/* Portfolio stylesheet — all 10 pages. Original cascade order preserved within each page. */

/* Shared global font and animation definitions */
@keyframes p2-marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}
@keyframes p2-fade-up {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes sp-float {
  0%,100% {
    transform:translateY(0)
  }
  50% {
    transform:translateY(-.7cqw)
  }
}
@keyframes cp-dot {
  0%,100% {
    opacity:.25
  }
  50% {
    opacity:.9
  }
}
@keyframes cp-spin {
  to {
    transform:rotate(360deg)
  }
}
@keyframes a-run {
  0% {
    left:0;
    opacity:1
  }
  100% {
    left:calc(100% - 8px);
    opacity:1
  }
}
@keyframes acDriftA {
  to {
    transform:translate(55%,35%) scale(1.2)
  }
}
@keyframes acDriftB {
  to {
    transform:translate(-50%,-32%) scale(1.18)
  }
}
@keyframes acDriftC {
  to {
    transform:translate(-20%,-55%) scale(.86)
  }
}
@font-face {
  font-family: "Switzer";
  src: url("./fonts/Switzer-Light.otf") format("opentype");
  font-weight: 300;
}
@font-face {
  font-family: "Switzer";
