  font-weight: 500;
}
@font-face {
  font-family: "Switzer";
  src: url("./fonts/Switzer-Bold.otf") format("opentype");
  font-weight: 700;
}
@keyframes p2-marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
@keyframes p2-fade-up {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: none; }
}
@keyframes sp-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-.7cqw)}}
@keyframes a-run{0%{left:0;opacity:1}100%{left:calc(100% - 8px);opacity:1}}
@keyframes hxbob{50%{transform:translateY(-.5em)}}
@keyframes hxbl{50%{opacity:0}}
@keyframes hxbar{to{transform:scaleX(1)}}
@keyframes smIn{from{opacity:0;transform:translateY(8px)}}

