  grid-template-columns: 1fr auto;
  gap: 10px;
}
.password-row input {
  width: 100%;
  height: 48px;
  padding: 0 16px;
  border: 1px solid rgba(0, 0, 0, 0.16);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.64);
  font-family: inherit;
