  border-radius: 8px;
  background: #111111;
  color: #ffffff;
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition:
    opacity 0.2s ease,
    transform 0.2s ease;
}
.password-row button:hover:not(:disabled) {
  transform: translateY(-1px);
}
