/* Original: project-v2.css */


/* =========================================================
   PROJECT V2 â€” Cinematic, video-led project page treatment
   Layered on top of styles.css (keeps nav/footer chrome)
========================================================= */

:scope {
  --p2-ink: #0a0a0a;
  --p2-ink-soft: #555252;
  --p2-mute: #8a847b;
  --p2-line: #ededed;
  --p2-cream: #efe9e1;
  --p2-cream-deep: #e6dfd4;
  --p2-paper: #f6f4ef;
  --p2-mono: "Neue Haas Grotesk Display Pro", "Neue Haas Grotesk", "Helvetica Neue", Arial, sans-serif, "Switzer", sans-serif;
  --p2-display: "Switzer", sans-serif;
}
/* keep nav over hero */
.p2-page {
  color: var(--p2-ink);
}
.p2-page main {
  overflow: visible;
}
/* container */
.p2-wrap {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding-left: 100px;
  padding-right: 100px;
}
@media (max-width: 1100px) {
  .p2-wrap {
    padding-left: 40px;
    padding-right: 40px;
  }
}
@media (max-width: 700px) {
  .p2-wrap {
    padding-left: 24px;
    padding-right: 24px;
  }
}
/* reveal animation */
.p2-rise {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1), transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}
.p2-rise.is-in {
  opacity: 1;
  transform: none;
}
/* ============ HERO ============ */

.p2-hero {
  position: relative;
  padding-top: 64px;
  padding-bottom: 0;
  background: #ffffff;
}
.p2-hero-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  font-family: var(--p2-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--p2-ink-soft);
  text-transform: uppercase;
  margin-bottom: 56px;
}
.p2-hero-meta .slash {
  color: var(--p2-mute);
}
.p2-hero-meta .meta-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.p2-hero-meta .dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #0a0a0a;
  display: inline-block;
}
.p2-hero-title {
  font-size: clamp(48px, 7.2vw, 104px);
  line-height: 0.96;
  font-weight: 400;
  letter-spacing: -0.025em;
  margin-bottom: 32px;
  text-wrap: balance;
}
.p2-hero-title em {
  font-style: normal;
  font-weight: 300;
}
.p2-hero-lede {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  padding-bottom: 48px;
}
.p2-hero-sub {
  font-size: clamp(22px, 2vw, 28px);
  line-height: 1.25;
  font-weight: 300;
  color: var(--p2-ink);
  max-width: 540px;
}
.p2-hero-detail {
  font-size: 14px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
  max-width: 460px;
  justify-self: end;
}
.p2-hero-detail strong {
  color: var(--p2-ink);
  font-weight: 600;
}
.p2-hero-detail p + p {
  margin-top: 8px;
}
@media (max-width: 900px) {
  .p2-hero-lede {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .p2-hero-detail {
    justify-self: start;
  }
}
/* ============ HERO VIDEO ============ */

.p2-hero-video {
  position: relative;
  width: calc(100% - 240px);
  max-width: 1100px;
  margin: 0 auto;
  aspect-ratio: 16 / 9;
  background: #04182b;
  overflow: hidden;
  border-radius: 24px;
}
.p2-video-fallback.hidden {
  display: none !important;
}
.p2-hero-video video,
.p2-hero-video .p2-video-fallback {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  background: #04182b;
}
.p2-video-fallback {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #efe9e1 0%, #e6dfd4 50%, #d9d0c1 100%);
  font-family: var(--p2-mono);
  font-size: 14px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #7a6b58;
}
.p2-video-fallback .fb-inner {
  text-align: center;
}
.p2-video-fallback .fb-play {
  width: 88px;
  height: 88px;
  border: 1.5px solid #7a6b58;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
}
.p2-video-fallback .fb-play::after {
  content: "";
  width: 0;
  height: 0;
  border-left: 18px solid #7a6b58;
  border-top: 12px solid transparent;
  border-bottom: 12px solid transparent;
  margin-left: 4px;
}
.p2-hero-video .p2-corner {
  position: absolute;
  top: 16px;
  left: 16px;
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  color: #ffffff;
  background: rgba(0,0,0,0.5);
  padding: 6px 10px;
  text-transform: uppercase;
  z-index: 2;
}
.p2-hero-video .p2-corner.right {
  left: auto;
  right: 16px;
}
@media (max-width: 900px) {
  .p2-hero-video {
    width: calc(100% - 80px);
  }
}
@media (max-width: 700px) {
  .p2-hero-video {
    width: calc(100% - 48px);
    border-radius: 16px;
  }
}
/* ============ STAT TICKER ============ */

.p2-stats {
  background: #0a0a0a;
  color: #fff;
  padding-top: 80px;
  padding-bottom: 80px;
  margin-top: 80px;
}
.p2-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-top: 1px solid rgba(255,255,255,0.12);
  border-bottom: 1px solid rgba(255,255,255,0.12);
}
.p2-stat {
  padding: 40px 32px 40px 0;
  border-right: 1px solid rgba(255,255,255,0.12);
  position: relative;
}
.p2-stat:last-child {
  border-right: none;
}
.p2-stat .stat-no {
