/* ============ MARQUEE ============ */

.p2-marquee {
  background: #0a0a0a;
  color: #fff;
  padding: 24px 0;
  margin-top: -1px;
  overflow: hidden;
  border-top: 1px solid rgba(255,255,255,0.12);
