}
.sp-hero-art .p2-corner {
  background:rgba(35,38,29,.85)
}
@media(max-width:1100px) {
  .sp-hero-art .p2-corner.right {
    display:none
  }
}
.sp-hero-art .ph {
  position:absolute;
  --pw:20cqw;
  top:6.5cqw;
  animation:sp-float 8s ease-in-out infinite
}
.sp-hero-art .ph.h1 {
  left:12cqw
}
.sp-hero-art .ph.h2 {
  left:40cqw;
  animation-delay:-2.6s
}
.sp-hero-art .ph.h3 {
  left:68cqw;
  animation-delay:-5.2s
}
.sp-hl {
  position:absolute;
  top:2.4cqw;
  width:20cqw;
  text-align:center;
  font-family:var(--p2-mono);
  font-size:max(9px,1.05cqw);
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-ink)
}
.sp-hsys {
  position:absolute;
  left:12cqw;
  right:12cqw;
  bottom:2.2cqw;
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:2cqw;
  background:#141414;
  color:#fff;
