}
.sp-hsys span {
  font-family:var(--p2-mono);
  font-size:max(9px,1cqw);
  letter-spacing:.06em;
  text-transform:uppercase;
  color:rgba(255,255,255,.65)
}
.sp-hsys b {
  font-size:max(10px,1.35cqw);
