}
@media(max-width:700px) {
  .sp-hsys span {
    display:none
  }
}

.sp-fc {
  position:absolute;
  z-index:4;
  background:rgba(255,255,255,.95);
  border-radius:1.2cqw;
  padding:1.1cqw 1.4cqw;
  display:flex;
  align-items:center;
  gap:1cqw;
  box-shadow:0 2cqw 3cqw -1.5cqw rgba(0,0,0,.22);
  font-size:max(10px,1.15cqw);
  line-height:1.3
}
.sp-fc .ok {
  width:2.6cqw;
  height:2.6cqw;
  border-radius:50%;
  background:#36412a;
  color:#fff;
  display:grid;
  place-items:center;
  flex-shrink:0
}
.sp-fc .ok svg {
  width:1.3cqw;
  height:1.3cqw;
  fill:none;
  stroke:currentColor;
  stroke-width:2.4
}
.sp-fc b {
  display:block;
  font-weight:500
}
.sp-fc small {
  color:var(--p2-mute)
}
.sp-fc.a {
  left:8cqw;
  bottom:12cqw
}
.sp-fc.b {
  right:7cqw;
  top:14cqw
}
.sp-fc.b .ok {
  background:#9a7b4f
}
/* ---------- unify ---------- */
.sp-unify {
  background:var(--sp-sand);
  border-radius:18px;
  padding:32px;
  position:relative;
  overflow:hidden
}
.sp-unify-head {
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:16px;
  margin-bottom:8px;
  flex-wrap:wrap
}
.sp-ustage {
  container-type:inline-size;
  position:relative;
  aspect-ratio:16/8
}
.sp-lay {
  position:absolute;
  inset:0;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:5cqw;
  transition:opacity .8s cubic-bezier(.22,1,.36,1),scale .8s cubic-bezier(.22,1,.36,1)
}
.sp-lay .ph {
  --pw:19cqw
}
.sp-lay.after .ph {
  --pw:21.5cqw
}
.sp-unify[data-state="before"] .after,.sp-unify[data-state="after"] .before {
  opacity:0;
  scale:.94;
  pointer-events:none
}
.sp-ann {
  position:absolute;
  width:24cqw;
  font-size:max(11px,1.35cqw);
  line-height:1.4;
  color:var(--p2-ink-soft)
}
.sp-ann b {
  display:block;
  font-family:var(--p2-mono);
  font-size:max(9px,1cqw);
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--p2-ink);
  font-weight:500;
  margin-bottom:.5cqw
}
.sp-ann.l {
  left:4cqw;
  top:30%;
  text-align:right
}
.sp-ann.r {
  right:4cqw;
  top:55%
}
.sp-ann::after {
  content:"";
  position:absolute;
  top:1cqw;
  height:1px;
  width:8cqw;
  background:var(--p2-ink)
}
.sp-ann.l::after {
  left:calc(100% + 1.5cqw)
}
.sp-ann.r::after {
  right:calc(100% + 1.5cqw)
}
/* ---------- methodology art ---------- */
.sp-art {
  container-type:inline-size;
  background:var(--sp-sand);
  border-radius:18px;
  aspect-ratio:4/3;
  position:relative;
  overflow:hidden
}
.sp-art .cap {
  position:absolute;
  left:16px;
  bottom:14px;
  font-family:var(--p2-mono);
  font-size:10px;
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--p2-ink-soft);
  z-index:5
}
/* board */
.sp-board {
  position:absolute;
  inset:0;
  background:var(--sp-sand);
  background-image:radial-gradient(circle at 1px 1px,rgba(0,0,0,.09) 1px,transparent 0);
  background-size:16px 16px
}
.sp-tool {
  position:absolute;
  top:2.4cqw;
  left:50%;
  translate:-50% 0;
  display:flex;
  gap:1.6cqw;
  background:#fff;
  border-radius:1.4cqw;
  padding:1cqw 1.8cqw;
  box-shadow:0 .6cqw 2cqw rgba(0,0,0,.08);
  z-index:3
}
.sp-tool i {
  width:2.2cqw;
  height:2.2cqw;
  border-radius:.5cqw;
  background:#e8e4dc
}
.sp-tool i:nth-child(3) {
  background:#f6e3a6
}
.sp-tool i:nth-child(4) {
  background:#141414;
  border-radius:50%
}
.sp-sec {
  position:absolute;
  top:10cqw;
  height:52cqw;
  width:22.5cqw;
  border-radius:1.4cqw;
  opacity:0;
  scale:.97;
  transition:opacity .5s .8s,scale .5s .8s
}
.sp-sec span {
  position:absolute;
  top:-.2cqw;
  left:1.2cqw;
  translate:0 -50%;
  font-size:max(9px,1.45cqw);
  font-weight:500;
  padding:.5cqw 1.1cqw;
  border-radius:.7cqw;
  color:#fff;
  white-space:nowrap
}
.is-active .sp-sec {
  opacity:1;
  scale:1
}
.sp-st {
  position:absolute;
  width:19cqw;
  min-height:15cqw;
  padding:1.4cqw;
  font-size:max(9px,1.55cqw);
  line-height:1.3;
  box-shadow:0 .5cqw 1.2cqw -.4cqw rgba(0,0,0,.22),0 .1cqw .2cqw rgba(0,0,0,.08);
  border-radius:.4cqw;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  gap:1cqw;
  transition:left 1s cubic-bezier(.22,1,.36,1),top 1s cubic-bezier(.22,1,.36,1),rotate 1s;
  z-index:2;
  color:#1d1a15
}
.sp-st small {
  font-size:max(8px,1.2cqw);
  color:rgba(0,0,0,.5);
  display:flex;
  align-items:center;
  gap:.6cqw
}
.sp-st small::before {
  content:"";
  width:1.6cqw;
  height:1.6cqw;
  border-radius:50%;
  background:currentColor;
  opacity:.5
}
.sp-cur {
  position:absolute;
  z-index:4;
  left:60%;
  top:70%;
  transition:left 1.4s cubic-bezier(.22,1,.36,1),top 1.4s cubic-bezier(.22,1,.36,1);
  pointer-events:none
}
.sp-cur svg {
  width:2.4cqw;
  height:2.4cqw;
  display:block
}
.sp-cur span {
  display:inline-block;
  margin:.2cqw 0 0 1.6cqw;
  background:#c94235;
  color:#fff;
  font-size:max(9px,1.3cqw);
  padding:.3cqw .9cqw;
  border-radius:.6cqw .6cqw .6cqw 0
}
/* IA wire */
.sp-ia2 .ph {
  --pw:25cqw;
  position:absolute;
  left:50%;
  top:9cqw;
  translate:-50% 0
}
.sp-strip {
  position:absolute;
  top:3cqw;
  left:3.4cqw;
  display:flex;
  align-items:center;
  gap:1cqw;
  font-size:max(10px,1.4cqw)
}
.sp-strip s {
  color:var(--p2-mute)
}
.sp-strip b {
  font-weight:500
}
.sp-co {
  position:absolute;
  width:27cqw;
  font-size:max(10px,1.45cqw);
  line-height:1.35;
  color:var(--p2-ink-soft);
  opacity:0;
  translate:0 1cqw;
  transition:opacity .5s,translate .5s
}
.sp-co b {
  display:block;
  color:var(--p2-ink);
  font-weight:500;
  margin-bottom:.3cqw
}
.sp-co .n {
  font-family:var(--p2-mono);
  font-size:max(9px,1.1cqw);
  color:var(--p2-mute);
  letter-spacing:.1em
}
.sp-co::after {
  content:"";
  position:absolute;
  top:1.1cqw;
  height:1px;
  background:var(--p2-ink);
  width:var(--ln,9cqw)
}
.sp-co::before {
  content:"";
  position:absolute;
  top:.6cqw;
  width:1.1cqw;
  height:1.1cqw;
  border-radius:50%;
  background:var(--sp-gold);
  border:2px solid #fff;
  box-shadow:0 0 0 1px var(--p2-ink)
}
.sp-co.l {
  left:3.4cqw;
  text-align:right
}
.sp-co.l::after {
  left:calc(100% + 1cqw)
}
.sp-co.l::before {
  left:calc(100% + 1cqw + var(--ln,9cqw))
}
.sp-co.r {
  right:3.4cqw
}
.sp-co.r::after {
  right:calc(100% + 1cqw)
}
.sp-co.r::before {
  right:calc(100% + 1cqw + var(--ln,9cqw))
}
.is-active .sp-co {
  opacity:1;
  translate:0 0
}
.is-active .sp-co:nth-of-type(2) {
  transition-delay:.15s
}
.is-active .sp-co:nth-of-type(3) {
  transition-delay:.3s
}
.is-active .sp-co:nth-of-type(4) {
  transition-delay:.45s
}
/* system sheet */
.sp-sys {
  position:absolute;
  inset:3.4cqw 3.4cqw 8cqw;
  display:grid;
  grid-template-columns:1fr 1fr;
  grid-template-rows:1fr 1fr;
  gap:2cqw
}
.sp-fr {
  background:#fff;
  border-radius:1.6cqw;
  padding:2.2cqw;
