  flex-direction:column;
  gap:1.6cqw;
  box-shadow:0 1cqw 2.4cqw -1.4cqw rgba(0,0,0,.18);
  opacity:0;
  translate:0 1.5cqw;
  transition:opacity .5s,translate .5s;
  min-width:0;
  overflow:hidden
}
.is-active .sp-fr {
  opacity:1;
  translate:0 0
}
.is-active .sp-fr:nth-child(2) {
