  .p2-page .p2-hero-title { font-size: clamp(32px, 8vw, 45px) !important; }
  .p2-page .p2-hero-meta, .p2-page .p2-eyebrow { font-size: 10px !important; }
  /* Place the artwork immediately after the heading, before lengthy explanations. */
  .p2-page .p2-hero { display: flex !important; flex-direction: column !important; }
  .p2-page .p2-hero > .p2-wrap { display: contents !important; }
  .p2-page .p2-hero-meta { order: 0; margin: 10px 5% 8px !important; }
  .p2-page .p2-hero-title { order: 1; margin: 0 5% 10px !important; }
  .p2-page .p2-hero-video { order: 2; width: 100% !important; margin: 4px 0 16px !important; }
  .p2-page .portfolio-public-note, .p2-page .pt-public-note { order: 3; margin: 0 5% 12px !important; }
  .p2-page .cp-headline, .p2-page .sp-positioning-line { order: 4; margin: 0 5% 12px !important; }
  .p2-page .p2-hero-lede { order: 5; margin: 0 5% 22px !important; }
  .p2-page .sp-hero-art .sp-hl { z-index: 30 !important; font-size: 9px !important; max-width: 31%; white-space: normal !important; }
  .p2-page .sp-out .sp-eq { grid-template-columns: 1fr !important; }
  .p2-page .sp-out .sp-op { justify-self: center !important; }
  .p2-page .sp-out .sp-col { width: 100%; }
  .p2-page .p2-section-head, .p2-page .p2-section-head > * { min-width: 0; }
  .p2-page .p2-hero-lede { display: block !important; }
  .p2-page .p2-hero-detail { margin-top: 12px; }
  .p2-page .sp-hero-art .sp-hl { top: 6px !important; }
  .p2-page .p2-section { overflow-x: clip; }
  .ac-two .p2-section:last-of-type, .ac-two .p2-section:has(.sp-out) { padding-bottom: 32px !important; }
  .p2-page .portfolio-footer { margin-top: 24px !important; }
}

