/* =========================
   PASSWORD OVERLAY
========================= */

.password-overlay {
  position: fixed;
  inset: 0;
  background: rgba(246, 244, 239, 0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 99999;
}
.password-overlay.hidden {
  display: none !important;
}
.password-container {
  width: 100%;
  max-width: 520px;
  padding: 0 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}
.password-container h3 {
  font-size: 34px;
  line-height: 1.12;
  font-weight: 400;
  letter-spacing: -0.03em;
  margin-bottom: 28px;
}
.password-row {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
}
.password-row input {
  width: 100%;
  height: 48px;
  padding: 0 16px;
  border: 1px solid rgba(0, 0, 0, 0.16);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.64);
  font-family: inherit;
  font-size: 14px;
  font-weight: 400;
  color: #111111;
  outline: none;
  transition:
    border-color 0.2s ease,
    background 0.2s ease;
}
.password-row input::placeholder {
  color: rgba(0, 0, 0, 0.45);
}
.password-row input:focus {
  border-color: rgba(0, 0, 0, 0.55);
  background: rgba(255, 255, 255, 0.86);
}
.password-row button {
  height: 48px;
  padding: 0 22px;
  border: 1px solid #111111;
  border-radius: 8px;
  background: #111111;
  color: #ffffff;
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition:
    opacity 0.2s ease,
    transform 0.2s ease;
}
.password-row button:hover:not(:disabled) {
  transform: translateY(-1px);
}
.password-row button:disabled {
  opacity: 0.28;
  cursor: not-allowed;
}
.error-message {
  width: 100%;
  min-height: 12px;
  margin-top: 10px;
  text-align: left;
  color: #D14B4B;
  font-size: 12px;
}
.password-link {
  margin-top: 12px;
  font-size: 13px;
  line-height: 1.4;
  font-weight: 500;
  color: #555252;
  text-decoration: underline;
  text-underline-offset: 3px;
  transition: opacity 0.2s ease;
}
.password-link:hover {
  opacity: 0.6;
}
.password-close {
  position: absolute;
  top: 28px;
  right: 32px;
  background: none;
  border: none;
  font-size: 24px;
  line-height: 1;
  font-weight: 300;
  cursor: pointer;
}
@media (max-width: 700px) {
  .password-container {
    max-width: 100%;
    padding: 0 24px;
