/* Original: project-v2.css */


/* =========================================================
   PROJECT V2 â€” Cinematic, video-led project page treatment
   Layered on top of styles.css (keeps nav/footer chrome)
========================================================= */

:scope {
  --p2-ink: #0a0a0a;
  --p2-ink-soft: #555252;
  --p2-mute: #8a847b;
  --p2-line: #ededed;
  --p2-cream: #efe9e1;
  --p2-cream-deep: #e6dfd4;
  --p2-paper: #f6f4ef;
  --p2-mono: "Neue Haas Grotesk Display Pro", "Neue Haas Grotesk", "Helvetica Neue", Arial, sans-serif, "Switzer", sans-serif;
  --p2-display: "Switzer", sans-serif;
}
/* keep nav over hero */
.p2-page {
  color: var(--p2-ink);
}
.p2-page main {
  overflow: visible;
}
/* container */
.p2-wrap {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding-left: 100px;
  padding-right: 100px;
}
@media (max-width: 1100px) {
  .p2-wrap {
    padding-left: 40px;
    padding-right: 40px;
  }
}
@media (max-width: 700px) {
  .p2-wrap {
    padding-left: 24px;
    padding-right: 24px;
  }
}
/* reveal animation */
.p2-rise {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1), transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}
.p2-rise.is-in {
  opacity: 1;
  transform: none;
}
/* ============ HERO ============ */

.p2-hero {
  position: relative;
  padding-top: 64px;
  padding-bottom: 0;
  background: #ffffff;
}
.p2-hero-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  font-family: var(--p2-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--p2-ink-soft);
  text-transform: uppercase;
  margin-bottom: 56px;
}
.p2-hero-meta .slash {
  color: var(--p2-mute);
}
.p2-hero-meta .meta-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.p2-hero-meta .dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #0a0a0a;
  display: inline-block;
}
.p2-hero-title {
  font-size: clamp(48px, 7.2vw, 104px);
  line-height: 0.96;
  font-weight: 400;
  letter-spacing: -0.025em;
  margin-bottom: 32px;
  text-wrap: balance;
}
.p2-hero-title em {
  font-style: normal;
  font-weight: 300;
}
.p2-hero-lede {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  padding-bottom: 48px;
}
.p2-hero-sub {
  font-size: clamp(22px, 2vw, 28px);
  line-height: 1.25;
  font-weight: 300;
  color: var(--p2-ink);
  max-width: 540px;
}
.p2-hero-detail {
  font-size: 14px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
  max-width: 460px;
  justify-self: end;
}
.p2-hero-detail strong {
  color: var(--p2-ink);
  font-weight: 600;
}
.p2-hero-detail p + p {
  margin-top: 8px;
}
@media (max-width: 900px) {
  .p2-hero-lede {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .p2-hero-detail {
    justify-self: start;
  }
}
/* ============ HERO VIDEO ============ */

.p2-hero-video {
  position: relative;
  width: calc(100% - 240px);
  max-width: 1100px;
  margin: 0 auto;
  aspect-ratio: 16 / 9;
  background: #04182b;
  overflow: hidden;
  border-radius: 24px;
}
.p2-video-fallback.hidden {
  display: none !important;
}
.p2-hero-video video,
.p2-hero-video .p2-video-fallback {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  background: #04182b;
}
.p2-video-fallback {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #efe9e1 0%, #e6dfd4 50%, #d9d0c1 100%);
  font-family: var(--p2-mono);
  font-size: 14px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #7a6b58;
}
.p2-video-fallback .fb-inner {
  text-align: center;
}
.p2-video-fallback .fb-play {
  width: 88px;
  height: 88px;
  border: 1.5px solid #7a6b58;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
}
.p2-video-fallback .fb-play::after {
  content: "";
  width: 0;
  height: 0;
  border-left: 18px solid #7a6b58;
  border-top: 12px solid transparent;
  border-bottom: 12px solid transparent;
  margin-left: 4px;
}
.p2-hero-video .p2-corner {
  position: absolute;
  top: 16px;
  left: 16px;
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  color: #ffffff;
  background: rgba(0,0,0,0.5);
  padding: 6px 10px;
  text-transform: uppercase;
  z-index: 2;
}
.p2-hero-video .p2-corner.right {
  left: auto;
  right: 16px;
}
@media (max-width: 900px) {
  .p2-hero-video {
    width: calc(100% - 80px);
  }
}
@media (max-width: 700px) {
  .p2-hero-video {
    width: calc(100% - 48px);
    border-radius: 16px;
  }
}
/* ============ STAT TICKER ============ */

.p2-stats {
  background: #0a0a0a;
  color: #fff;
  padding-top: 80px;
  padding-bottom: 80px;
  margin-top: 80px;
}
.p2-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-top: 1px solid rgba(255,255,255,0.12);
  border-bottom: 1px solid rgba(255,255,255,0.12);
}
.p2-stat {
  padding: 40px 32px 40px 0;
  border-right: 1px solid rgba(255,255,255,0.12);
  position: relative;
}
.p2-stat:last-child {
  border-right: none;
}
.p2-stat .stat-no {
  font-family: var(--p2-mono);
  font-size: 11px;
  color: rgba(255,255,255,0.4);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin-bottom: 24px;
}
.p2-stat .stat-num {
  font-size: clamp(48px, 6vw, 76px);
  line-height: 0.95;
  letter-spacing: -0.025em;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  margin-bottom: 16px;
}
.p2-stat .stat-num .unit {
  font-size: 0.5em;
  margin-left: 0.05em;
  color: rgba(255,255,255,0.65);
}
.p2-stat .stat-label {
  font-size: 13px;
  line-height: 1.4;
  color: rgba(255,255,255,0.65);
}
@media (max-width: 900px) {
  .p2-stats-grid {
    grid-template-columns: 1fr 1fr;
  }
  .p2-stat:nth-child(2) {
    border-right: none;
  }
  .p2-stat:nth-child(1), .p2-stat:nth-child(2) {
    border-bottom: 1px solid rgba(255,255,255,0.12);
  }
}
@media (max-width: 560px) {
  .p2-stats-grid {
    grid-template-columns: 1fr;
  }
  .p2-stat {
    border-right: none;
    border-bottom: 1px solid rgba(255,255,255,0.12);
    padding: 28px 0;
  }
  .p2-stat:last-child {
    border-bottom: none;
  }
}
/* ============ MARQUEE ============ */

.p2-marquee {
  background: #0a0a0a;
  color: #fff;
  padding: 24px 0;
  margin-top: -1px;
  overflow: hidden;
  border-top: 1px solid rgba(255,255,255,0.12);
}
.p2-marquee-track {
  display: inline-flex;
  align-items: center;
  gap: 56px;
  white-space: nowrap;
  animation: p2-marquee 38s linear infinite;
  font-family: var(--p2-mono);
  font-size: 13px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.7);
}
.p2-marquee-track span.dot {
  width: 4px;
  height: 4px;
  background: rgba(255,255,255,0.3);
  border-radius: 50%;
  display: inline-block;
}
.p2-marquee-track strong {
  color: #fff;
  font-weight: 600;
}

/* ============ SECTION HEADERS ============ */

.p2-section {
  padding-top: 120px;
  padding-bottom: 0;
}
.p2-section-head {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  margin-bottom: 64px;
}
.p2-eyebrow {
  font-family: var(--p2-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--p2-mute);
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}
.p2-eyebrow .num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border: 1px solid var(--p2-mute);
  border-radius: 50%;
  font-size: 10px;
}
.p2-section-title {
  font-size: clamp(34px, 4.4vw, 56px);
  line-height: 1.05;
  letter-spacing: -0.02em;
  font-weight: 400;
  max-width: 720px;
}
.p2-section-blurb {
  font-size: 16px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
  max-width: 460px;
  justify-self: end;
}
@media (max-width: 900px) {
  .p2-section-head {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .p2-section-blurb {
    justify-self: start;
  }
  .p2-section {
    padding-top: 80px;
  }
}
/* ============ DEVICE SHOWCASE ============ */

.p2-device {
  position: relative;
  background: var(--p2-cream);
  padding: 96px 0;
  overflow: hidden;
}
.p2-device-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  align-items: end;
}
.p2-device-tile {
  background: #ffffff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 30px 60px -30px rgba(0,0,0,0.18);
  aspect-ratio: 9/19;
  position: relative;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}
.p2-device-tile.center {
  transform: translateY(-40px);
}
.p2-device-tile.right {
  transform: translateY(20px);
}
.p2-device-tile:hover {
  transform: translateY(-60px);
}
.p2-device-tile.right:hover {
  transform: translateY(0);
}
.p2-device-tile.left:hover {
  transform: translateY(-20px);
}
.p2-device-tile img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.p2-device-tile video {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
  display: block;
  background: #000;
}
.p2-device-tag {
  position: absolute;
  top: 16px;
  left: 16px;
  font-family: var(--p2-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(0,0,0,0.55);
  background: rgba(255,255,255,0.9);
  padding: 5px 9px;
  border-radius: 999px;
  z-index: 2;
}
@media (max-width: 900px) {
  .p2-device-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .p2-device-tile.center, .p2-device-tile.right {
    transform: none;
  }
  .p2-device-tile {
    aspect-ratio: 16/9;
  }
}
/* ============ INTERACTIVE BILINGUAL SANDBOX ============ */

.p2-bili {
  padding-top: 120px;
  padding-bottom: 120px;
}
.p2-bili-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--p2-line);
}
.p2-bili-hint {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--p2-mute);
}
.p2-toggle {
  display: inline-flex;
  background: #f2f2f2;
  border: 1px solid var(--p2-line);
  border-radius: 999px;
  padding: 4px;
  position: relative;
}
.p2-toggle button {
  position: relative;
  z-index: 1;
  background: none;
  border: none;
  cursor: pointer;
  padding: 10px 20px;
  font-family: var(--p2-mono);
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--p2-mute);
  border-radius: 999px;
  transition: color 0.3s ease;
}
.p2-toggle button[aria-pressed="true"] {
  color: #fff;
}
.p2-toggle .p2-toggle-pill {
  position: absolute;
  top: 4px;
  bottom: 4px;
  left: 4px;
  width: calc(50% - 4px);
  background: #0a0a0a;
  border-radius: 999px;
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.p2-toggle[data-dir="rtl"] .p2-toggle-pill {
  transform: translateX(100%);
}
.p2-bili-stage {
  display: grid;
  grid-template-columns: 380px 1fr;
  gap: 56px;
  align-items: start;
}
@media (max-width: 900px) {
  .p2-bili-stage {
    grid-template-columns: 1fr;
    gap: 32px;
  }
}
.p2-bili-spec {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.p2-bili-spec h3 {
  font-size: 24px;
  line-height: 1.2;
  font-weight: 400;
  letter-spacing: -0.01em;
}
.p2-bili-spec p {
  font-size: 14px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
}
.p2-spec-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  border-top: 1px solid var(--p2-line);
}
.p2-spec-list li {
  display: grid;
  grid-template-columns: 88px 1fr;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--p2-line);
  font-size: 13px;
  color: var(--p2-ink-soft);
  align-items: center;
}
.p2-spec-list li .k {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--p2-mute);
}
.p2-spec-list li .v {
  font-variant-numeric: tabular-nums;
  transition: opacity 0.4s ease;
}
.p2-bili-card-wrap {
  background: var(--p2-paper);
  border-radius: 18px;
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 520px;
  position: relative;
  overflow: hidden;
}
.p2-bili-card-wrap::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 1px 1px, rgba(0,0,0,0.06) 1px, transparent 0);
  background-size: 24px 24px;
  opacity: 0.5;
  pointer-events: none;
}
.p2-bili-card {
  width: 100%;
  max-width: 380px;
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 30px 60px -30px rgba(0,0,0,0.25), 0 2px 6px rgba(0,0,0,0.04);
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
