.sp-unify {
  background:var(--sp-sand);
  border-radius:18px;
  padding:32px;
  position:relative;
  overflow:hidden
}
.sp-unify-head {
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:16px;
  margin-bottom:8px;
  flex-wrap:wrap
}
