  container-type:inline-size;
  position:relative;
  aspect-ratio:16/8
}
.sp-lay {
  position:absolute;
  inset:0;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:5cqw;
  transition:opacity .8s cubic-bezier(.22,1,.36,1),scale .8s cubic-bezier(.22,1,.36,1)
}
.sp-lay .ph {
  --pw:19cqw
}
.sp-lay.after .ph {
  --pw:21.5cqw
}
.sp-unify[data-state="before"] .after,.sp-unify[data-state="after"] .before {
  opacity:0;
  scale:.94;
  pointer-events:none
}
.sp-ann {
  position:absolute;
  width:24cqw;
  font-size:max(11px,1.35cqw);
  line-height:1.4;
  color:var(--p2-ink-soft)
}
