  display:block;
  font-family:var(--p2-mono);
  font-size:max(9px,1cqw);
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--p2-ink);
  font-weight:500;
  margin-bottom:.5cqw
}
.sp-ann.l {
  left:4cqw;
  top:30%;
  text-align:right
}
.sp-ann.r {
  right:4cqw;
  top:55%
}
.sp-ann::after {
  content:"";
  position:absolute;
  top:1cqw;
  height:1px;
  width:8cqw;
  background:var(--p2-ink)
}
.sp-ann.l::after {
  left:calc(100% + 1.5cqw)
}
.sp-ann.r::after {
  right:calc(100% + 1.5cqw)
}
/* ---------- methodology art ---------- */
.sp-art {
  container-type:inline-size;
  background:var(--sp-sand);
  border-radius:18px;
  aspect-ratio:4/3;
  position:relative;
  overflow:hidden
}
.sp-art .cap {
  position:absolute;
  left:16px;
  bottom:14px;
  font-family:var(--p2-mono);
  font-size:10px;
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--p2-ink-soft);
  z-index:5
}
/* board */
.sp-board {
  position:absolute;
  inset:0;
  background:var(--sp-sand);
  background-image:radial-gradient(circle at 1px 1px,rgba(0,0,0,.09) 1px,transparent 0);
  background-size:16px 16px
}
.sp-tool {
  position:absolute;
  top:2.4cqw;
  left:50%;
  translate:-50% 0;
  display:flex;
  gap:1.6cqw;
  background:#fff;
  border-radius:1.4cqw;
  padding:1cqw 1.8cqw;
  box-shadow:0 .6cqw 2cqw rgba(0,0,0,.08);
  z-index:3
}
.sp-tool i {
  width:2.2cqw;
  height:2.2cqw;
  border-radius:.5cqw;
  background:#e8e4dc
}
.sp-tool i:nth-child(3) {
  background:#f6e3a6
}
.sp-tool i:nth-child(4) {
  background:#141414;
  border-radius:50%
}
.sp-sec {
  position:absolute;
  top:10cqw;
  height:52cqw;
  width:22.5cqw;
  border-radius:1.4cqw;
  opacity:0;
  scale:.97;
  transition:opacity .5s .8s,scale .5s .8s
}
.sp-sec span {
  position:absolute;
  top:-.2cqw;
  left:1.2cqw;
  translate:0 -50%;
  font-size:max(9px,1.45cqw);
  font-weight:500;
  padding:.5cqw 1.1cqw;
  border-radius:.7cqw;
  color:#fff;
  white-space:nowrap
}
.is-active .sp-sec {
  opacity:1;
  scale:1
}
.sp-st {
  position:absolute;
  width:19cqw;
  min-height:15cqw;
  padding:1.4cqw;
  font-size:max(9px,1.55cqw);
  line-height:1.3;
  box-shadow:0 .5cqw 1.2cqw -.4cqw rgba(0,0,0,.22),0 .1cqw .2cqw rgba(0,0,0,.08);
  border-radius:.4cqw;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  gap:1cqw;
  transition:left 1s cubic-bezier(.22,1,.36,1),top 1s cubic-bezier(.22,1,.36,1),rotate 1s;
  z-index:2;
  color:#1d1a15
}
.sp-st small {
  font-size:max(8px,1.2cqw);
  color:rgba(0,0,0,.5);
  display:flex;
  align-items:center;
  gap:.6cqw
}
.sp-st small::before {
  content:"";
  width:1.6cqw;
  height:1.6cqw;
  border-radius:50%;
  background:currentColor;
  opacity:.5
}
.sp-cur {
  position:absolute;
  z-index:4;
  left:60%;
  top:70%;
  transition:left 1.4s cubic-bezier(.22,1,.36,1),top 1.4s cubic-bezier(.22,1,.36,1);
  pointer-events:none
}
.sp-cur svg {
  width:2.4cqw;
  height:2.4cqw;
  display:block
}
.sp-cur span {
  display:inline-block;
  margin:.2cqw 0 0 1.6cqw;
  background:#c94235;
  color:#fff;
  font-size:max(9px,1.3cqw);
  padding:.3cqw .9cqw;
  border-radius:.6cqw .6cqw .6cqw 0
}
/* IA wire */
.sp-ia2 .ph {
  --pw:25cqw;
  position:absolute;
  left:50%;
  top:9cqw;
  translate:-50% 0
}
.sp-strip {
  position:absolute;
  top:3cqw;
  left:3.4cqw;
  display:flex;
  align-items:center;
  gap:1cqw;
  font-size:max(10px,1.4cqw)
}
.sp-strip s {
  color:var(--p2-mute)
}
.sp-strip b {
  font-weight:500
}
.sp-co {
  position:absolute;
  width:27cqw;
  font-size:max(10px,1.45cqw);
  line-height:1.35;
  color:var(--p2-ink-soft);
  opacity:0;
  translate:0 1cqw;
  transition:opacity .5s,translate .5s
}
.sp-co b {
  display:block;
  color:var(--p2-ink);
  font-weight:500;
  margin-bottom:.3cqw
}
.sp-co .n {
  font-family:var(--p2-mono);
  font-size:max(9px,1.1cqw);
  color:var(--p2-mute);
  letter-spacing:.1em
}
.sp-co::after {
  content:"";
  position:absolute;
  top:1.1cqw;
  height:1px;
  background:var(--p2-ink);
  width:var(--ln,9cqw)
}
.sp-co::before {
  content:"";
  position:absolute;
  top:.6cqw;
  width:1.1cqw;
  height:1.1cqw;
  border-radius:50%;
  background:var(--sp-gold);
  border:2px solid #fff;
  box-shadow:0 0 0 1px var(--p2-ink)
}
.sp-co.l {
  left:3.4cqw;
  text-align:right
}
.sp-co.l::after {
  left:calc(100% + 1cqw)
}
.sp-co.l::before {
  left:calc(100% + 1cqw + var(--ln,9cqw))
}
.sp-co.r {
  right:3.4cqw
}
.sp-co.r::after {
  right:calc(100% + 1cqw)
}
.sp-co.r::before {
  right:calc(100% + 1cqw + var(--ln,9cqw))
}
.is-active .sp-co {
  opacity:1;
  translate:0 0
}
.is-active .sp-co:nth-of-type(2) {
  transition-delay:.15s
}
.is-active .sp-co:nth-of-type(3) {
  transition-delay:.3s
}
.is-active .sp-co:nth-of-type(4) {
  transition-delay:.45s
}
/* system sheet */
.sp-sys {
  position:absolute;
  inset:3.4cqw 3.4cqw 8cqw;
  display:grid;
  grid-template-columns:1fr 1fr;
  grid-template-rows:1fr 1fr;
  gap:2cqw
}
.sp-fr {
  background:#fff;
  border-radius:1.6cqw;
  padding:2.2cqw;
  display:flex;
  flex-direction:column;
  gap:1.6cqw;
  box-shadow:0 1cqw 2.4cqw -1.4cqw rgba(0,0,0,.18);
  opacity:0;
  translate:0 1.5cqw;
  transition:opacity .5s,translate .5s;
  min-width:0;
  overflow:hidden
}
.is-active .sp-fr {
  opacity:1;
  translate:0 0
}
.is-active .sp-fr:nth-child(2) {
  transition-delay:.12s
}
.is-active .sp-fr:nth-child(3) {
  transition-delay:.24s
}
.is-active .sp-fr:nth-child(4) {
  transition-delay:.36s
}
.sp-fl {
  display:flex;
  justify-content:space-between;
  font-family:var(--p2-mono);
  font-size:max(8px,1.15cqw);
  letter-spacing:.12em;
  text-transform:uppercase;
  color:var(--p2-mute)
}
.sp-sw {
  display:flex;
  gap:1cqw
}
.sp-sw i {
  flex:1;
  aspect-ratio:1;
  border-radius:50%;
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.08)
}
.sp-ty {
  display:flex;
  align-items:baseline;
  gap:1.4cqw
}
.sp-ty b {
  font-size:4cqw;
  font-weight:400;
  letter-spacing:-.03em;
  line-height:1
}
.sp-ty span {
  font-family:"IBM Plex Sans Arabic",sans-serif;
  font-size:3.4cqw;
  line-height:1
}
.sp-ty small {
  margin-left:auto;
  font-family:var(--p2-mono);
  font-size:max(8px,1.1cqw);
  color:var(--p2-mute)
}
.sp-at {
  display:flex;
  flex-wrap:wrap;
  gap:1cqw;
  align-items:center
}
.sp-b {
  font-size:max(9px,1.4cqw);
  padding:1cqw 1.8cqw;
  border-radius:99px;
  background:#141414;
  color:#fff;
  white-space:nowrap
}
.sp-b.g {
  background:transparent;
  color:#141414;
  box-shadow:inset 0 0 0 1px #141414
}
.sp-b.y {
  background:var(--sp-gold);
  color:#141414
}
.sp-tg {
  width:4.4cqw;
  height:2.5cqw;
  border-radius:99px;
  background:#141414;
  position:relative
}
.sp-tg::after {
  content:"";
  position:absolute;
  right:.35cqw;
  top:.35cqw;
  width:1.8cqw;
  height:1.8cqw;
  border-radius:50%;
  background:#fff
}
.sp-ck {
  width:2.5cqw;
  height:2.5cqw;
  border-radius:.6cqw;
  background:var(--sp-gold);
  display:grid;
  place-items:center
}
.sp-ck svg {
  width:1.6cqw;
  height:1.6cqw;
  fill:none;
  stroke:#141414;
  stroke-width:3
}
.sp-chip {
  font-size:max(9px,1.25cqw);
  padding:.7cqw 1.4cqw;
  border-radius:99px;
  background:rgba(212,165,72,.2);
  color:#7d5a10
}
.sp-in {
  display:flex;
  align-items:center;
  gap:1cqw;
  border:1px solid #e6e1d8;
  border-radius:1.2cqw;
  padding:1.2cqw 1.4cqw;
  font-size:max(9px,1.35cqw);
  color:var(--p2-mute)
}
.sp-in svg {
  width:1.8cqw;
  height:1.8cqw;
  fill:none;
  stroke:currentColor;
  stroke-width:2
}
.sp-in kbd {
  margin-left:auto;
  font-family:var(--p2-mono);
  font-size:max(8px,1.05cqw);
  background:#f2efe9;
  padding:.3cqw .7cqw;
  border-radius:.5cqw
}
.sp-seg {
  display:flex;
  background:#f2efe9;
  border-radius:1.2cqw;
  padding:.5cqw
}
.sp-seg span {
  flex:1;
  text-align:center;
  font-size:max(9px,1.3cqw);
  padding:.8cqw;
  border-radius:.9cqw;
  color:var(--p2-ink-soft)
}
.sp-seg span.on {
  background:#fff;
  color:#141414;
  box-shadow:0 .2cqw .6cqw rgba(0,0,0,.08)
}
.sp-oc {
  display:flex;
  gap:1.4cqw;
  align-items:center;
  flex:1;
  min-height:0
}
.sp-oc .im {
  width:40%;
  align-self:stretch;
  border-radius:1.2cqw;
  background:#cbbd9f center/cover
}
.sp-oc b {
  display:block;
  font-size:max(10px,1.6cqw);
  font-weight:500
}
.sp-oc small {
  display:block;
  font-size:max(9px,1.2cqw);
  color:var(--p2-mute);
  margin:.3cqw 0 1cqw
}
.sp-oc em {
  font-style:normal;
  font-size:max(10px,1.5cqw);
  font-weight:600
}
/* parity */
.sp-par2 {
  position:absolute;
  inset:3cqw 3cqw 8cqw;
  display:flex;
  justify-content:center;
  align-items:center;
  gap:9cqw
}
.sp-par2 .ph {
  --pw:28.5cqw
}
.sp-axis {
  position:absolute;
  left:50%;
  top:0;
  bottom:0;
  border-left:1px dashed var(--p2-ink)
}
.sp-axis span {
  position:absolute;
  top:50%;
  left:0;
  translate:-50% -50%;
  writing-mode:vertical-rl;
  background:var(--sp-sand);
  padding:1cqw 0;
  font-family:var(--p2-mono);
  font-size:max(8px,1.1cqw);
  letter-spacing:.14em;
  text-transform:uppercase;
  white-space:nowrap
}
.sp-plab {
  position:absolute;
  top:0;
  font-family:var(--p2-mono);
  font-size:max(8px,1.1cqw);
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--p2-ink-soft)
}
/* bilingual card photo */
.p2-bili-card .card-media {
  background:#cbbd9f url("https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=900&q=70") center/cover!important
}
.p2-bili-card .card-media::after {
  display:none!important
}
/* locked */
.sp-lock {
  background:#23261d;
  color:#fff;
  padding:120px 0
}
.sp-lock .p2-section-title {
  color:#fff
}
.sp-lock .p2-section-blurb {
  color:rgba(255,255,255,.65)
}
.sp-lock .p2-eyebrow {
  color:rgba(255,255,255,.5)
}
.sp-lock .p2-eyebrow .num {
  border-color:rgba(255,255,255,.5)
}
.sp-lock-grid {
  display:grid;
  grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);
  gap:56px;
  align-items:start
}
.sp-chapters {
  list-style:none;
  margin:0;
  padding:0;
  border-top:1px solid rgba(255,255,255,.14)
}
.sp-chapters li {
  display:grid;
  grid-template-columns:40px minmax(0,1fr) auto;
  gap:16px;
  align-items:center;
  padding:20px 0;
  border-bottom:1px solid rgba(255,255,255,.14)
}
.sp-chapters .n {
  font-family:var(--p2-mono);
  font-size:11px;
  color:rgba(255,255,255,.45)
}
.sp-chapters .t {
  font-size:18px
}
.sp-chapters .t small {
  display:block;
  font-size:13px;
  color:rgba(255,255,255,.55);
  margin-top:4px
}
.sp-chapters svg {
  width:14px;
  height:14px;
  stroke:rgba(255,255,255,.55);
  fill:none;
  stroke-width:1.6
}
.sp-gate {
  background:#fff;
  color:var(--p2-ink);
  border-radius:18px;
  padding:36px;
  display:flex;
  flex-direction:column;
  gap:16px;
  position:sticky;
  top:100px
}
.sp-gate h3 {
  font-size:28px;
  font-weight:400;
  letter-spacing:-.01em;
  line-height:1.15
}
.sp-gate p {
  font-size:14px;
  line-height:1.55;
  color:var(--p2-ink-soft)
}
.sp-gate .password-row {
  margin-top:8px
}
.sp-gate .error-message {
  min-height:18px;
  font-size:13px;
  color:#a33a2c
}
.sp-gate .alt a {
  color:var(--p2-ink);
  text-decoration:underline;
  text-underline-offset:3px
}
@media(max-width:900px) {
  .sp-lock-grid {
    grid-template-columns:1fr
  }
  .sp-gate {
    position:static
  }
  .sp-lock {
    padding:80px 0
  }
}
/* ---------- type: no mono, no italics ---------- */
.p2-page .p2-hero-title em,.p2-page .p2-section-title em,.p2-page .p2-next-link em,.p2-page h3 em,.p2-page h4 em {
  font-style:normal;
  color:var(--p2-mute)
}
.p2-page .p2-eyebrow,.p2-page .tab-no,.p2-page .stat-no,.p2-page .p2-corner,.p2-page .sp-note,.p2-page .p2-bili-hint,.p2-page .p2-next-eyebrow,.p2-page .cap {
  letter-spacing:.06em
}
/* ---------- role ---------- */
.sp-org {
  container-type:inline-size;
  background:var(--sp-sand);
  border-radius:18px;
  padding:48px 32px 32px
}
.sp-streams {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:3cqw
}
.sp-stream {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:22px;
  text-align:center;
  position:relative;
  padding-bottom:44px
}
.sp-stream::after {
  content:"";
  position:absolute;
  bottom:0;
  left:50%;
  height:30px;
  border-left:1px solid var(--p2-ink)
}
.sp-stream .ph {
  --pw:min(27cqw,330px)
}
.sp-lab span {
  display:block;
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute)
}
.sp-lab b {
  display:block;
  font-size:20px;
  font-weight:500;
  margin-top:6px
}
.sp-stream>p {
  font-size:14px;
  line-height:1.5;
  color:var(--p2-ink-soft);
  max-width:28ch;
  margin:0
}
.sp-base {
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:8px 16px;
  flex-wrap:wrap;
  background:#fff;
  border-radius:14px;
  padding:20px 24px
}
.sp-base span {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute)
}
.sp-base b {
  font-size:17px;
  font-weight:500
}
.sp-base.sys {
  background:var(--sp-olive);
  color:#fff
}
.sp-base.sys span {
  color:rgba(255,255,255,.7)
}
.sp-wire {
  height:20px;
  width:0;
  margin:0 auto;
  border-left:1px solid var(--p2-ink)
}
.sp-own {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:32px;
  margin-top:56px
}
.sp-own div {
  border-top:1px solid var(--p2-ink);
  padding-top:18px
}
.sp-own span {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  color:var(--p2-mute)
}
.sp-own h4 {
  font-size:19px;
  font-weight:500;
  margin:10px 0 8px
}
.sp-own p {
  font-size:14px;
  line-height:1.55;
  color:var(--p2-ink-soft);
  margin:0
}
@media(max-width:900px) {
  .sp-own {
    grid-template-columns:1fr 1fr
  }
}
@media(max-width:700px) {
  .sp-org {
    padding:28px 14px 14px
  }
  .sp-stream .ph {
    --pw:27cqw
  }
  .sp-lab b {
    font-size:14px
  }
  .sp-stream>p {
    display:none
  }
  .sp-own {
    grid-template-columns:1fr
  }
}
/* ---------- outcomes ---------- */
.sp-out {
  padding-bottom:40px
}
.sp-attr {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:16px
}
.sp-col {
  background:var(--sp-sand);
  border-radius:18px;
  padding:28px
}
.sp-col.me {
  background:var(--sp-olive);
  color:#fff
}
.sp-col span {
  display:block;
  font-family:var(--p2-mono);
  font-size:12px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute);
  margin-bottom:20px
}
.sp-col.me span {
  color:rgba(255,255,255,.7)
}
.sp-col ul {
  list-style:none;
  margin:0;
  padding:0;
  display:flex;
  flex-direction:column
}
.sp-col li {
  font-size:16px;
  line-height:1.4;
  padding:12px 0;
  border-top:1px solid rgba(0,0,0,.12)
}
.sp-col.me li {
  border-color:rgba(255,255,255,.2)
}
@media(max-width:900px) {
  .sp-attr {
    grid-template-columns:1fr
  }
}
.p2-page .stat-num {
  font-size:clamp(40px,5vw,72px)
}
.p2-page .p2-stats-grid {
  grid-template-columns:repeat(4,minmax(0,1fr))
}
@media(max-width:1000px) {
  .p2-page .p2-stats-grid {
    grid-template-columns:repeat(2,minmax(0,1fr));
    row-gap:32px
  }
  .p2-page .p2-stat {
    padding-left:0!important
  }
}
.sp-stream .ph {
  text-align:start
}
/* ---------- before/after tags ---------- */
.sp-pc {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:2cqw
}
.sp-tag {
  display:inline-flex;
  align-items:center;
  gap:.7cqw;
