/* Original: portfolio-final-polish.css */
/* Final portfolio polish — 12 October 2026. Shared across all eight pages. */
:scope { --portfolio-neue: "Neue Haas Grotesk Display Pro", "Neue Haas Grotesk", "Helvetica Neue", Arial, sans-serif; }

/* A consistent editorial sans-serif; no display-font overrides. */
body, button, input, select, textarea, .p2-page, .p2-page *, .portfolio-nav, .portfolio-footer,
.hero, .section, .wwm-page, .wwm-page *, .ac-two, .ac-two * {
