.case-text p {
  font-size: 14px;
  line-height: 1.5;
  color: #555252;
  margin-bottom: 20px;
}
.case-text p + p {
  margin-top: 16px;
}
.case-text p strong {
  display: block;
  margin-bottom: 6px;
}
.case-text p {
  margin-bottom: 14px;
}
/* LIST */

.case-text ol {
  margin-top: 12px;
  padding-left: 18px;
