.case-image {
  display: flex;
  justify-content: flex-end;
}
.case-image img {
  width: 100%;
  max-width: 734px;
  filter: drop-shadow(0px 4px 20px rgba(0,0,0,0.08));
}
/* CASE TITLE */

.case-title {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 16px;
  color: #555252;
}
