.dad-impact-line {
  width: 100%;
  height: 1px;
  background: #ffffff;
  margin-top: 10px;
}
.dad-impact-inner {
  display: grid;
  grid-template-columns: 360px 1fr;
  gap: 16px;
  align-items: center;
}
.dad-impact-text h2 {
  font-size: 32px;
  line-height: 1.3;
  font-weight: 500;
  color: #ffffff;
  margin-bottom: 16px;
}
.dad-impact-text h4 {
  font-size: 20px;
  line-height: 1.2;
  font-weight: 400;
  color: #ffffff;
  margin-bottom: 16px;
}
.dad-impact-text p {
  font-size: 14px;
  line-height: 1.5;
  color: #eeeeee;
  margin-bottom: 16px;
}
.dad-impact-text a {
  font-size: 14px;
  line-height: 18px;
  font-weight: 500;
  color: #ffffff;
  text-decoration: underline;
}
.dad-impact-images {
