/* Original: project-v2.css */


/* =========================================================
   PROJECT V2 â€” Cinematic, video-led project page treatment
   Layered on top of styles.css (keeps nav/footer chrome)
========================================================= */

:scope {
  --p2-ink: #0a0a0a;
  --p2-ink-soft: #555252;
  --p2-mute: #8a847b;
  --p2-line: #ededed;
  --p2-cream: #efe9e1;
  --p2-cream-deep: #e6dfd4;
  --p2-paper: #f6f4ef;
  --p2-mono: "Neue Haas Grotesk Display Pro", "Neue Haas Grotesk", "Helvetica Neue", Arial, sans-serif, "Switzer", sans-serif;
  --p2-display: "Switzer", sans-serif;
}
/* keep nav over hero */
.p2-page {
  color: var(--p2-ink);
}
.p2-page main {
  overflow: visible;
}
/* container */
.p2-wrap {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding-left: 100px;
  padding-right: 100px;
}
@media (max-width: 1100px) {
  .p2-wrap {
    padding-left: 40px;
    padding-right: 40px;
  }
}
@media (max-width: 700px) {
  .p2-wrap {
    padding-left: 24px;
    padding-right: 24px;
  }
}
/* reveal animation */
.p2-rise {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1), transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}
.p2-rise.is-in {
  opacity: 1;
  transform: none;
}
/* ============ HERO ============ */

.p2-hero {
  position: relative;
  padding-top: 64px;
  padding-bottom: 0;
  background: #ffffff;
}
.p2-hero-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  font-family: var(--p2-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--p2-ink-soft);
  text-transform: uppercase;
  margin-bottom: 56px;
}
.p2-hero-meta .slash {
  color: var(--p2-mute);
}
.p2-hero-meta .meta-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.p2-hero-meta .dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #0a0a0a;
  display: inline-block;
}
.p2-hero-title {
  font-size: clamp(48px, 7.2vw, 104px);
  line-height: 0.96;
  font-weight: 400;
  letter-spacing: -0.025em;
  margin-bottom: 32px;
  text-wrap: balance;
}
.p2-hero-title em {
  font-style: normal;
  font-weight: 300;
}
.p2-hero-lede {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  padding-bottom: 48px;
}
.p2-hero-sub {
  font-size: clamp(22px, 2vw, 28px);
  line-height: 1.25;
  font-weight: 300;
  color: var(--p2-ink);
  max-width: 540px;
}
.p2-hero-detail {
  font-size: 14px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
  max-width: 460px;
  justify-self: end;
}
.p2-hero-detail strong {
  color: var(--p2-ink);
  font-weight: 600;
}
.p2-hero-detail p + p {
  margin-top: 8px;
}
@media (max-width: 900px) {
  .p2-hero-lede {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .p2-hero-detail {
    justify-self: start;
  }
}
/* ============ HERO VIDEO ============ */

.p2-hero-video {
  position: relative;
  width: calc(100% - 240px);
  max-width: 1100px;
  margin: 0 auto;
  aspect-ratio: 16 / 9;
  background: #04182b;
  overflow: hidden;
  border-radius: 24px;
}
.p2-video-fallback.hidden {
  display: none !important;
}
.p2-hero-video video,
.p2-hero-video .p2-video-fallback {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  background: #04182b;
}
.p2-video-fallback {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #efe9e1 0%, #e6dfd4 50%, #d9d0c1 100%);
  font-family: var(--p2-mono);
  font-size: 14px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #7a6b58;
}
.p2-video-fallback .fb-inner {
  text-align: center;
}
.p2-video-fallback .fb-play {
  width: 88px;
  height: 88px;
  border: 1.5px solid #7a6b58;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
}
.p2-video-fallback .fb-play::after {
  content: "";
  width: 0;
  height: 0;
  border-left: 18px solid #7a6b58;
  border-top: 12px solid transparent;
  border-bottom: 12px solid transparent;
  margin-left: 4px;
}
.p2-hero-video .p2-corner {
  position: absolute;
  top: 16px;
  left: 16px;
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  color: #ffffff;
  background: rgba(0,0,0,0.5);
  padding: 6px 10px;
  text-transform: uppercase;
  z-index: 2;
}
.p2-hero-video .p2-corner.right {
  left: auto;
  right: 16px;
}
@media (max-width: 900px) {
  .p2-hero-video {
    width: calc(100% - 80px);
  }
}
@media (max-width: 700px) {
  .p2-hero-video {
    width: calc(100% - 48px);
    border-radius: 16px;
  }
}
/* ============ STAT TICKER ============ */

.p2-stats {
  background: #0a0a0a;
  color: #fff;
  padding-top: 80px;
  padding-bottom: 80px;
  margin-top: 80px;
}
.p2-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-top: 1px solid rgba(255,255,255,0.12);
  border-bottom: 1px solid rgba(255,255,255,0.12);
}
.p2-stat {
  padding: 40px 32px 40px 0;
  border-right: 1px solid rgba(255,255,255,0.12);
  position: relative;
}
.p2-stat:last-child {
  border-right: none;
}
.p2-stat .stat-no {
  font-family: var(--p2-mono);
  font-size: 11px;
  color: rgba(255,255,255,0.4);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin-bottom: 24px;
}
.p2-stat .stat-num {
  font-size: clamp(48px, 6vw, 76px);
  line-height: 0.95;
  letter-spacing: -0.025em;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  margin-bottom: 16px;
}
.p2-stat .stat-num .unit {
  font-size: 0.5em;
  margin-left: 0.05em;
  color: rgba(255,255,255,0.65);
}
.p2-stat .stat-label {
  font-size: 13px;
  line-height: 1.4;
  color: rgba(255,255,255,0.65);
}
@media (max-width: 900px) {
  .p2-stats-grid {
    grid-template-columns: 1fr 1fr;
  }
  .p2-stat:nth-child(2) {
    border-right: none;
  }
  .p2-stat:nth-child(1), .p2-stat:nth-child(2) {
    border-bottom: 1px solid rgba(255,255,255,0.12);
  }
}
@media (max-width: 560px) {
  .p2-stats-grid {
    grid-template-columns: 1fr;
  }
  .p2-stat {
    border-right: none;
    border-bottom: 1px solid rgba(255,255,255,0.12);
    padding: 28px 0;
  }
  .p2-stat:last-child {
    border-bottom: none;
  }
}
/* ============ MARQUEE ============ */

.p2-marquee {
  background: #0a0a0a;
  color: #fff;
  padding: 24px 0;
  margin-top: -1px;
  overflow: hidden;
  border-top: 1px solid rgba(255,255,255,0.12);
}
.p2-marquee-track {
  display: inline-flex;
  align-items: center;
  gap: 56px;
  white-space: nowrap;
  animation: p2-marquee 38s linear infinite;
  font-family: var(--p2-mono);
  font-size: 13px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.7);
}
.p2-marquee-track span.dot {
  width: 4px;
  height: 4px;
  background: rgba(255,255,255,0.3);
  border-radius: 50%;
  display: inline-block;
}
.p2-marquee-track strong {
  color: #fff;
  font-weight: 600;
}

/* ============ SECTION HEADERS ============ */

.p2-section {
  padding-top: 120px;
  padding-bottom: 0;
}
.p2-section-head {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  margin-bottom: 64px;
}
.p2-eyebrow {
  font-family: var(--p2-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--p2-mute);
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}
.p2-eyebrow .num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border: 1px solid var(--p2-mute);
  border-radius: 50%;
  font-size: 10px;
}
.p2-section-title {
  font-size: clamp(34px, 4.4vw, 56px);
  line-height: 1.05;
  letter-spacing: -0.02em;
  font-weight: 400;
  max-width: 720px;
}
.p2-section-blurb {
  font-size: 16px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
  max-width: 460px;
  justify-self: end;
}
@media (max-width: 900px) {
  .p2-section-head {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .p2-section-blurb {
    justify-self: start;
  }
  .p2-section {
    padding-top: 80px;
  }
}
/* ============ DEVICE SHOWCASE ============ */

.p2-device {
  position: relative;
  background: var(--p2-cream);
  padding: 96px 0;
  overflow: hidden;
}
.p2-device-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  align-items: end;
}
.p2-device-tile {
  background: #ffffff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 30px 60px -30px rgba(0,0,0,0.18);
  aspect-ratio: 9/19;
  position: relative;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}
.p2-device-tile.center {
  transform: translateY(-40px);
}
.p2-device-tile.right {
  transform: translateY(20px);
}
.p2-device-tile:hover {
  transform: translateY(-60px);
}
.p2-device-tile.right:hover {
  transform: translateY(0);
}
.p2-device-tile.left:hover {
  transform: translateY(-20px);
}
.p2-device-tile img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.p2-device-tile video {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
  display: block;
  background: #000;
}
.p2-device-tag {
  position: absolute;
  top: 16px;
  left: 16px;
  font-family: var(--p2-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(0,0,0,0.55);
  background: rgba(255,255,255,0.9);
  padding: 5px 9px;
  border-radius: 999px;
  z-index: 2;
}
@media (max-width: 900px) {
  .p2-device-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .p2-device-tile.center, .p2-device-tile.right {
    transform: none;
  }
  .p2-device-tile {
    aspect-ratio: 16/9;
  }
}
/* ============ INTERACTIVE BILINGUAL SANDBOX ============ */

.p2-bili {
  padding-top: 120px;
  padding-bottom: 120px;
}
.p2-bili-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--p2-line);
}
.p2-bili-hint {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--p2-mute);
}
.p2-toggle {
  display: inline-flex;
  background: #f2f2f2;
  border: 1px solid var(--p2-line);
  border-radius: 999px;
  padding: 4px;
  position: relative;
}
.p2-toggle button {
  position: relative;
  z-index: 1;
  background: none;
  border: none;
  cursor: pointer;
  padding: 10px 20px;
  font-family: var(--p2-mono);
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--p2-mute);
  border-radius: 999px;
  transition: color 0.3s ease;
}
.p2-toggle button[aria-pressed="true"] {
  color: #fff;
}
.p2-toggle .p2-toggle-pill {
  position: absolute;
  top: 4px;
  bottom: 4px;
  left: 4px;
  width: calc(50% - 4px);
  background: #0a0a0a;
  border-radius: 999px;
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.p2-toggle[data-dir="rtl"] .p2-toggle-pill {
  transform: translateX(100%);
}
.p2-bili-stage {
  display: grid;
  grid-template-columns: 380px 1fr;
  gap: 56px;
  align-items: start;
}
@media (max-width: 900px) {
  .p2-bili-stage {
    grid-template-columns: 1fr;
    gap: 32px;
  }
}
.p2-bili-spec {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.p2-bili-spec h3 {
  font-size: 24px;
  line-height: 1.2;
  font-weight: 400;
  letter-spacing: -0.01em;
}
.p2-bili-spec p {
  font-size: 14px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
}
.p2-spec-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  border-top: 1px solid var(--p2-line);
}
.p2-spec-list li {
  display: grid;
  grid-template-columns: 88px 1fr;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--p2-line);
  font-size: 13px;
  color: var(--p2-ink-soft);
  align-items: center;
}
.p2-spec-list li .k {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--p2-mute);
}
.p2-spec-list li .v {
  font-variant-numeric: tabular-nums;
  transition: opacity 0.4s ease;
}
.p2-bili-card-wrap {
  background: var(--p2-paper);
  border-radius: 18px;
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 520px;
  position: relative;
  overflow: hidden;
}
.p2-bili-card-wrap::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 1px 1px, rgba(0,0,0,0.06) 1px, transparent 0);
  background-size: 24px 24px;
  opacity: 0.5;
  pointer-events: none;
}
.p2-bili-card {
  width: 100%;
  max-width: 380px;
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 30px 60px -30px rgba(0,0,0,0.25), 0 2px 6px rgba(0,0,0,0.04);
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
  position: relative;
  z-index: 1;
}
.p2-bili-card[data-dir="rtl"] {
  direction: rtl;
}
.p2-bili-card .card-media {
  width: 100%;
  aspect-ratio: 4/3;
  background:
    linear-gradient(135deg, rgba(0,0,0,0.05), transparent 50%),
    linear-gradient(180deg, #c9b893 0%, #b09971 60%, #927b56 100%);
  position: relative;
}
.p2-bili-card .card-media::after {
  /* villa silhouette */
  content: "";
  position: absolute;
  left: 12%;
  right: 12%;
  bottom: 8%;
  top: 38%;
  background:
    linear-gradient(180deg, transparent 30%, rgba(0,0,0,0.1) 100%),
    linear-gradient(180deg, #f5efe4 0%, #ede4d2 100%);
  clip-path: polygon(0 80%, 8% 80%, 8% 35%, 22% 22%, 38% 35%, 38% 50%, 62% 50%, 62% 35%, 78% 22%, 92% 35%, 92% 80%, 100% 80%, 100% 100%, 0 100%);
}
.p2-bili-card .card-tag {
  position: absolute;
  top: 16px;
  left: 16px;
  background: rgba(255,255,255,0.95);
  font-family: var(--p2-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 999px;
  color: #0a0a0a;
}
.p2-bili-card[data-dir="rtl"] .card-tag {
  left: auto;
  right: 16px;
}
.p2-bili-card .card-fav {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 32px;
  height: 32px;
  background: rgba(255,255,255,0.95);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.p2-bili-card[data-dir="rtl"] .card-fav {
  right: auto;
  left: 16px;
}
.p2-bili-card .card-fav svg {
  width: 16px;
  height: 16px;
  fill: #0a0a0a;
}
.p2-bili-card .card-body {
  padding: 20px 22px 22px;
}
.p2-bili-card .card-row1 {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 4px;
}
.p2-bili-card .card-title {
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.p2-bili-card .card-price {
  font-size: 18px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: #0a0a0a;
}
.p2-bili-card .card-loc {
  font-size: 13px;
  color: var(--p2-ink-soft);
  margin-bottom: 18px;
}
.p2-bili-card .card-feats {
  display: flex;
  gap: 18px;
  font-size: 12px;
  color: var(--p2-ink-soft);
  margin-bottom: 18px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--p2-line);
}
.p2-bili-card .card-feats span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.p2-bili-card .card-feats svg {
  width: 14px;
  height: 14px;
  stroke: var(--p2-ink-soft);
  fill: none;
  stroke-width: 1.5;
}
.p2-bili-card[data-dir="rtl"] .card-feats svg {
  transform: scaleX(-1);
}
.p2-bili-card .card-cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  font-weight: 500;
}
.p2-bili-card .card-cta .arr {
  width: 28px;
  height: 28px;
  border: 1px solid #0a0a0a;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background 0.3s, color 0.3s;
}
.p2-bili-card .card-cta:hover .arr {
  background: #0a0a0a;
  color: #fff;
}
.p2-bili-card .card-cta .arr svg {
  width: 12px;
  height: 12px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
}
.p2-bili-card[data-dir="rtl"] .card-cta .arr svg {
  transform: scaleX(-1);
}
.p2-bili-card[data-dir="rtl"] .card-arabic {
  font-family: "Noto Naskh Arabic", "Tajawal", Georgia, serif;
}
/* ============ PROCESS STEPPER ============ */

.p2-process {
  padding-top: 120px;
  padding-bottom: 80px;
}
.p2-process-tabs {
  display: flex;
  gap: 0;
  border-top: 1px solid var(--p2-line);
  border-bottom: 1px solid var(--p2-line);
  margin-bottom: 56px;
}
.p2-process-tab {
  flex: 1;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  padding: 24px 28px;
  border-right: 1px solid var(--p2-line);
  position: relative;
  transition: background 0.3s ease;
}
.p2-process-tab:last-child {
  border-right: none;
}
.p2-process-tab:hover {
  background: #fafafa;
}
.p2-process-tab .tab-no {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--p2-mute);
  margin-bottom: 12px;
}
.p2-process-tab .tab-title {
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--p2-ink);
  line-height: 1.25;
}
.p2-process-tab[aria-selected="true"] {
  background: #0a0a0a;
}
.p2-process-tab[aria-selected="true"] .tab-no {
  color: rgba(255,255,255,0.5);
}
.p2-process-tab[aria-selected="true"] .tab-title {
  color: #fff;
}
.p2-process-tab::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 2px;
  background: #0a0a0a;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}
.p2-process-panels {
  position: relative;
}
.p2-process-panel {
  display: none;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: start;
}
.p2-process-panel.is-active {
  display: grid;
  animation: p2-fade-up 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.p2-process-text h4 {
  font-size: 24px;
  font-weight: 500;
  letter-spacing: -0.01em;
  margin-bottom: 16px;
  line-height: 1.25;
}
.p2-process-text p {
  font-size: 15px;
  line-height: 1.6;
  color: var(--p2-ink-soft);
  margin-bottom: 14px;
}
.p2-process-text ul {
  margin-top: 16px;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.p2-process-text li {
  font-size: 14px;
  line-height: 1.5;
  color: var(--p2-ink-soft);
  padding-left: 20px;
  position: relative;
}
.p2-process-text li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 9px;
  width: 8px;
  height: 1px;
  background: var(--p2-mute);
}
.p2-process-media {
  background: var(--p2-cream);
  border-radius: 18px;
  overflow: hidden;
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.p2-process-media img,
.p2-process-media video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
@media (max-width: 900px) {
  .p2-process-panel {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .p2-process-tabs {
    flex-direction: column;
  }
  .p2-process-tab {
    border-right: none;
    border-bottom: 1px solid var(--p2-line);
  }
  .p2-process-tab:last-child {
    border-bottom: none;
  }
}
/* ============ DESIGN SYSTEM REVEAL ============ */

.p2-ds {
  padding-top: 120px;
  padding-bottom: 120px;
  background: #fafaf8;
  margin-top: 80px;
}
.p2-ds-stage {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
@media (max-width: 900px) {
  .p2-ds-stage {
    grid-template-columns: 1fr;
    gap: 40px;
  }
}
.p2-ds-text h3 {
  font-size: clamp(28px, 3vw, 40px);
  line-height: 1.1;
  letter-spacing: -0.02em;
  font-weight: 400;
  margin-bottom: 24px;
}
.p2-ds-text p {
  font-size: 15px;
  line-height: 1.6;
  color: var(--p2-ink-soft);
  margin-bottom: 16px;
}
.p2-ds-pills {
  display: flex;
  gap: 8px;
  margin-top: 28px;
  flex-wrap: wrap;
}
.p2-ds-pill {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 8px 14px;
  border: 1px solid var(--p2-line);
  background: #fff;
  cursor: pointer;
  border-radius: 999px;
  color: var(--p2-ink-soft);
  transition: all 0.3s ease;
}
.p2-ds-pill[aria-pressed="true"] {
  background: #0a0a0a;
  color: #fff;
  border-color: #0a0a0a;
}
.p2-ds-viz {
  background: #fff;
  border-radius: 18px;
  padding: 40px;
  aspect-ratio: 1/1;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  box-shadow: 0 30px 60px -40px rgba(0,0,0,0.18);
}
.p2-ds-viz-stage {
  width: 100%;
  height: 100%;
  position: relative;
}
/* atoms */
.p2-ds-atom {
  position: absolute;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  transition: all 0.6s cubic-bezier(0.22, 1, 0.36, 1);
  font-family: var(--p2-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--p2-mute);
}
.p2-ds-atom .swatch {
  width: 48px;
  height: 48px;
  background: #0a0a0a;
  border-radius: 4px;
}
.p2-ds-atom.color1 {
  top: 0%;
  left: 0%;
}
.p2-ds-atom.color1 .swatch {
  background: #0a0a0a;
}
.p2-ds-atom.color2 {
  top: 0%;
  left: 30%;
}
.p2-ds-atom.color2 .swatch {
  background: #d4a548;
  border-radius: 4px;
}
.p2-ds-atom.color3 {
  top: 0%;
  left: 60%;
}
.p2-ds-atom.color3 .swatch {
  background: #efe9e1;
  border: 1px solid #e0d8cc;
}
.p2-ds-atom.type1 {
  top: 38%;
  left: 0%;
}
.p2-ds-atom.type1 .swatch {
  background: none;
  width: auto;
  height: auto;
  font-family: "Switzer", sans-serif;
  font-size: 28px;
  font-weight: 500;
  color: #0a0a0a;
  letter-spacing: -0.02em;
}
.p2-ds-atom.type1 .swatch::before {
  content: "Aa";
}
.p2-ds-atom.space1 {
  top: 38%;
  left: 38%;
}
.p2-ds-atom.space1 .swatch {
  background: none;
  width: 48px;
  height: 6px;
  border-top: 1px solid #0a0a0a;
  border-bottom: 1px solid #0a0a0a;
  position: relative;
}
.p2-ds-atom.space1 .swatch::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  border-top: 1px dashed var(--p2-mute);
}
/* molecules (buttons, inputs) */
.p2-ds-mol {
  position: absolute;
  opacity: 0;
  transform: translateY(20px) scale(0.95);
  transition: all 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  font-family: "Switzer", sans-serif;
}
.p2-ds-mol.btn {
  top: 60%;
  left: 0;
  background: #0a0a0a;
  color: #fff;
  font-size: 13px;
  padding: 12px 20px;
  border-radius: 8px;
}
.p2-ds-mol.input {
  top: 60%;
  left: 35%;
  background: #fff;
  border: 1px solid #ddd;
  font-size: 13px;
  padding: 12px 16px;
  border-radius: 8px;
  width: 160px;
  color: var(--p2-mute);
}
.p2-ds-mol.input::after {
  content: "Searchâ€¦";
}
/* organisms (card preview) */
.p2-ds-org {
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: scale(0.94);
  transition: all 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 16px 40px -16px rgba(0,0,0,0.18);
  border: 1px solid #ededed;
}
.p2-ds-org .org-img {
  height: 60%;
  background: linear-gradient(135deg, #d9c69b, #9a8259);
}
.p2-ds-org .org-body {
  padding: 20px;
}
.p2-ds-org .org-title {
  font-size: 16px;
  font-weight: 500;
  margin-bottom: 8px;
}
.p2-ds-org .org-meta {
  font-size: 12px;
  color: var(--p2-ink-soft);
}
/* mode states */
.p2-ds-viz[data-mode="atoms"] .p2-ds-mol,
.p2-ds-viz[data-mode="atoms"] .p2-ds-org {
  opacity: 0;
  pointer-events: none;
}
.p2-ds-viz[data-mode="molecules"] .p2-ds-mol {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}
.p2-ds-viz[data-mode="molecules"] .p2-ds-org {
  opacity: 0;
  pointer-events: none;
}
.p2-ds-viz[data-mode="molecules"] .p2-ds-atom {
  opacity: 0.35;
}
.p2-ds-viz[data-mode="organisms"] .p2-ds-mol,
.p2-ds-viz[data-mode="organisms"] .p2-ds-atom {
  opacity: 0;
  pointer-events: none;
}
.p2-ds-viz[data-mode="organisms"] .p2-ds-org {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}
/* ============ IMAGE STRIP ============ */

.p2-strip {
  padding-top: 80px;
  padding-bottom: 0;
}
.p2-strip-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.p2-strip-grid img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  border-radius: 8px;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}
.p2-strip-grid > div {
  overflow: hidden;
  border-radius: 8px;
  display: block;
  position: relative;
}
.p2-strip-grid > div:hover img {
  transform: scale(1.04);
}
.p2-strip-grid > div::after {
  content: attr(data-cap);
  position: absolute;
  left: 12px;
  bottom: 12px;
  font-family: var(--p2-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #fff;
  background: rgba(0,0,0,0.6);
  padding: 5px 9px;
  border-radius: 999px;
}
@media (max-width: 900px) {
  .p2-strip-grid {
    grid-template-columns: 1fr 1fr;
  }
}
/* ============ OUTCOMES ============ */

.p2-outcomes {
  padding-top: 120px;
  padding-bottom: 120px;
}
.p2-outcomes-head {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  margin-bottom: 64px;
}
.p2-outcomes-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  border-top: 1px solid var(--p2-line);
}
.p2-outcomes-item {
  padding: 40px 0;
  border-bottom: 1px solid var(--p2-line);
  border-right: 1px solid var(--p2-line);
  padding-right: 32px;
  padding-left: 0;
  display: grid;
  grid-template-rows: auto 1fr auto;
  min-height: 220px;
}
.p2-outcomes-item:nth-child(3n) {
  border-right: none;
  padding-right: 0;
}
.p2-outcomes-item:nth-child(3n/**/+2),
.p2-outcomes-item:nth-child(3n/**/+3) {
  padding-left: 32px;
}
.p2-outcomes-item .o-num {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--p2-mute);
  margin-bottom: 24px;
}
.p2-outcomes-item .o-big {
  font-size: clamp(36px, 4vw, 56px);
  line-height: 1;
  letter-spacing: -0.025em;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  margin-bottom: 12px;
}
.p2-outcomes-item .o-big .unit {
  font-size: 0.5em;
  color: var(--p2-ink-soft);
  margin-left: 0.1em;
}
.p2-outcomes-item .o-label {
  font-size: 14px;
  line-height: 1.4;
  color: var(--p2-ink-soft);
}
@media (max-width: 700px) {
  .p2-outcomes-grid {
    grid-template-columns: 1fr;
  }
  .p2-outcomes-item {
    border-right: none;
    padding-left: 0 !important;
    padding-right: 0 !important;
  }
}
.p2-outcomes-summary {
  margin-top: 48px;
  padding: 32px;
  background: #0a0a0a;
  color: #fff;
  border-radius: 18px;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  gap: 32px;
}
.p2-outcomes-summary p {
  font-size: clamp(18px, 1.8vw, 22px);
  line-height: 1.35;
  font-weight: 400;
  max-width: 760px;
}
.p2-outcomes-summary .o-source {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
}
@media (max-width: 700px) {
  .p2-outcomes-summary {
    grid-template-columns: 1fr;
  }
}
/* ============ REFLECTION / NEXT ============ */

.p2-reflect {
  padding-top: 0;
  padding-bottom: 120px;
}
.p2-reflect-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: start;
}
@media (max-width: 900px) {
  .p2-reflect-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }
}
.p2-reflect h3 {
  font-size: clamp(28px, 3vw, 40px);
  line-height: 1.1;
  letter-spacing: -0.02em;
  font-weight: 400;
  margin-bottom: 0;
}
.p2-reflect ul {
  list-style: none;
  padding: 0;
  margin: 0;
  border-top: 1px solid var(--p2-line);
}
.p2-reflect li {
  font-size: 15px;
  line-height: 1.45;
  color: var(--p2-ink);
  padding: 18px 0;
  border-bottom: 1px solid var(--p2-line);
  display: grid;
  grid-template-columns: 24px 1fr;
  gap: 16px;
  align-items: baseline;
}
.p2-reflect li .num {
  font-family: var(--p2-mono);
  font-size: 11px;
  color: var(--p2-mute);
  letter-spacing: 0.1em;
}
/* ============ NEXT PROJECT ============ */

.p2-next {
  background: #0a0a0a;
  color: #fff;
  padding-top: 80px;
  padding-bottom: 80px;
}
.p2-next-eyebrow {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  margin-bottom: 24px;
}
.p2-next-link {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  gap: 32px;
  text-decoration: none;
  color: #fff;
  padding: 32px 0;
  border-top: 1px solid rgba(255,255,255,0.15);
  border-bottom: 1px solid rgba(255,255,255,0.15);
  transition: padding 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
.p2-next-link:hover {
  padding-left: 16px;
}
.p2-next-link h3 {
  font-size: clamp(32px, 4.4vw, 56px);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.05;
}
.p2-next-link .arrow {
  font-size: 32px;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
.p2-next-link:hover .arrow {
  transform: translateX(12px);
}
/* ============ MISC ============ */

.p2-hr {
  border: 0;
  border-top: 1px solid var(--p2-line);
  margin: 0;
}
.p2-page .contact-banner {
  margin-top: 0;
}
.p2-section-title em,.p2-next-link em,.p2-process-text h4 em {
  font-style:normal
}
/* no scroll-reveal */
.p2-rise,.p2-rise.is-in {
  opacity:1!important;
  transform:none!important;
  transition:none!important
}


/* Original: property-tech-preview.css */
:scope {
  --sp-gold:#9a7b4f;
  --sp-olive:#36412a;
  --sp-sand:#f7f5f1
}
.p2-page {
  --p2-cream:#f7f5f1;
  --p2-cream-deep:#f7f5f1;
  --p2-paper:#f7f5f1
}
a {
  color:var(--p2-ink)
}
a:hover {
  color:var(--p2-ink-soft)
}
.sp-badge {
  display:inline-flex;
  align-items:center;
  gap:8px;
  white-space:nowrap;
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.14em;
  text-transform:uppercase;
  padding:7px 12px;
  border:1px solid var(--p2-ink);
  border-radius:999px;
  text-decoration:none
}
.sp-badge svg {
  width:12px;
  height:12px
}
.sp-note {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--p2-mute)
}
/* ---------- iPhone ---------- */
.hf {
  font-family:"Switzer",sans-serif;
  font-weight:300;
  letter-spacing:-.03em
}
[dir="rtl"] .hf {
  font-family:"IBM Plex Sans Arabic",sans-serif;
  font-weight:400;
  letter-spacing:0
}
.ph {
  --pw:260px;
  position:relative;
  width:var(--pw);
  aspect-ratio:300/640;
  font-size:calc(var(--pw)/30);
  background:#0c0c0c;
  border-radius:4.9em;
  padding:.72em;
  flex-shrink:0;
  box-shadow:0 0 0 .28em #ddd3c0,0 0 0 .36em #a8997b,0 0 0 .42em #eee7d9,0 5em 6em -3em rgba(60,45,20,.38),0 2em 2.4em -2em rgba(0,0,0,.3)
}
.ph::before {
  content:"";
  position:absolute;
  top:1.85em;
  left:50%;
  translate:-50% 0;
  width:8.4em;
  height:2.5em;
  border-radius:2em;
  background:#000;
  z-index:6
}
.scr {
  position:relative;
  width:100%;
  height:100%;
  border-radius:4.15em;
  overflow:hidden;
  background:#fff;
  display:flex;
  flex-direction:column;
  color:#141414;
  line-height:1.25;
  font-family:"Switzer",system-ui,sans-serif;
  letter-spacing:-.005em
}
.scr[dir="rtl"] {
  font-family:"IBM Plex Sans Arabic","Switzer",serif;
  line-height:1.35
}
.scr::after {
  content:"";
  position:absolute;
  bottom:.75em;
  left:50%;
  translate:-50% 0;
  width:10em;
  height:.42em;
  border-radius:1em;
  background:#141414;
  z-index:6
}
.scr svg {
  fill:none;
  stroke:currentColor;
  stroke-width:1.6;
  stroke-linecap:round;
  stroke-linejoin:round
}
.sb {
  height:4.8em;
  flex-shrink:0;
  display:flex;
  justify-content:space-between;
  align-items:center;
  padding:0 2.5em 0 2.9em;
  position:relative;
  z-index:5;
  direction:ltr
}
.sb b {
  font-size:1.35em;
  font-weight:600;
  font-family:"Switzer",system-ui,sans-serif
}
.sb .ic {
  display:flex;
  gap:.45em;
  align-items:center
}
.sb .ic svg {
  height:1.15em;
  width:auto;
  fill:currentColor;
  stroke:none
}
.sb.lt {
  position:absolute;
  left:0;
  right:0;
  top:0;
  color:#fff
}
.pad {
  padding:0 1.9em;
  display:flex;
  flex-direction:column;
  gap:1.2em;
  flex:1;
  min-height:0
}
.ed-top {
  display:flex;
  justify-content:space-between;
  align-items:center;
  margin-top:.3em
}
.ed-mark svg {
  width:2.4em;
  height:2.4em;
  color:#141414;
  stroke-width:2.2
}
.ed-menu {
  width:3.3em;
  height:3.3em;
  border-radius:50%;
  background:#f3f3f1;
  display:grid;
  place-items:center
}
.ed-menu svg {
  width:1.5em;
  height:1.5em
}
.ed-eb {
  display:block;
  font-size:1.1em;
  color:#8b8b8b
}
.ed-h {
  font-size:3.1em;
  line-height:1.02;
  color:#141414
}
.ed-p {
  font-size:1.15em;
  color:#6b6b6b;
  line-height:1.4;
  margin:0
}
.ed-link {
  align-self:flex-start;
  display:flex;
  align-items:center;
  gap:.4em;
  font-size:1.1em;
  font-weight:500;
  border-bottom:1px solid currentColor;
  padding-bottom:.3em
}
.ed-link svg {
  width:1.2em;
  height:1.2em
}
.ed-photo {
  flex:1;
  min-height:0;
  border-radius:1.8em;
  background:#cbbd9f center/cover;
  position:relative;
  overflow:hidden
}
.ed-cap {
  position:absolute;
  left:1.3em;
  bottom:1.2em;
  color:#fff;
  text-shadow:0 1px 8px rgba(0,0,0,.35)
}
.ed-cap small {
  display:block;
  font-size:1em;
  opacity:.9
}
.ed-cap b {
  font-size:1.5em;
  font-weight:500
}
.ed-stats {
  display:flex;
  background:#fbe3c4;
  color:#141414;
  border-radius:1.5em;
  padding:1em .4em;
  margin-bottom:.4em;
  flex-shrink:0
}
.ed-stats span {
  flex:1;
  text-align:center;
  border-inline-start:1px solid rgba(0,0,0,.1)
}
.ed-stats span:first-child {
  border:0
}
.ed-stats b {
  display:block;
  font-size:1.45em;
  font-weight:500
}
.ed-stats i {
  font-style:normal;
  font-size:.9em;
  opacity:.65
}
.hdr {
  display:flex;
  justify-content:space-between;
  align-items:center;
  margin-top:.4em
}
.hdr small {
  display:block;
  font-size:1.1em;
  color:#8b8b8b
}
.hdr b {
  display:block;
  font-size:2em
}
.hdr .r {
  display:flex;
  gap:.6em
}
.ib {
  width:3.5em;
  height:3.5em;
  border-radius:50%;
  background:#f5f5f3;
  display:grid;
  place-items:center;
  position:relative
}
.ib svg {
  width:1.6em;
  height:1.6em
}
.ib.dot::after {
  content:"";
  position:absolute;
  top:.85em;
  right:.95em;
  width:.6em;
  height:.6em;
  border-radius:50%;
  background:#b0703c;
  border:.15em solid #fff
}
.av {
  width:3.5em;
  height:3.5em;
  border-radius:50%;
  background:#141414;
  color:#fff;
  display:grid;
  place-items:center
}
.av i {
  font-style:normal;
  font-size:1.3em;
  font-weight:600
}
.sec {
  display:flex;
  justify-content:space-between;
  align-items:baseline;
  flex-shrink:0
}
.sec b {
  font-size:1.4em;
  font-weight:500
}
.sec small {
  font-size:1.05em;
  color:#8b8b8b
}
.fav {
  position:absolute;
  top:1.2em;
  right:1.2em;
  width:3.1em;
  height:3.1em;
  border-radius:50%;
  background:rgba(255,255,255,.92);
  display:grid;
  place-items:center;
  color:#141414;
  z-index:2
}
[dir="rtl"] .fav {
  right:auto;
  left:1.2em
}
.fav svg {
  width:1.45em;
  height:1.45em
}
.fav.on svg {
  fill:#141414;
  stroke:#141414
}
.pager {
  position:absolute;
  bottom:3.6em;
  left:50%;
  translate:-50% 0;
  display:flex;
  gap:.4em;
  z-index:2
}
.pager i {
  width:.55em;
  height:.55em;
  border-radius:1em;
  background:rgba(255,255,255,.55)
}
.pager i.on {
  width:1.6em;
  background:#fff
}
.tb {
  height:7em;
  flex-shrink:0;
  display:flex;
  justify-content:space-around;
  padding:1em .8em 0;
  background:#fff;
  border-top:1px solid #efefef
}
.tb span {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:.35em;
  color:#b0b0b0;
  width:5em
}
.tb svg {
  width:2em;
  height:2em
}
.tb i {
  font-style:normal;
  font-size:.92em
}
.tb span.on {
  color:#141414
}
.tb span.on i {
  font-weight:600
}
.fi-hero {
  background:#dbeaf1;
  border-radius:1.8em;
  padding:1.6em;
  display:flex;
  flex-direction:column;
  gap:.4em
}
.fi-hero b {
  font-size:3.8em;
  line-height:1;
  color:#141414
}
.fi-hero small {
  font-size:1.02em;
  color:#8b8b8b
}
.fi-sl .h {
  display:flex;
  justify-content:space-between;
  font-size:1.1em;
  margin-bottom:.6em
}
.fi-sl .h span {
  color:#6b6b6b
}
.fi-sl .h b {
  font-weight:600
}
.tr {
  height:.45em;
  border-radius:1em;
  background:#ededed;
  position:relative
}
.tr i {
  position:absolute;
  left:0;
  top:0;
  bottom:0;
  background:#141414;
  border-radius:1em
}
.tr i::after {
  content:"";
  position:absolute;
  right:-.8em;
  top:50%;
  translate:0 -50%;
  width:1.6em;
  height:1.6em;
  border-radius:50%;
  background:#f5f5f3;
  box-shadow:0 .1em .5em rgba(0,0,0,.2);
  background:#fff
}
.fi-bank {
  display:flex;
  gap:1em;
  align-items:center;
  background:#f5f5f3;
  border-radius:1.4em;
  padding:.9em
}
.fi-bank .bk {
  width:3.2em;
  height:3.2em;
  border-radius:1em;
  color:#fff;
  display:grid;
  place-items:center;
  font-weight:600
}
.fi-bank b {
  display:block;
  font-size:1.15em;
  font-weight:500
}
.fi-bank small {
  font-size:.98em;
  color:#8b8b8b
}
.dt-img {
  height:28.5em;
  flex-shrink:0;
  background:#cbbd9f center/cover;
  position:relative
}
.dt-img::before {
  content:"";
  position:absolute;
  inset:0 0 auto;
  height:9em;
  background:linear-gradient(180deg,rgba(0,0,0,.35),transparent)
}
.tbtn {
  position:absolute;
  top:5.4em;
  width:3.4em;
  height:3.4em;
  border-radius:50%;
  background:rgba(255,255,255,.92);
  display:grid;
  place-items:center;
  z-index:2
}
.tbtn svg {
  width:1.5em;
  height:1.5em
}
.tbtn.l {
  left:1.6em
}
.tbtn.r {
  right:1.6em
}
[dir="rtl"] .tbtn.l {
  left:auto;
  right:1.6em
}
[dir="rtl"] .tbtn.r {
  right:auto;
  left:1.6em
}
[dir="rtl"] .flip {
  transform:scaleX(-1)
}
.sheet {
  flex:1;
  min-height:0;
  margin-top:-2.4em;
  background:#fff;
  border-radius:2.4em 2.4em 0 0;
  position:relative;
  z-index:3;
  padding:1.9em 1.8em 2.4em;
  display:flex;
  flex-direction:column;
  gap:1.15em
}
.ttl {
  display:flex;
  justify-content:space-between;
  align-items:flex-start;
  gap:1em
}
.ttl b {
  display:block;
  font-size:2em;
  color:#141414
}
.ttl small {
  display:block;
  font-size:1.08em;
  color:#8b8b8b;
  margin-top:.3em
}
.ttl .p {
  text-align:end;
  flex-shrink:0
}
.ttl .p b {
  font-size:1.45em;
  font-weight:600;
  font-family:"Switzer",sans-serif
}
.ft {
  display:flex;
  gap:.6em
}
.ft span {
  flex:1;
  background:#f5f5f3;
  border-radius:1.25em;
  padding:.95em .4em;
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:.35em
}
.ft svg {
  width:1.7em;
  height:1.7em;
  color:#141414
}
.ft i {
  font-style:normal;
  font-size:1.05em
}
.mort {
  background:#f5f5f3;
  border-radius:1.6em;
  padding:1.25em 1.4em;
  display:flex;
  flex-direction:column;
  gap:.55em
}
.mort .h {
  display:flex;
  justify-content:space-between;
  font-size:1.02em;
  color:#8b8b8b
}
.mort .h u {
  text-decoration:none;
  color:#141414;
  font-weight:500
}
.mort b {
  font-size:2em;
  font-weight:300;
  letter-spacing:-.02em
}
.bar {
  height:.5em;
  border-radius:1em;
  background:#ededed;
  overflow:hidden
}
.bar i {
  display:block;
  height:100%;
  width:62%;
  background:#141414;
  border-radius:1em
}
.mort small {
  font-size:.98em;
  color:#8b8b8b
}
.cta {
  margin-top:auto;
  display:flex;
  gap:.7em
}
.btn {
  flex:1;
  height:4.7em;
  border-radius:2.4em;
  background:#141414;
  color:#fff;
  display:grid;
  place-items:center
}
.btn i {
  font-style:normal;
  font-size:1.25em;
  font-weight:500
}
.sq {
  width:4.7em;
  height:4.7em;
  border-radius:50%;
  background:#f5f5f3;
  display:grid;
  place-items:center
}
.sq svg {
  width:1.8em;
  height:1.8em
}
.home {
  flex:1;
  min-height:0;
  border-radius:2em;
  background:#cbbd9f center/cover;
  position:relative;
  overflow:hidden
}
.home .ov {
  position:absolute;
  inset:auto 0 0;
  padding:4em 1.5em 1.4em;
  background:linear-gradient(180deg,transparent,rgba(20,24,14,.68));
  color:#fff;
  display:flex;
  flex-direction:column;
  gap:.45em
}
.home .ov small {
  font-size:1em;
  opacity:.85
}
.home .ov b {
  font-size:1.7em;
  font-weight:600
}
.home .bar {
  background:rgba(255,255,255,.3)
}
.home .bar i {
  width:85%;
  background:#fff
}
.home .meta {
  display:flex;
  justify-content:space-between;
  font-size:.98em;
  opacity:.9
}
.rqs {
  display:flex;
  flex-direction:column;
  gap:.6em;
  flex-shrink:0
}
.rq {
  display:flex;
  align-items:center;
  gap:1em;
  background:#f5f5f3;
  border-radius:1.4em;
  padding:.8em
}
.rq .ic {
  width:3.5em;
  height:3.5em;
  border-radius:1.1em;
  display:grid;
  place-items:center;
  flex-shrink:0
}
.rq .ic svg {
  width:1.6em;
  height:1.6em
}
.rq .tx {
  flex:1;
  min-width:0
}
.rq b {
  display:block;
  font-size:1.12em;
  font-weight:600
}
.rq small {
  display:block;
  font-size:.95em;
  color:#8b8b8b
}
.pill {
  font-size:.92em;
  padding:.3em .8em;
  border-radius:2em;
  white-space:nowrap;
  font-weight:500
}
.pay {
  background:#dcefe0;
  color:#141414;
  border-radius:1.7em;
  padding:1.2em 1.4em;
  display:flex;
  justify-content:space-between;
  align-items:center;
  flex-shrink:0;
  margin-bottom:.4em
}
.pay small {
  display:block;
  font-size:.98em;
  opacity:.6
}
.pay b {
  display:block;
  font-size:1.6em;
  font-weight:600
}
.pay span {
  background:#141414;
  color:#fff;
  border-radius:2em;
  padding:.7em 1.5em
}
.pay span i {
  font-style:normal;
  font-size:1.1em;
  font-weight:600
}
.lg {
  flex:1;
  padding:3.5em 2.2em 3em;
  display:flex;
  flex-direction:column;
  gap:1.1em
}
.lg .lgo {
  align-self:flex-start;
  width:5.2em;
  height:5.2em;
  border-radius:50%;
  display:grid;
  place-items:center;
  color:#fff;
  margin-bottom:1em
}
.lg .lgo i {
  font-style:normal;
  font-size:2.1em;
  font-weight:500
}
.lg>b {
  font-size:2.6em;
  line-height:1.08;
  color:#141414
}
.lg p {
  font-size:1.1em;
  color:#8b8b8b;
  margin:0 0 1em
}
.fld {
  height:4.4em;
  border-radius:2.2em;
  background:#f5f5f3;
  border:1px solid #eaeaea;
  padding:0 1.5em;
  display:flex;
  align-items:center
}
.fld i {
  font-style:normal;
  font-size:1.12em;
  color:#b0b0b0
}
.lg .btn {
  flex:none;
  margin-top:auto
}
.lg .alt {
  text-align:center;
  font-size:1.05em;
  color:#8b8b8b
}
.ph.wire .scr {
  filter:grayscale(1) contrast(.9)
}
.ph.wire .ed-photo {
  background-image:none!important;
  background:repeating-linear-gradient(45deg,#e4e1dc 0 .6em,#eeece8 .6em 1.2em)
}
.lg.v1 {
  padding-top:2.5em
}
.lg.v1 .lgo {
  border-radius:.5em;
  width:100%;
  height:4.6em;
  align-self:stretch;
  justify-content:start;
  padding-left:1.2em;
  margin-bottom:1.6em
}
.lg.v1 .lgo i {
  font-size:1.4em;
  font-weight:700
}
.lg.v1>b {
  font-family:Arial,Helvetica,sans-serif;
  font-weight:700;
  font-size:2.3em;
  letter-spacing:-.01em
}
.lg.v1 .fld {
  border-radius:.4em;
  background:#eef1f6;
  border:0
}
.lg.v1 .btn {
  border-radius:.4em
}
.lg.v2 {
  background:#0e5e45;
  color:#fff
}
.lg.v2 .lgo {
  background:#fff!important;
  color:#0e5e45
}
.lg.v2 .ed-eb,.lg.v2 p,.lg.v2 .alt {
  color:rgba(255,255,255,.7)
}
.lg.v2>b {
  font-family:Georgia,serif;
  font-weight:400;
  color:#fff;
  font-size:2.8em;
  letter-spacing:0
}
.lg.v2 .fld {
  background:transparent;
  border:0;
  border-bottom:1px solid rgba(255,255,255,.5);
  border-radius:0;
  padding:0
}
.lg.v2 .fld i {
  color:rgba(255,255,255,.6)
}
.lg.v2 .btn {
  background:transparent!important;
  border:1.5px solid #fff;
  border-radius:0
}
.lg.v3 {
  background:#fff4ec;
  align-items:center;
  text-align:center
}
.lg.v3 .lgo {
  align-self:center;
  border-radius:1.4em
}
.lg.v3>b {
  font-weight:800;
  font-size:2.4em;
  color:#b6451a;
  letter-spacing:-.02em
}
.lg.v3 .fld {
  align-self:stretch;
  border-radius:2.2em;
  border:2px solid #f2c9b1;
  background:#fff
}
.lg.v3 .btn {
  align-self:stretch;
  border-radius:2.4em;
  box-shadow:0 .6em 1.2em -.4em rgba(226,102,45,.6)
}
/* ---------- hero art ---------- */
.sp-hero-art {
  container-type:inline-size;
  position:relative;
  background:var(--sp-sand)!important;
  overflow:hidden
}
.sp-hero-art .p2-corner {
  background:rgba(35,38,29,.85)
}
@media(max-width:1100px) {
  .sp-hero-art .p2-corner.right {
    display:none
  }
}
.sp-hero-art .ph {
  position:absolute;
  --pw:20cqw;
  top:6.5cqw;
  animation:sp-float 8s ease-in-out infinite
}
.sp-hero-art .ph.h1 {
  left:12cqw
}
.sp-hero-art .ph.h2 {
  left:40cqw;
  animation-delay:-2.6s
}
.sp-hero-art .ph.h3 {
  left:68cqw;
  animation-delay:-5.2s
}
.sp-hl {
  position:absolute;
  top:2.4cqw;
  width:20cqw;
  text-align:center;
  font-family:var(--p2-mono);
  font-size:max(9px,1.05cqw);
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-ink)
}
.sp-hsys {
  position:absolute;
  left:12cqw;
  right:12cqw;
  bottom:2.2cqw;
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:2cqw;
  background:#141414;
  color:#fff;
  border-radius:1.2cqw;
  padding:1.1cqw 1.8cqw;
  z-index:3
}
.sp-hsys span {
  font-family:var(--p2-mono);
  font-size:max(9px,1cqw);
  letter-spacing:.06em;
  text-transform:uppercase;
  color:rgba(255,255,255,.65)
}
.sp-hsys b {
  font-size:max(10px,1.35cqw);
  font-weight:500
}
@media(max-width:700px) {
  .sp-hsys span {
    display:none
  }
}

.sp-fc {
  position:absolute;
  z-index:4;
  background:rgba(255,255,255,.95);
  border-radius:1.2cqw;
  padding:1.1cqw 1.4cqw;
  display:flex;
  align-items:center;
  gap:1cqw;
  box-shadow:0 2cqw 3cqw -1.5cqw rgba(0,0,0,.22);
  font-size:max(10px,1.15cqw);
  line-height:1.3
}
.sp-fc .ok {
  width:2.6cqw;
  height:2.6cqw;
  border-radius:50%;
  background:#36412a;
  color:#fff;
  display:grid;
  place-items:center;
  flex-shrink:0
}
.sp-fc .ok svg {
  width:1.3cqw;
  height:1.3cqw;
  fill:none;
  stroke:currentColor;
  stroke-width:2.4
}
.sp-fc b {
  display:block;
  font-weight:500
}
.sp-fc small {
  color:var(--p2-mute)
}
.sp-fc.a {
  left:8cqw;
  bottom:12cqw
}
.sp-fc.b {
  right:7cqw;
  top:14cqw
}
.sp-fc.b .ok {
  background:#9a7b4f
}
/* ---------- unify ---------- */
.sp-unify {
  background:var(--sp-sand);
  border-radius:18px;
  padding:32px;
  position:relative;
  overflow:hidden
}
.sp-unify-head {
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:16px;
  margin-bottom:8px;
  flex-wrap:wrap
}
.sp-ustage {
  container-type:inline-size;
  position:relative;
  aspect-ratio:16/8
}
.sp-lay {
  position:absolute;
  inset:0;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:5cqw;
  transition:opacity .8s cubic-bezier(.22,1,.36,1),scale .8s cubic-bezier(.22,1,.36,1)
}
.sp-lay .ph {
  --pw:19cqw
}
.sp-lay.after .ph {
  --pw:21.5cqw
}
.sp-unify[data-state="before"] .after,.sp-unify[data-state="after"] .before {
  opacity:0;
  scale:.94;
  pointer-events:none
}
.sp-ann {
  position:absolute;
  width:24cqw;
  font-size:max(11px,1.35cqw);
  line-height:1.4;
  color:var(--p2-ink-soft)
}
.sp-ann b {
  display:block;
  font-family:var(--p2-mono);
  font-size:max(9px,1cqw);
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--p2-ink);
  font-weight:500;
  margin-bottom:.5cqw
}
.sp-ann.l {
  left:4cqw;
  top:30%;
  text-align:right
}
.sp-ann.r {
  right:4cqw;
  top:55%
}
.sp-ann::after {
  content:"";
  position:absolute;
  top:1cqw;
  height:1px;
  width:8cqw;
  background:var(--p2-ink)
}
.sp-ann.l::after {
  left:calc(100% + 1.5cqw)
}
.sp-ann.r::after {
  right:calc(100% + 1.5cqw)
}
/* ---------- methodology art ---------- */
.sp-art {
  container-type:inline-size;
  background:var(--sp-sand);
  border-radius:18px;
  aspect-ratio:4/3;
  position:relative;
  overflow:hidden
}
.sp-art .cap {
  position:absolute;
  left:16px;
  bottom:14px;
  font-family:var(--p2-mono);
  font-size:10px;
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--p2-ink-soft);
  z-index:5
}
/* board */
.sp-board {
  position:absolute;
  inset:0;
  background:var(--sp-sand);
  background-image:radial-gradient(circle at 1px 1px,rgba(0,0,0,.09) 1px,transparent 0);
  background-size:16px 16px
}
.sp-tool {
  position:absolute;
  top:2.4cqw;
  left:50%;
  translate:-50% 0;
  display:flex;
  gap:1.6cqw;
  background:#fff;
  border-radius:1.4cqw;
  padding:1cqw 1.8cqw;
  box-shadow:0 .6cqw 2cqw rgba(0,0,0,.08);
  z-index:3
}
.sp-tool i {
  width:2.2cqw;
  height:2.2cqw;
  border-radius:.5cqw;
  background:#e8e4dc
}
.sp-tool i:nth-child(3) {
  background:#f6e3a6
}
.sp-tool i:nth-child(4) {
  background:#141414;
  border-radius:50%
}
.sp-sec {
  position:absolute;
  top:10cqw;
  height:52cqw;
  width:22.5cqw;
  border-radius:1.4cqw;
  opacity:0;
  scale:.97;
  transition:opacity .5s .8s,scale .5s .8s
}
.sp-sec span {
  position:absolute;
  top:-.2cqw;
  left:1.2cqw;
  translate:0 -50%;
  font-size:max(9px,1.45cqw);
  font-weight:500;
  padding:.5cqw 1.1cqw;
  border-radius:.7cqw;
  color:#fff;
  white-space:nowrap
}
.is-active .sp-sec {
  opacity:1;
  scale:1
}
.sp-st {
  position:absolute;
  width:19cqw;
  min-height:15cqw;
  padding:1.4cqw;
  font-size:max(9px,1.55cqw);
  line-height:1.3;
  box-shadow:0 .5cqw 1.2cqw -.4cqw rgba(0,0,0,.22),0 .1cqw .2cqw rgba(0,0,0,.08);
  border-radius:.4cqw;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  gap:1cqw;
  transition:left 1s cubic-bezier(.22,1,.36,1),top 1s cubic-bezier(.22,1,.36,1),rotate 1s;
  z-index:2;
  color:#1d1a15
}
.sp-st small {
  font-size:max(8px,1.2cqw);
  color:rgba(0,0,0,.5);
  display:flex;
  align-items:center;
  gap:.6cqw
}
.sp-st small::before {
  content:"";
  width:1.6cqw;
  height:1.6cqw;
  border-radius:50%;
  background:currentColor;
  opacity:.5
}
.sp-cur {
  position:absolute;
  z-index:4;
  left:60%;
  top:70%;
  transition:left 1.4s cubic-bezier(.22,1,.36,1),top 1.4s cubic-bezier(.22,1,.36,1);
  pointer-events:none
}
.sp-cur svg {
  width:2.4cqw;
  height:2.4cqw;
  display:block
}
.sp-cur span {
  display:inline-block;
  margin:.2cqw 0 0 1.6cqw;
  background:#c94235;
  color:#fff;
  font-size:max(9px,1.3cqw);
  padding:.3cqw .9cqw;
  border-radius:.6cqw .6cqw .6cqw 0
}
/* IA wire */
.sp-ia2 .ph {
  --pw:25cqw;
  position:absolute;
  left:50%;
  top:9cqw;
  translate:-50% 0
}
.sp-strip {
  position:absolute;
  top:3cqw;
  left:3.4cqw;
  display:flex;
  align-items:center;
  gap:1cqw;
  font-size:max(10px,1.4cqw)
}
.sp-strip s {
  color:var(--p2-mute)
}
.sp-strip b {
  font-weight:500
}
.sp-co {
  position:absolute;
  width:27cqw;
  font-size:max(10px,1.45cqw);
  line-height:1.35;
  color:var(--p2-ink-soft);
  opacity:0;
  translate:0 1cqw;
  transition:opacity .5s,translate .5s
}
.sp-co b {
  display:block;
  color:var(--p2-ink);
  font-weight:500;
  margin-bottom:.3cqw
}
.sp-co .n {
  font-family:var(--p2-mono);
  font-size:max(9px,1.1cqw);
  color:var(--p2-mute);
  letter-spacing:.1em
}
.sp-co::after {
  content:"";
  position:absolute;
  top:1.1cqw;
  height:1px;
  background:var(--p2-ink);
  width:var(--ln,9cqw)
}
.sp-co::before {
  content:"";
  position:absolute;
  top:.6cqw;
  width:1.1cqw;
  height:1.1cqw;
  border-radius:50%;
  background:var(--sp-gold);
  border:2px solid #fff;
  box-shadow:0 0 0 1px var(--p2-ink)
}
.sp-co.l {
  left:3.4cqw;
  text-align:right
}
.sp-co.l::after {
  left:calc(100% + 1cqw)
}
.sp-co.l::before {
  left:calc(100% + 1cqw + var(--ln,9cqw))
}
.sp-co.r {
  right:3.4cqw
}
.sp-co.r::after {
  right:calc(100% + 1cqw)
}
.sp-co.r::before {
  right:calc(100% + 1cqw + var(--ln,9cqw))
}
.is-active .sp-co {
  opacity:1;
  translate:0 0
}
.is-active .sp-co:nth-of-type(2) {
  transition-delay:.15s
}
.is-active .sp-co:nth-of-type(3) {
  transition-delay:.3s
}
.is-active .sp-co:nth-of-type(4) {
  transition-delay:.45s
}
/* system sheet */
.sp-sys {
  position:absolute;
  inset:3.4cqw 3.4cqw 8cqw;
  display:grid;
  grid-template-columns:1fr 1fr;
  grid-template-rows:1fr 1fr;
  gap:2cqw
}
.sp-fr {
  background:#fff;
  border-radius:1.6cqw;
  padding:2.2cqw;
  display:flex;
  flex-direction:column;
  gap:1.6cqw;
  box-shadow:0 1cqw 2.4cqw -1.4cqw rgba(0,0,0,.18);
  opacity:0;
  translate:0 1.5cqw;
  transition:opacity .5s,translate .5s;
  min-width:0;
  overflow:hidden
}
.is-active .sp-fr {
  opacity:1;
  translate:0 0
}
.is-active .sp-fr:nth-child(2) {
  transition-delay:.12s
}
.is-active .sp-fr:nth-child(3) {
  transition-delay:.24s
}
.is-active .sp-fr:nth-child(4) {
  transition-delay:.36s
}
.sp-fl {
  display:flex;
  justify-content:space-between;
  font-family:var(--p2-mono);
  font-size:max(8px,1.15cqw);
  letter-spacing:.12em;
  text-transform:uppercase;
  color:var(--p2-mute)
}
.sp-sw {
  display:flex;
  gap:1cqw
}
.sp-sw i {
  flex:1;
  aspect-ratio:1;
  border-radius:50%;
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.08)
}
.sp-ty {
  display:flex;
  align-items:baseline;
  gap:1.4cqw
}
.sp-ty b {
  font-size:4cqw;
  font-weight:400;
  letter-spacing:-.03em;
  line-height:1
}
.sp-ty span {
  font-family:"IBM Plex Sans Arabic",sans-serif;
  font-size:3.4cqw;
  line-height:1
}
.sp-ty small {
  margin-left:auto;
  font-family:var(--p2-mono);
  font-size:max(8px,1.1cqw);
  color:var(--p2-mute)
}
.sp-at {
  display:flex;
  flex-wrap:wrap;
  gap:1cqw;
  align-items:center
}
.sp-b {
  font-size:max(9px,1.4cqw);
  padding:1cqw 1.8cqw;
  border-radius:99px;
  background:#141414;
  color:#fff;
  white-space:nowrap
}
.sp-b.g {
  background:transparent;
  color:#141414;
  box-shadow:inset 0 0 0 1px #141414
}
.sp-b.y {
  background:var(--sp-gold);
  color:#141414
}
.sp-tg {
  width:4.4cqw;
  height:2.5cqw;
  border-radius:99px;
  background:#141414;
  position:relative
}
.sp-tg::after {
  content:"";
  position:absolute;
  right:.35cqw;
  top:.35cqw;
  width:1.8cqw;
  height:1.8cqw;
  border-radius:50%;
  background:#fff
}
.sp-ck {
  width:2.5cqw;
  height:2.5cqw;
  border-radius:.6cqw;
  background:var(--sp-gold);
  display:grid;
  place-items:center
}
.sp-ck svg {
  width:1.6cqw;
  height:1.6cqw;
  fill:none;
  stroke:#141414;
  stroke-width:3
}
.sp-chip {
  font-size:max(9px,1.25cqw);
  padding:.7cqw 1.4cqw;
  border-radius:99px;
  background:rgba(212,165,72,.2);
  color:#7d5a10
}
.sp-in {
  display:flex;
  align-items:center;
  gap:1cqw;
  border:1px solid #e6e1d8;
  border-radius:1.2cqw;
  padding:1.2cqw 1.4cqw;
  font-size:max(9px,1.35cqw);
  color:var(--p2-mute)
}
.sp-in svg {
  width:1.8cqw;
  height:1.8cqw;
  fill:none;
  stroke:currentColor;
  stroke-width:2
}
.sp-in kbd {
  margin-left:auto;
  font-family:var(--p2-mono);
  font-size:max(8px,1.05cqw);
  background:#f2efe9;
  padding:.3cqw .7cqw;
  border-radius:.5cqw
}
.sp-seg {
  display:flex;
  background:#f2efe9;
  border-radius:1.2cqw;
  padding:.5cqw
}
.sp-seg span {
  flex:1;
  text-align:center;
  font-size:max(9px,1.3cqw);
  padding:.8cqw;
  border-radius:.9cqw;
  color:var(--p2-ink-soft)
}
.sp-seg span.on {
  background:#fff;
  color:#141414;
  box-shadow:0 .2cqw .6cqw rgba(0,0,0,.08)
}
.sp-oc {
  display:flex;
  gap:1.4cqw;
  align-items:center;
  flex:1;
  min-height:0
}
.sp-oc .im {
  width:40%;
  align-self:stretch;
  border-radius:1.2cqw;
  background:#cbbd9f center/cover
}
.sp-oc b {
  display:block;
  font-size:max(10px,1.6cqw);
  font-weight:500
}
.sp-oc small {
  display:block;
  font-size:max(9px,1.2cqw);
  color:var(--p2-mute);
  margin:.3cqw 0 1cqw
}
.sp-oc em {
  font-style:normal;
  font-size:max(10px,1.5cqw);
  font-weight:600
}
/* parity */
.sp-par2 {
  position:absolute;
  inset:3cqw 3cqw 8cqw;
  display:flex;
  justify-content:center;
  align-items:center;
  gap:9cqw
}
.sp-par2 .ph {
  --pw:28.5cqw
}
.sp-axis {
  position:absolute;
  left:50%;
  top:0;
  bottom:0;
  border-left:1px dashed var(--p2-ink)
}
.sp-axis span {
  position:absolute;
  top:50%;
  left:0;
  translate:-50% -50%;
  writing-mode:vertical-rl;
  background:var(--sp-sand);
  padding:1cqw 0;
  font-family:var(--p2-mono);
  font-size:max(8px,1.1cqw);
  letter-spacing:.14em;
  text-transform:uppercase;
  white-space:nowrap
}
.sp-plab {
  position:absolute;
  top:0;
  font-family:var(--p2-mono);
  font-size:max(8px,1.1cqw);
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--p2-ink-soft)
}
/* bilingual card photo */
.p2-bili-card .card-media {
  background:#cbbd9f url("https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=900&q=70") center/cover!important
}
.p2-bili-card .card-media::after {
  display:none!important
}
/* locked */
.sp-lock {
  background:#23261d;
  color:#fff;
  padding:120px 0
}
.sp-lock .p2-section-title {
  color:#fff
}
.sp-lock .p2-section-blurb {
  color:rgba(255,255,255,.65)
}
.sp-lock .p2-eyebrow {
  color:rgba(255,255,255,.5)
}
.sp-lock .p2-eyebrow .num {
  border-color:rgba(255,255,255,.5)
}
.sp-lock-grid {
  display:grid;
  grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);
  gap:56px;
  align-items:start
}
.sp-chapters {
  list-style:none;
  margin:0;
  padding:0;
  border-top:1px solid rgba(255,255,255,.14)
}
.sp-chapters li {
  display:grid;
  grid-template-columns:40px minmax(0,1fr) auto;
  gap:16px;
  align-items:center;
  padding:20px 0;
  border-bottom:1px solid rgba(255,255,255,.14)
}
.sp-chapters .n {
  font-family:var(--p2-mono);
  font-size:11px;
  color:rgba(255,255,255,.45)
}
.sp-chapters .t {
  font-size:18px
}
.sp-chapters .t small {
  display:block;
  font-size:13px;
  color:rgba(255,255,255,.55);
  margin-top:4px
}
.sp-chapters svg {
  width:14px;
  height:14px;
  stroke:rgba(255,255,255,.55);
  fill:none;
  stroke-width:1.6
}
.sp-gate {
  background:#fff;
  color:var(--p2-ink);
  border-radius:18px;
  padding:36px;
  display:flex;
  flex-direction:column;
  gap:16px;
  position:sticky;
  top:100px
}
.sp-gate h3 {
  font-size:28px;
  font-weight:400;
  letter-spacing:-.01em;
  line-height:1.15
}
.sp-gate p {
  font-size:14px;
  line-height:1.55;
  color:var(--p2-ink-soft)
}
.sp-gate .password-row {
  margin-top:8px
}
.sp-gate .error-message {
  min-height:18px;
  font-size:13px;
  color:#a33a2c
}
.sp-gate .alt a {
  color:var(--p2-ink);
  text-decoration:underline;
  text-underline-offset:3px
}
@media(max-width:900px) {
  .sp-lock-grid {
    grid-template-columns:1fr
  }
  .sp-gate {
    position:static
  }
  .sp-lock {
    padding:80px 0
  }
}
/* ---------- type: no mono, no italics ---------- */
.p2-page .p2-hero-title em,.p2-page .p2-section-title em,.p2-page .p2-next-link em,.p2-page h3 em,.p2-page h4 em {
  font-style:normal;
  color:var(--p2-mute)
}
.p2-page .p2-eyebrow,.p2-page .tab-no,.p2-page .stat-no,.p2-page .p2-corner,.p2-page .sp-note,.p2-page .p2-bili-hint,.p2-page .p2-next-eyebrow,.p2-page .cap {
  letter-spacing:.06em
}
/* ---------- role ---------- */
.sp-org {
  container-type:inline-size;
  background:var(--sp-sand);
  border-radius:18px;
  padding:48px 32px 32px
}
.sp-streams {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:3cqw
}
.sp-stream {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:22px;
  text-align:center;
  position:relative;
  padding-bottom:44px
}
.sp-stream::after {
  content:"";
  position:absolute;
  bottom:0;
  left:50%;
  height:30px;
  border-left:1px solid var(--p2-ink)
}
.sp-stream .ph {
  --pw:min(27cqw,330px)
}
.sp-lab span {
  display:block;
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute)
}
.sp-lab b {
  display:block;
  font-size:20px;
  font-weight:500;
  margin-top:6px
}
.sp-stream>p {
  font-size:14px;
  line-height:1.5;
  color:var(--p2-ink-soft);
  max-width:28ch;
  margin:0
}
.sp-base {
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:8px 16px;
  flex-wrap:wrap;
  background:#fff;
  border-radius:14px;
  padding:20px 24px
}
.sp-base span {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute)
}
.sp-base b {
  font-size:17px;
  font-weight:500
}
.sp-base.sys {
  background:var(--sp-olive);
  color:#fff
}
.sp-base.sys span {
  color:rgba(255,255,255,.7)
}
.sp-wire {
  height:20px;
  width:0;
  margin:0 auto;
  border-left:1px solid var(--p2-ink)
}
.sp-own {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:32px;
  margin-top:56px
}
.sp-own div {
  border-top:1px solid var(--p2-ink);
  padding-top:18px
}
.sp-own span {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  color:var(--p2-mute)
}
.sp-own h4 {
  font-size:19px;
  font-weight:500;
  margin:10px 0 8px
}
.sp-own p {
  font-size:14px;
  line-height:1.55;
  color:var(--p2-ink-soft);
  margin:0
}
@media(max-width:900px) {
  .sp-own {
    grid-template-columns:1fr 1fr
  }
}
@media(max-width:700px) {
  .sp-org {
    padding:28px 14px 14px
  }
  .sp-stream .ph {
    --pw:27cqw
  }
  .sp-lab b {
    font-size:14px
  }
  .sp-stream>p {
    display:none
  }
  .sp-own {
    grid-template-columns:1fr
  }
}
/* ---------- outcomes ---------- */
.sp-out {
  padding-bottom:40px
}
.sp-attr {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:16px
}
.sp-col {
  background:var(--sp-sand);
  border-radius:18px;
  padding:28px
}
.sp-col.me {
  background:var(--sp-olive);
  color:#fff
}
.sp-col span {
  display:block;
  font-family:var(--p2-mono);
  font-size:12px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute);
  margin-bottom:20px
}
.sp-col.me span {
  color:rgba(255,255,255,.7)
}
.sp-col ul {
  list-style:none;
  margin:0;
  padding:0;
  display:flex;
  flex-direction:column
}
.sp-col li {
  font-size:16px;
  line-height:1.4;
  padding:12px 0;
  border-top:1px solid rgba(0,0,0,.12)
}
.sp-col.me li {
  border-color:rgba(255,255,255,.2)
}
@media(max-width:900px) {
  .sp-attr {
    grid-template-columns:1fr
  }
}
.p2-page .stat-num {
  font-size:clamp(40px,5vw,72px)
}
.p2-page .p2-stats-grid {
  grid-template-columns:repeat(4,minmax(0,1fr))
}
@media(max-width:1000px) {
  .p2-page .p2-stats-grid {
    grid-template-columns:repeat(2,minmax(0,1fr));
    row-gap:32px
  }
  .p2-page .p2-stat {
    padding-left:0!important
  }
}
.sp-stream .ph {
  text-align:start
}
/* ---------- before/after tags ---------- */
.sp-pc {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:2cqw
}
.sp-tag {
  display:inline-flex;
  align-items:center;
  gap:.7cqw;
  font-size:max(11px,1.35cqw);
  font-weight:500;
  padding:.8cqw 1.6cqw;
  border-radius:99px;
  white-space:nowrap;
  color:#fff;
  background:#b3261e;
  box-shadow:0 .6cqw 1.4cqw -.6cqw rgba(179,38,30,.6)
}
.sp-tag.ok {
  background:#141414;
  box-shadow:0 .6cqw 1.4cqw -.6cqw rgba(0,0,0,.5)
}
.sp-tag small {
  font-size:inherit;
  opacity:.75;
  font-weight:400
}
.sp-ustage {
  aspect-ratio:16/8.6
}
@media(max-width:700px) {
  .sp-unify {
    padding:20px
  }
  .sp-ustage {
    aspect-ratio:4/3.8
  }
  .sp-lay {
    gap:2cqw
  }
  .sp-lay .ph {
    --pw:28cqw
  }
  .sp-lay.after .ph {
    --pw:36cqw
  }
  .sp-ann {
    display:none
  }
  .sp-tag small {
    display:none
  }
}
/* ---------- property card: one type token ---------- */
.p2-page .p2-bili-card,.p2-page .p2-bili-card[data-dir="rtl"] .card-arabic {
  font-family:"Switzer","IBM Plex Sans Arabic",sans-serif
}
.p2-page .p2-spec-list li {
  grid-template-columns:96px 1fr
}
.p2-spec-list .v small {
  display:block;
  color:var(--p2-mute);
  font-size:12px;
  margin-top:2px
}
/* ---------- outcomes equation ---------- */
.sp-eq {
  display:grid;
  grid-template-columns:minmax(0,1fr) auto minmax(0,1fr) auto minmax(0,1.25fr);
  align-items:stretch;
  gap:16px
}
.sp-op {
  align-self:center;
  width:52px;
  height:52px;
  border-radius:50%;
  background:#fff;
  border:1px solid rgba(0,0,0,.12);
  display:grid;
  place-items:center;
  font-size:26px;
  font-weight:300;
  line-height:1
}
.sp-col.res {
  background:#141414;
  color:#fff
}
.sp-col.res span {
  color:rgba(255,255,255,.6)
}
.sp-res {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:24px 20px
}
.sp-res b {
  display:block;
  font-size:clamp(32px,3.4vw,48px);
  font-weight:300;
  letter-spacing:-.03em;
  line-height:1
}
.sp-res small {
  display:block;
  font-size:13px;
  line-height:1.4;
  color:rgba(255,255,255,.7);
  margin-top:8px
}
.sp-col.res p {
  margin:24px 0 0;
  padding-top:16px;
  border-top:1px solid rgba(255,255,255,.2);
  font-size:14px;
  line-height:1.5;
  color:rgba(255,255,255,.8)
}
.sp-col.me {
  background:var(--sp-sand);
  color:var(--p2-ink)
}
.sp-col.me span {
  color:var(--p2-mute)
}
.sp-col.me li {
  border-color:rgba(0,0,0,.12)
}
.sp-col.tm {
  background:#fff;
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.1)
}
@media(max-width:1000px) {
  .sp-eq {
    grid-template-columns:1fr
  }
  .sp-op {
    justify-self:center
  }
}
.sp-conf {
  max-width:760px;
  margin:0 0 28px;
  padding:14px 18px;
  border-radius:12px;
  background:var(--sp-sand);
  border:1px solid rgba(0,0,0,.08);
  font-size:14px;
  line-height:1.5;
  color:var(--p2-ink-soft)
}
.sp-conf strong {
  color:var(--p2-ink);
  font-weight:500
}
/* no staged reveals inside illustrations */
.sp-co,.sp-fr,.sp-sec {
  opacity:1!important;
  translate:none!important;
  scale:none!important;
  transition:none!important
}


/* Original: copilot-preview.css */
:scope {
  --cp-navy:#0b1a2e;
  --cp-blue:#2f5bff
}
/* skins: one component, three clients */
.sk-air {
  --bg:#0b1a2e;
  --fg:#fff;
  --mu:#8ea0bd;
  --card:#15294a;
  --acc:#2f5bff;
  --bub:#1a3480;
  --line:rgba(255,255,255,.1)
}
.sk-ret {
  --bg:#fbf7f1;
  --fg:#1d1a16;
  --mu:#8a8276;
  --card:#fff;
  --acc:#1d1a16;
  --bub:#efe6d8;
  --line:rgba(0,0,0,.08)
}
.sk-bank {
  --bg:#121212;
  --fg:#fff;
  --mu:#9a9a9a;
  --card:#1f1f1f;
  --acc:#e0312b;
  --bub:#2a2a2a;
  --line:rgba(255,255,255,.1)
}
.scr[class*="sk-"] {
  background:var(--bg);
  color:var(--fg)
}
.scr[class*="sk-"]::after {
  background:var(--fg)
}
.sk-ret {
  font-family:"Switzer",sans-serif
}
.cp-head {
  display:flex;
  justify-content:space-between;
  align-items:center;
  padding:.4em 1.6em 1em;
  border-bottom:1px solid var(--line);
  flex-shrink:0
}
.cp-brand {
  display:flex;
  align-items:center;
  gap:.5em
}
.cp-brand svg {
  width:1.5em;
  height:1.5em
}
.cp-brand b {
  font-size:1.25em;
  font-weight:600
}
.sk-ret .cp-brand b {
  font-family:Georgia,serif;
  font-weight:400;
  font-size:1.45em;
  letter-spacing:.02em
}
.cp-ai {
  display:flex;
  align-items:center;
  gap:.5em;
  font-size:.95em;
  color:var(--mu)
}
.cp-ai i {
  font-style:normal
}
.cp-msgs {
  flex:1;
  min-height:0;
  overflow:hidden;
  display:flex;
  flex-direction:column;
  justify-content:flex-end;
  gap:.75em;
  padding:1em 1.4em
}
.cb {
  max-width:85%;
  font-size:1.1em;
  line-height:1.38;
  padding:.8em 1em;
  border-radius:1.2em
}
.cb.u {
  align-self:flex-end;
  background:var(--card);
  border-bottom-right-radius:.3em;
  box-shadow:0 0 0 1px var(--line)
}
.cb.a {
  align-self:flex-start;
  display:flex;
  gap:.6em;
  align-items:flex-start;
  background:var(--bub);
  border-bottom-left-radius:.3em;
  max-width:92%
}
.sk-air .cb.a,.sk-bank .cb.a {
  color:#fff
}
.cb.a .orb.av {
  margin-top:.1em
}
.cb.ty {
  padding:.7em 1em
}
.dots {
  display:flex;
  gap:.3em;
  align-items:center;
  height:1.6em
}
.dots i {
  width:.45em;
  height:.45em;
  border-radius:50%;
  background:currentColor;
  opacity:.4;
  animation:cp-dot 1.2s infinite
}
.dots i:nth-child(2) {
  animation-delay:.2s
}
.dots i:nth-child(3) {
  animation-delay:.4s
}

.cr {
  align-self:flex-start;
  display:flex;
  align-items:center;
  gap:.45em;
  font-size:.92em;
  color:var(--mu);
  padding:.35em .8em;
  border-radius:2em;
  box-shadow:inset 0 0 0 1px var(--line)
}
.cr svg {
  width:1.15em;
  height:1.15em
}
.co {
  display:flex;
  flex-direction:column;
  gap:.5em
}
.opt {
  display:flex;
  justify-content:space-between;
  align-items:center;
  background:var(--card);
  border-radius:1em;
  padding:.8em 1em;
  box-shadow:0 0 0 1px var(--line)
}
.opt small {
  display:block;
  font-size:.85em;
  color:var(--mu)
}
.opt b {
  display:block;
  font-size:1.25em;
  font-weight:500;
  margin:.1em 0
}
.opt em {
  font-style:normal;
  font-size:1.6em;
  font-weight:300
}
.cpr {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:.6em
}
.cpr>div {
  background:var(--card);
  border-radius:1em;
  padding:.5em;
  box-shadow:0 0 0 1px var(--line)
}
.cpr .im {
  display:block;
  aspect-ratio:1;
  border-radius:.7em;
  margin-bottom:.5em
}
.cpr b {
  display:block;
  font-size:1.05em;
  font-weight:500
}
.cpr small {
  font-size:.95em;
  color:var(--mu)
}
.qr {
  display:flex;
  gap:.5em
}
.qr span {
  flex:1;
  text-align:center;
  font-size:1.02em;
  padding:.8em .4em;
  border-radius:2em;
  box-shadow:inset 0 0 0 1px var(--line);
  background:var(--card)
}
.qr span.y {
  background:var(--acc);
  color:#fff;
  box-shadow:none
}
.hand {
  display:flex;
  gap:.8em;
  align-items:center;
  padding:.8em 1em;
  border-radius:1em;
  background:var(--card);
  box-shadow:0 0 0 1px var(--line)
}
.hand svg {
  width:2.2em;
  height:2.2em;
  padding:.45em;
  border-radius:50%;
  background:var(--acc);
  color:#fff;
  flex-shrink:0
}
.hand b {
  display:block;
  font-size:1.05em;
  font-weight:500
}
.hand small {
  font-size:.92em;
  color:var(--mu)
}
.ci {
  display:flex;
  align-items:center;
  justify-content:space-between;
  margin:0 1.4em 2.6em;
  padding:.45em .5em .45em 1.3em;
  border-radius:2em;
  background:var(--card);
  box-shadow:0 0 0 1px var(--line);
  flex-shrink:0
}
.ci span {
  font-size:1.08em;
  color:var(--mu)
}
/* orb */
.orb {
  display:inline-block;
  flex-shrink:0;
  border-radius:50%;
  background:radial-gradient(circle at 35% 30%,rgba(255,255,255,.95) 0 12%,transparent 34%),conic-gradient(from 0deg,#5b6cff,#ff7a9c,#7fd8ff,#b49cff,#5b6cff);
  animation:cp-spin 6s linear infinite;
  box-shadow:0 0 .8em rgba(120,130,255,.45)
}
.orb.sm {
  width:1.6em;
  height:1.6em
}
.orb.av {
  width:1.8em;
  height:1.8em
}
.orb.in {
  width:2.8em;
  height:2.8em
}
.orb.tb {
  width:4em;
  height:4em
}

/* airline home */
.cp-pad {
  flex:1;
  min-height:0;
  padding:.3em 1.7em 0;
  display:flex;
  flex-direction:column;
  gap:1.05em
}
.hm-top {
  display:flex;
  justify-content:space-between;
  align-items:center
}
.hm-top>span>svg {
  width:1.6em;
  height:1.6em
}
.hm-h {
  font-size:2.3em;
  font-weight:500;
  line-height:1.1;
  letter-spacing:-.02em
}
.hm-f {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:.55em
}
.hm-f span {
  background:var(--card);
  border-radius:.8em;
  padding:.6em .8em;
  font-size:1.05em
}
.hm-f small {
  display:block;
  font-size:.82em;
  color:var(--mu)
}
.hm-btn {
  background:var(--acc);
  border-radius:.8em;
  text-align:center;
  padding:.9em;
  font-size:1.15em;
  font-weight:500
}
.hm-s {
  font-size:1.2em;
  font-weight:500
}
.hm-sug {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:.55em
}
.hm-sug span {
  background:linear-gradient(160deg,#2f5bff,#2546c4);
  border-radius:.9em;
  padding:.8em;
  display:flex;
  flex-direction:column;
  gap:.15em
}
.hm-sug svg {
  width:1.4em;
  height:1.4em;
  margin-bottom:.3em
}
.hm-sug b {
  font-size:1.05em;
  font-weight:500
}
.hm-sug small {
  font-size:.88em;
  opacity:.8
}
.hm-j {
  display:flex;
  align-items:center;
  gap:.8em;
  background:var(--card);
  border-radius:.9em;
  padding:.9em 1em
}
.hm-j small {
  font-size:.9em;
  color:var(--mu)
}
.hm-j b {
  display:block;
  font-size:1.5em;
  font-weight:500
}
.hm-j i {
  flex:1;
  height:0;
  border-top:1px dashed var(--mu)
}
.hm-tb {
  height:7em;
  flex-shrink:0;
  display:flex;
  justify-content:space-around;
  align-items:flex-start;
  padding:.9em .6em 0;
  border-top:1px solid var(--line);
  background:#0e2038
}
.hm-tb span {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:.3em;
  color:var(--mu);
  width:4.6em
}
.hm-tb svg {
  width:1.8em;
  height:1.8em
}
.hm-tb i {
  font-style:normal;
  font-size:.85em
}
.hm-tb span:first-child {
  color:#fff
}
.hm-tb .mid {
  margin-top:-1.6em
}
/* hero */
.cp-hero-art {
  container-type:inline-size;
  position:relative;
  overflow:hidden;
  background:var(--sp-sand)!important
}
.cp-hero-art::before {
  content:"";
  position:absolute;
  width:60cqw;
  height:60cqw;
  left:20cqw;
  top:-6cqw;
  border-radius:50%;
  background:radial-gradient(circle,rgba(139,128,255,.32),rgba(255,140,170,.18) 45%,transparent 70%);
  filter:blur(2cqw)
}
.cp-hero-art .ph {
  position:absolute;
  --pw:20cqw;
  top:6.5cqw
}
.cp-hero-art .ph.h1 {
  left:12cqw
}
.cp-hero-art .ph.h2 {
  left:40cqw
}
.cp-hero-art .ph.h3 {
  left:68cqw
}
/* simulator */
.cp-sim {
  display:grid;
  grid-template-columns:auto minmax(0,1fr);
  gap:32px;
  align-items:start;
  background:var(--sp-sand);
  border-radius:18px;
  padding:32px
}
.cp-sim .ph {
  --pw:280px
}
.cp-scn {
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-bottom:16px
}
.cp-scn button {
  font:inherit;
  font-size:14px;
  padding:10px 16px;
  border-radius:99px;
  border:1px solid rgba(0,0,0,.15);
  background:#fff;
  cursor:pointer;
  color:var(--p2-ink)
}
.cp-scn button[aria-pressed="true"] {
  background:var(--cp-navy);
  color:#fff;
  border-color:var(--cp-navy)
}
.cp-steps {
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:4px;
  background:#fff;
  border-radius:12px;
  padding:4px;
  margin-bottom:16px
}
.cp-steps button {
  font:inherit;
  font-size:13px;
  padding:10px;
  border:0;
  border-radius:9px;
  background:transparent;
  cursor:pointer;
  color:var(--p2-mute);
  display:flex;
  align-items:center;
  gap:8px;
  justify-content:center
}
.cp-steps button i {
  font-style:normal;
  width:20px;
  height:20px;
  border-radius:50%;
  background:#eceae6;
  color:var(--p2-ink);
  display:grid;
  place-items:center;
  font-size:11px
}
.cp-steps button[aria-pressed="true"] {
  background:var(--sp-sand);
  color:var(--p2-ink)
}
.cp-steps button[aria-pressed="true"] i {
  background:var(--cp-navy);
  color:#fff
}
.cp-pane {
  background:#fff;
  border-radius:14px;
  padding:24px;
  min-height:380px;
  display:flex;
  flex-direction:column;
  gap:16px
}
.cp-pane h4 {
  margin:0;
  font-size:20px;
  font-weight:500
}
.cp-pane>p {
  margin:0;
  font-size:14px;
  color:var(--p2-ink-soft);
  line-height:1.5
}
.cp-in {
  border-left:3px solid var(--cp-blue);
  padding:6px 12px;
  font-size:15px
}
.cp-ints {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:8px
}
.cp-int {
  border:1px solid #ecebe8;
  border-radius:10px;
  padding:12px;
  color:#b3b0aa
}
.cp-int b {
  display:block;
  font-size:14px;
  font-weight:500
}
.cp-int small {
  font-size:12px
}
.cp-int.on {
  border-color:var(--cp-blue);
  color:var(--p2-ink);
  box-shadow:0 0 0 1px var(--cp-blue)
}
.cp-int.on small {
  color:var(--cp-blue)
}
.cp-tbl {
  width:100%;
  border-collapse:collapse;
  font-size:13.5px
}
.cp-tbl th {
  text-align:left;
  font-weight:400;
  color:var(--p2-mute);
  font-size:12px;
  padding:0 8px 8px 0;
  border-bottom:1px solid #ecebe8
}
.cp-tbl td {
  padding:10px 8px 10px 0;
  border-bottom:1px solid #f2f1ee;
  vertical-align:top
}
.st {
  display:inline-flex;
  align-items:center;
  gap:6px;
  font-size:12px;
  padding:3px 9px;
  border-radius:99px;
  white-space:nowrap
}
.st.ok {
  background:#e3f4ea;
  color:#1f6b3e
}
.st.miss {
  background:#fdf0dc;
  color:#8a5a12
}
.st.no {
  background:#fbe3e1;
  color:#9c2a22
}
.cp-dec {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:8px
}
.cp-dec>div {
  border-radius:10px;
  padding:12px;
  background:var(--sp-sand)
}
.cp-dec small {
  display:block;
  font-family:var(--p2-mono);
  font-size:10.5px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute);
  margin-bottom:6px
}
.cp-dec b {
