  min-height:2.9em
}
.a-now {
  min-height:22px
}
.a-conn {
  overflow:visible
}
.a-conn::before {
  content:"";
  position:absolute;
  top:-3px;
  left:0;
  width:8px;
  height:8px;
  border-radius:50%;
  background:var(--cp-blue);
  opacity:0
