/* =========================================================
   PROJECT V2 â€” Cinematic, video-led project page treatment
   Layered on top of styles.css (keeps nav/footer chrome)
========================================================= */

:scope {
  --p2-ink: #0a0a0a;
  --p2-ink-soft: #555252;
  --p2-mute: #8a847b;
  --p2-line: #ededed;
  --p2-cream: #efe9e1;
  --p2-cream-deep: #e6dfd4;
  --p2-paper: #f6f4ef;
  --p2-mono: "Neue Haas Grotesk Display Pro", "Neue Haas Grotesk", "Helvetica Neue", Arial, sans-serif, "Switzer", sans-serif;
  --p2-display: "Switzer", sans-serif;
}
/* keep nav over hero */
.p2-page {
  color: var(--p2-ink);
}
.p2-page main {
  overflow: visible;
}
/* container */
.p2-wrap {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding-left: 100px;
  padding-right: 100px;
}
@media (max-width: 1100px) {
  .p2-wrap {
    padding-left: 40px;
    padding-right: 40px;
  }
}
@media (max-width: 700px) {
  .p2-wrap {
    padding-left: 24px;
    padding-right: 24px;
  }
}
/* reveal animation */
.p2-rise {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1), transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}
.p2-rise.is-in {
  opacity: 1;
  transform: none;
}
/* ============ HERO ============ */

.p2-hero {
  position: relative;
  padding-top: 64px;
  padding-bottom: 0;
  background: #ffffff;
}
.p2-hero-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  font-family: var(--p2-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--p2-ink-soft);
  text-transform: uppercase;
  margin-bottom: 56px;
}
.p2-hero-meta .slash {
