}
.p2-hero-lede {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  padding-bottom: 48px;
}
.p2-hero-sub {
  font-size: clamp(22px, 2vw, 28px);
  line-height: 1.25;
  font-weight: 300;
  color: var(--p2-ink);
  max-width: 540px;
}
.p2-hero-detail {
  font-size: 14px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
  max-width: 460px;
  justify-self: end;
}
.p2-hero-detail strong {
  color: var(--p2-ink);
  font-weight: 600;
}
.p2-hero-detail p + p {
  margin-top: 8px;
}
@media (max-width: 900px) {
  .p2-hero-lede {
    grid-template-columns: 1fr;
    gap: 32px;
  }
