    justify-self: start;
  }
}
/* ============ HERO VIDEO ============ */

.p2-hero-video {
  position: relative;
  width: calc(100% - 240px);
  max-width: 1100px;
  margin: 0 auto;
  aspect-ratio: 16 / 9;
  background: #04182b;
  overflow: hidden;
  border-radius: 24px;
}
.p2-video-fallback.hidden {
  display: none !important;
}
.p2-hero-video video,
.p2-hero-video .p2-video-fallback {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  background: #04182b;
}
.p2-video-fallback {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #efe9e1 0%, #e6dfd4 50%, #d9d0c1 100%);
