  height: 88px;
  border: 1.5px solid #7a6b58;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
}
.p2-video-fallback .fb-play::after {
  content: "";
  width: 0;
