.sp-tg {
  width:4.4cqw;
  height:2.5cqw;
  border-radius:99px;
  background:#141414;
  position:relative
}
.sp-tg::after {
  content:"";
  position:absolute;
  right:.35cqw;
  top:.35cqw;
  width:1.8cqw;
  height:1.8cqw;
  border-radius:50%;
  background:#fff
}
.sp-ck {
  width:2.5cqw;
  height:2.5cqw;
  border-radius:.6cqw;
  background:var(--sp-gold);
  display:grid;
  place-items:center
}
.sp-ck svg {
  width:1.6cqw;
  height:1.6cqw;
  fill:none;
  stroke:#141414;
  stroke-width:3
}
.sp-chip {
  font-size:max(9px,1.25cqw);
  padding:.7cqw 1.4cqw;
  border-radius:99px;
  background:rgba(212,165,72,.2);
  color:#7d5a10
}
.sp-in {
  display:flex;
  align-items:center;
  gap:1cqw;
  border:1px solid #e6e1d8;
  border-radius:1.2cqw;
  padding:1.2cqw 1.4cqw;
  font-size:max(9px,1.35cqw);
  color:var(--p2-mute)
}
.sp-in svg {
  width:1.8cqw;
  height:1.8cqw;
  fill:none;
  stroke:currentColor;
  stroke-width:2
}
.sp-in kbd {
  margin-left:auto;
  font-family:var(--p2-mono);
  font-size:max(8px,1.05cqw);
  background:#f2efe9;
  padding:.3cqw .7cqw;
  border-radius:.5cqw
}
.sp-seg {
  display:flex;
  background:#f2efe9;
  border-radius:1.2cqw;
  padding:.5cqw
}
.sp-seg span {
  flex:1;
  text-align:center;
  font-size:max(9px,1.3cqw);
  padding:.8cqw;
  border-radius:.9cqw;
  color:var(--p2-ink-soft)
}
.sp-seg span.on {
  background:#fff;
  color:#141414;
  box-shadow:0 .2cqw .6cqw rgba(0,0,0,.08)
}
.sp-oc {
  display:flex;
  gap:1.4cqw;
  align-items:center;
  flex:1;
  min-height:0
}
.sp-oc .im {
  width:40%;
  align-self:stretch;
  border-radius:1.2cqw;
  background:#cbbd9f center/cover
}
.sp-oc b {
  display:block;
  font-size:max(10px,1.6cqw);
  font-weight:500
}
.sp-oc small {
  display:block;
  font-size:max(9px,1.2cqw);
  color:var(--p2-mute);
  margin:.3cqw 0 1cqw
}
.sp-oc em {
  font-style:normal;
  font-size:max(10px,1.5cqw);
  font-weight:600
}
/* parity */
.sp-par2 {
  position:absolute;
  inset:3cqw 3cqw 8cqw;
  display:flex;
  justify-content:center;
  align-items:center;
  gap:9cqw
}
.sp-par2 .ph {
  --pw:28.5cqw
}
.sp-axis {
  position:absolute;
  left:50%;
  top:0;
  bottom:0;
  border-left:1px dashed var(--p2-ink)
}
.sp-axis span {
  position:absolute;
  top:50%;
  left:0;
  translate:-50% -50%;
  writing-mode:vertical-rl;
  background:var(--sp-sand);
  padding:1cqw 0;
  font-family:var(--p2-mono);
  font-size:max(8px,1.1cqw);
  letter-spacing:.14em;
  text-transform:uppercase;
  white-space:nowrap
}
.sp-plab {
  position:absolute;
  top:0;
  font-family:var(--p2-mono);
  font-size:max(8px,1.1cqw);
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--p2-ink-soft)
}
/* bilingual card photo */
.p2-bili-card .card-media {
  background:#cbbd9f url("https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=900&q=70") center/cover!important
}
.p2-bili-card .card-media::after {
  display:none!important
}
/* locked */
.sp-lock {
  background:#23261d;
  color:#fff;
  padding:120px 0
}
.sp-lock .p2-section-title {
  color:#fff
}
.sp-lock .p2-section-blurb {
  color:rgba(255,255,255,.65)
}
.sp-lock .p2-eyebrow {
  color:rgba(255,255,255,.5)
}
.sp-lock .p2-eyebrow .num {
  border-color:rgba(255,255,255,.5)
}
.sp-lock-grid {
  display:grid;
  grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);
  gap:56px;
  align-items:start
}
.sp-chapters {
  list-style:none;
  margin:0;
  padding:0;
  border-top:1px solid rgba(255,255,255,.14)
}
.sp-chapters li {
  display:grid;
  grid-template-columns:40px minmax(0,1fr) auto;
  gap:16px;
  align-items:center;
  padding:20px 0;
  border-bottom:1px solid rgba(255,255,255,.14)
}
.sp-chapters .n {
  font-family:var(--p2-mono);
  font-size:11px;
  color:rgba(255,255,255,.45)
}
.sp-chapters .t {
  font-size:18px
}
.sp-chapters .t small {
  display:block;
  font-size:13px;
  color:rgba(255,255,255,.55);
  margin-top:4px
}
.sp-chapters svg {
  width:14px;
  height:14px;
  stroke:rgba(255,255,255,.55);
  fill:none;
  stroke-width:1.6
}
.sp-gate {
  background:#fff;
  color:var(--p2-ink);
  border-radius:18px;
  padding:36px;
  display:flex;
  flex-direction:column;
  gap:16px;
  position:sticky;
  top:100px
}
.sp-gate h3 {
  font-size:28px;
  font-weight:400;
  letter-spacing:-.01em;
  line-height:1.15
}
.sp-gate p {
  font-size:14px;
  line-height:1.55;
  color:var(--p2-ink-soft)
}
.sp-gate .password-row {
  margin-top:8px
}
.sp-gate .error-message {
  min-height:18px;
  font-size:13px;
  color:#a33a2c
}
.sp-gate .alt a {
  color:var(--p2-ink);
  text-decoration:underline;
  text-underline-offset:3px
}
@media(max-width:900px) {
  .sp-lock-grid {
    grid-template-columns:1fr
  }
  .sp-gate {
    position:static
  }
  .sp-lock {
    padding:80px 0
  }
}
/* ---------- type: no mono, no italics ---------- */
.p2-page .p2-hero-title em,.p2-page .p2-section-title em,.p2-page .p2-next-link em,.p2-page h3 em,.p2-page h4 em {
  font-style:normal;
  color:var(--p2-mute)
}
.p2-page .p2-eyebrow,.p2-page .tab-no,.p2-page .stat-no,.p2-page .p2-corner,.p2-page .sp-note,.p2-page .p2-bili-hint,.p2-page .p2-next-eyebrow,.p2-page .cap {
  letter-spacing:.06em
}
/* ---------- role ---------- */
.sp-org {
  container-type:inline-size;
  background:var(--sp-sand);
  border-radius:18px;
  padding:48px 32px 32px
}
.sp-streams {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:3cqw
}
.sp-stream {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:22px;
  text-align:center;
  position:relative;
  padding-bottom:44px
}
.sp-stream::after {
  content:"";
  position:absolute;
  bottom:0;
  left:50%;
  height:30px;
  border-left:1px solid var(--p2-ink)
}
.sp-stream .ph {
  --pw:min(27cqw,330px)
}
.sp-lab span {
  display:block;
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute)
}
.sp-lab b {
  display:block;
  font-size:20px;
  font-weight:500;
  margin-top:6px
}
.sp-stream>p {
  font-size:14px;
  line-height:1.5;
  color:var(--p2-ink-soft);
  max-width:28ch;
  margin:0
}
.sp-base {
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:8px 16px;
  flex-wrap:wrap;
  background:#fff;
  border-radius:14px;
  padding:20px 24px
}
.sp-base span {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute)
}
.sp-base b {
  font-size:17px;
  font-weight:500
}
.sp-base.sys {
  background:var(--sp-olive);
  color:#fff
}
.sp-base.sys span {
  color:rgba(255,255,255,.7)
}
.sp-wire {
  height:20px;
  width:0;
  margin:0 auto;
  border-left:1px solid var(--p2-ink)
}
.sp-own {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:32px;
  margin-top:56px
}
.sp-own div {
  border-top:1px solid var(--p2-ink);
  padding-top:18px
}
.sp-own span {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  color:var(--p2-mute)
}
.sp-own h4 {
  font-size:19px;
  font-weight:500;
  margin:10px 0 8px
}
.sp-own p {
  font-size:14px;
  line-height:1.55;
  color:var(--p2-ink-soft);
  margin:0
}
@media(max-width:900px) {
  .sp-own {
    grid-template-columns:1fr 1fr
  }
}
@media(max-width:700px) {
  .sp-org {
    padding:28px 14px 14px
  }
  .sp-stream .ph {
    --pw:27cqw
  }
  .sp-lab b {
    font-size:14px
  }
  .sp-stream>p {
    display:none
  }
  .sp-own {
    grid-template-columns:1fr
  }
}
/* ---------- outcomes ---------- */
.sp-out {
  padding-bottom:40px
}
.sp-attr {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:16px
}
.sp-col {
  background:var(--sp-sand);
  border-radius:18px;
  padding:28px
}
.sp-col.me {
  background:var(--sp-olive);
  color:#fff
}
.sp-col span {
  display:block;
  font-family:var(--p2-mono);
  font-size:12px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute);
  margin-bottom:20px
}
.sp-col.me span {
  color:rgba(255,255,255,.7)
}
.sp-col ul {
  list-style:none;
  margin:0;
  padding:0;
  display:flex;
  flex-direction:column
}
.sp-col li {
  font-size:16px;
  line-height:1.4;
  padding:12px 0;
  border-top:1px solid rgba(0,0,0,.12)
}
.sp-col.me li {
  border-color:rgba(255,255,255,.2)
}
@media(max-width:900px) {
  .sp-attr {
    grid-template-columns:1fr
  }
}
.p2-page .stat-num {
  font-size:clamp(40px,5vw,72px)
}
.p2-page .p2-stats-grid {
  grid-template-columns:repeat(4,minmax(0,1fr))
}
@media(max-width:1000px) {
  .p2-page .p2-stats-grid {
    grid-template-columns:repeat(2,minmax(0,1fr));
    row-gap:32px
  }
  .p2-page .p2-stat {
    padding-left:0!important
  }
}
.sp-stream .ph {
  text-align:start
}
/* ---------- before/after tags ---------- */
.sp-pc {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:2cqw
}
.sp-tag {
  display:inline-flex;
  align-items:center;
  gap:.7cqw;
  font-size:max(11px,1.35cqw);
  font-weight:500;
  padding:.8cqw 1.6cqw;
  border-radius:99px;
  white-space:nowrap;
  color:#fff;
  background:#b3261e;
  box-shadow:0 .6cqw 1.4cqw -.6cqw rgba(179,38,30,.6)
}
.sp-tag.ok {
  background:#141414;
  box-shadow:0 .6cqw 1.4cqw -.6cqw rgba(0,0,0,.5)
}
.sp-tag small {
  font-size:inherit;
  opacity:.75;
  font-weight:400
}
.sp-ustage {
  aspect-ratio:16/8.6
}
@media(max-width:700px) {
  .sp-unify {
    padding:20px
  }
  .sp-ustage {
    aspect-ratio:4/3.8
  }
  .sp-lay {
    gap:2cqw
  }
  .sp-lay .ph {
    --pw:28cqw
  }
  .sp-lay.after .ph {
    --pw:36cqw
  }
  .sp-ann {
    display:none
  }
  .sp-tag small {
    display:none
  }
}
/* ---------- property card: one type token ---------- */
.p2-page .p2-bili-card,.p2-page .p2-bili-card[data-dir="rtl"] .card-arabic {
  font-family:"Switzer","IBM Plex Sans Arabic",sans-serif
}
.p2-page .p2-spec-list li {
  grid-template-columns:96px 1fr
}
.p2-spec-list .v small {
  display:block;
  color:var(--p2-mute);
  font-size:12px;
  margin-top:2px
}
/* ---------- outcomes equation ---------- */
.sp-eq {
  display:grid;
  grid-template-columns:minmax(0,1fr) auto minmax(0,1fr) auto minmax(0,1.25fr);
  align-items:stretch;
  gap:16px
}
.sp-op {
  align-self:center;
  width:52px;
  height:52px;
  border-radius:50%;
  background:#fff;
  border:1px solid rgba(0,0,0,.12);
  display:grid;
  place-items:center;
  font-size:26px;
  font-weight:300;
  line-height:1
}
.sp-col.res {
  background:#141414;
  color:#fff
}
.sp-col.res span {
  color:rgba(255,255,255,.6)
}
.sp-res {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:24px 20px
}
.sp-res b {
  display:block;
  font-size:clamp(32px,3.4vw,48px);
  font-weight:300;
  letter-spacing:-.03em;
  line-height:1
}
.sp-res small {
  display:block;
  font-size:13px;
  line-height:1.4;
  color:rgba(255,255,255,.7);
  margin-top:8px
}
.sp-col.res p {
  margin:24px 0 0;
  padding-top:16px;
  border-top:1px solid rgba(255,255,255,.2);
  font-size:14px;
  line-height:1.5;
  color:rgba(255,255,255,.8)
}
.sp-col.me {
  background:var(--sp-sand);
  color:var(--p2-ink)
}
.sp-col.me span {
  color:var(--p2-mute)
}
.sp-col.me li {
  border-color:rgba(0,0,0,.12)
}
.sp-col.tm {
  background:#fff;
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.1)
}
@media(max-width:1000px) {
  .sp-eq {
    grid-template-columns:1fr
  }
  .sp-op {
    justify-self:center
  }
}
.sp-conf {
  max-width:760px;
  margin:0 0 28px;
  padding:14px 18px;
  border-radius:12px;
  background:var(--sp-sand);
  border:1px solid rgba(0,0,0,.08);
  font-size:14px;
  line-height:1.5;
  color:var(--p2-ink-soft)
}
.sp-conf strong {
  color:var(--p2-ink);
  font-weight:500
}
/* no staged reveals inside illustrations */
.sp-co,.sp-fr,.sp-sec {
  opacity:1!important;
  translate:none!important;
  scale:none!important;
  transition:none!important
}


/* Original: copilot-preview.css */
:scope {
  --cp-navy:#0b1a2e;
  --cp-blue:#2f5bff
}
/* skins: one component, three clients */
.sk-air {
  --bg:#0b1a2e;
  --fg:#fff;
  --mu:#8ea0bd;
  --card:#15294a;
  --acc:#2f5bff;
  --bub:#1a3480;
  --line:rgba(255,255,255,.1)
}
.sk-ret {
  --bg:#fbf7f1;
  --fg:#1d1a16;
  --mu:#8a8276;
  --card:#fff;
  --acc:#1d1a16;
  --bub:#efe6d8;
  --line:rgba(0,0,0,.08)
}
.sk-bank {
  --bg:#121212;
  --fg:#fff;
  --mu:#9a9a9a;
  --card:#1f1f1f;
  --acc:#e0312b;
  --bub:#2a2a2a;
  --line:rgba(255,255,255,.1)
}
.scr[class*="sk-"] {
  background:var(--bg);
  color:var(--fg)
}
.scr[class*="sk-"]::after {
  background:var(--fg)
}
.sk-ret {
  font-family:"Switzer",sans-serif
}
.cp-head {
  display:flex;
  justify-content:space-between;
  align-items:center;
  padding:.4em 1.6em 1em;
  border-bottom:1px solid var(--line);
  flex-shrink:0
}
.cp-brand {
  display:flex;
  align-items:center;
  gap:.5em
}
.cp-brand svg {
  width:1.5em;
  height:1.5em
}
.cp-brand b {
  font-size:1.25em;
  font-weight:600
}
.sk-ret .cp-brand b {
  font-family:Georgia,serif;
  font-weight:400;
  font-size:1.45em;
  letter-spacing:.02em
}
.cp-ai {
  display:flex;
  align-items:center;
  gap:.5em;
  font-size:.95em;
  color:var(--mu)
}
.cp-ai i {
  font-style:normal
}
.cp-msgs {
  flex:1;
  min-height:0;
  overflow:hidden;
  display:flex;
  flex-direction:column;
  justify-content:flex-end;
  gap:.75em;
  padding:1em 1.4em
}
.cb {
  max-width:85%;
  font-size:1.1em;
  line-height:1.38;
  padding:.8em 1em;
  border-radius:1.2em
}
.cb.u {
  align-self:flex-end;
  background:var(--card);
  border-bottom-right-radius:.3em;
  box-shadow:0 0 0 1px var(--line)
}
.cb.a {
  align-self:flex-start;
  display:flex;
  gap:.6em;
  align-items:flex-start;
  background:var(--bub);
  border-bottom-left-radius:.3em;
  max-width:92%
}
.sk-air .cb.a,.sk-bank .cb.a {
  color:#fff
}
.cb.a .orb.av {
  margin-top:.1em
}
.cb.ty {
  padding:.7em 1em
}
.dots {
  display:flex;
  gap:.3em;
  align-items:center;
  height:1.6em
}
.dots i {
  width:.45em;
  height:.45em;
  border-radius:50%;
  background:currentColor;
  opacity:.4;
  animation:cp-dot 1.2s infinite
}
.dots i:nth-child(2) {
  animation-delay:.2s
}
.dots i:nth-child(3) {
  animation-delay:.4s
}

.cr {
  align-self:flex-start;
  display:flex;
  align-items:center;
  gap:.45em;
  font-size:.92em;
  color:var(--mu);
  padding:.35em .8em;
  border-radius:2em;
  box-shadow:inset 0 0 0 1px var(--line)
}
.cr svg {
  width:1.15em;
  height:1.15em
}
.co {
  display:flex;
  flex-direction:column;
  gap:.5em
}
.opt {
  display:flex;
  justify-content:space-between;
  align-items:center;
  background:var(--card);
  border-radius:1em;
  padding:.8em 1em;
  box-shadow:0 0 0 1px var(--line)
}
.opt small {
  display:block;
  font-size:.85em;
  color:var(--mu)
}
.opt b {
  display:block;
  font-size:1.25em;
  font-weight:500;
  margin:.1em 0
}
.opt em {
  font-style:normal;
  font-size:1.6em;
  font-weight:300
}
.cpr {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:.6em
}
.cpr>div {
  background:var(--card);
  border-radius:1em;
  padding:.5em;
  box-shadow:0 0 0 1px var(--line)
}
.cpr .im {
  display:block;
  aspect-ratio:1;
  border-radius:.7em;
  margin-bottom:.5em
}
.cpr b {
  display:block;
  font-size:1.05em;
  font-weight:500
}
.cpr small {
  font-size:.95em;
  color:var(--mu)
}
.qr {
  display:flex;
  gap:.5em
}
.qr span {
  flex:1;
  text-align:center;
  font-size:1.02em;
  padding:.8em .4em;
  border-radius:2em;
  box-shadow:inset 0 0 0 1px var(--line);
  background:var(--card)
}
.qr span.y {
  background:var(--acc);
  color:#fff;
  box-shadow:none
}
.hand {
  display:flex;
  gap:.8em;
  align-items:center;
  padding:.8em 1em;
  border-radius:1em;
  background:var(--card);
  box-shadow:0 0 0 1px var(--line)
}
.hand svg {
  width:2.2em;
  height:2.2em;
  padding:.45em;
  border-radius:50%;
  background:var(--acc);
  color:#fff;
  flex-shrink:0
}
.hand b {
  display:block;
  font-size:1.05em;
  font-weight:500
}
.hand small {
  font-size:.92em;
  color:var(--mu)
}
.ci {
  display:flex;
  align-items:center;
  justify-content:space-between;
  margin:0 1.4em 2.6em;
  padding:.45em .5em .45em 1.3em;
  border-radius:2em;
  background:var(--card);
  box-shadow:0 0 0 1px var(--line);
  flex-shrink:0
}
.ci span {
  font-size:1.08em;
  color:var(--mu)
}
/* orb */
.orb {
  display:inline-block;
  flex-shrink:0;
  border-radius:50%;
  background:radial-gradient(circle at 35% 30%,rgba(255,255,255,.95) 0 12%,transparent 34%),conic-gradient(from 0deg,#5b6cff,#ff7a9c,#7fd8ff,#b49cff,#5b6cff);
  animation:cp-spin 6s linear infinite;
  box-shadow:0 0 .8em rgba(120,130,255,.45)
}
.orb.sm {
  width:1.6em;
  height:1.6em
}
.orb.av {
  width:1.8em;
  height:1.8em
}
.orb.in {
  width:2.8em;
  height:2.8em
}
.orb.tb {
  width:4em;
  height:4em
}

/* airline home */
.cp-pad {
  flex:1;
  min-height:0;
  padding:.3em 1.7em 0;
  display:flex;
  flex-direction:column;
  gap:1.05em
}
.hm-top {
  display:flex;
  justify-content:space-between;
  align-items:center
}
.hm-top>span>svg {
  width:1.6em;
  height:1.6em
}
.hm-h {
  font-size:2.3em;
  font-weight:500;
  line-height:1.1;
  letter-spacing:-.02em
}
.hm-f {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:.55em
}
.hm-f span {
  background:var(--card);
  border-radius:.8em;
  padding:.6em .8em;
  font-size:1.05em
}
.hm-f small {
  display:block;
  font-size:.82em;
  color:var(--mu)
}
.hm-btn {
  background:var(--acc);
  border-radius:.8em;
  text-align:center;
  padding:.9em;
  font-size:1.15em;
  font-weight:500
}
.hm-s {
  font-size:1.2em;
  font-weight:500
}
.hm-sug {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:.55em
}
.hm-sug span {
  background:linear-gradient(160deg,#2f5bff,#2546c4);
  border-radius:.9em;
  padding:.8em;
  display:flex;
  flex-direction:column;
  gap:.15em
}
.hm-sug svg {
  width:1.4em;
  height:1.4em;
  margin-bottom:.3em
}
.hm-sug b {
  font-size:1.05em;
  font-weight:500
}
.hm-sug small {
  font-size:.88em;
  opacity:.8
}
.hm-j {
  display:flex;
  align-items:center;
  gap:.8em;
  background:var(--card);
  border-radius:.9em;
  padding:.9em 1em
}
.hm-j small {
  font-size:.9em;
  color:var(--mu)
}
.hm-j b {
  display:block;
  font-size:1.5em;
  font-weight:500
}
.hm-j i {
  flex:1;
  height:0;
  border-top:1px dashed var(--mu)
}
.hm-tb {
  height:7em;
  flex-shrink:0;
  display:flex;
  justify-content:space-around;
  align-items:flex-start;
  padding:.9em .6em 0;
  border-top:1px solid var(--line);
  background:#0e2038
}
.hm-tb span {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:.3em;
  color:var(--mu);
  width:4.6em
}
.hm-tb svg {
  width:1.8em;
  height:1.8em
}
.hm-tb i {
  font-style:normal;
  font-size:.85em
}
.hm-tb span:first-child {
  color:#fff
}
.hm-tb .mid {
  margin-top:-1.6em
}
/* hero */
.cp-hero-art {
  container-type:inline-size;
  position:relative;
  overflow:hidden;
  background:var(--sp-sand)!important
}
.cp-hero-art::before {
  content:"";
  position:absolute;
  width:60cqw;
  height:60cqw;
  left:20cqw;
  top:-6cqw;
  border-radius:50%;
  background:radial-gradient(circle,rgba(139,128,255,.32),rgba(255,140,170,.18) 45%,transparent 70%);
  filter:blur(2cqw)
}
.cp-hero-art .ph {
  position:absolute;
  --pw:20cqw;
  top:6.5cqw
}
.cp-hero-art .ph.h1 {
  left:12cqw
}
.cp-hero-art .ph.h2 {
  left:40cqw
}
.cp-hero-art .ph.h3 {
  left:68cqw
}
/* simulator */
.cp-sim {
  display:grid;
  grid-template-columns:auto minmax(0,1fr);
  gap:32px;
  align-items:start;
  background:var(--sp-sand);
  border-radius:18px;
  padding:32px
}
.cp-sim .ph {
  --pw:280px
}
.cp-scn {
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-bottom:16px
}
.cp-scn button {
  font:inherit;
  font-size:14px;
  padding:10px 16px;
  border-radius:99px;
  border:1px solid rgba(0,0,0,.15);
  background:#fff;
  cursor:pointer;
  color:var(--p2-ink)
}
.cp-scn button[aria-pressed="true"] {
  background:var(--cp-navy);
  color:#fff;
  border-color:var(--cp-navy)
}
.cp-steps {
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:4px;
  background:#fff;
  border-radius:12px;
  padding:4px;
  margin-bottom:16px
}
.cp-steps button {
  font:inherit;
  font-size:13px;
  padding:10px;
  border:0;
  border-radius:9px;
  background:transparent;
  cursor:pointer;
  color:var(--p2-mute);
  display:flex;
  align-items:center;
  gap:8px;
  justify-content:center
}
.cp-steps button i {
  font-style:normal;
  width:20px;
  height:20px;
  border-radius:50%;
  background:#eceae6;
  color:var(--p2-ink);
  display:grid;
  place-items:center;
  font-size:11px
}
.cp-steps button[aria-pressed="true"] {
  background:var(--sp-sand);
  color:var(--p2-ink)
}
.cp-steps button[aria-pressed="true"] i {
  background:var(--cp-navy);
  color:#fff
}
.cp-pane {
  background:#fff;
  border-radius:14px;
  padding:24px;
  min-height:380px;
  display:flex;
  flex-direction:column;
  gap:16px
}
.cp-pane h4 {
  margin:0;
  font-size:20px;
  font-weight:500
}
.cp-pane>p {
  margin:0;
  font-size:14px;
  color:var(--p2-ink-soft);
  line-height:1.5
}
.cp-in {
  border-left:3px solid var(--cp-blue);
  padding:6px 12px;
  font-size:15px
}
.cp-ints {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:8px
}
.cp-int {
  border:1px solid #ecebe8;
  border-radius:10px;
  padding:12px;
  color:#b3b0aa
}
.cp-int b {
  display:block;
  font-size:14px;
  font-weight:500
}
.cp-int small {
  font-size:12px
}
.cp-int.on {
  border-color:var(--cp-blue);
  color:var(--p2-ink);
  box-shadow:0 0 0 1px var(--cp-blue)
}
.cp-int.on small {
  color:var(--cp-blue)
}
.cp-tbl {
  width:100%;
  border-collapse:collapse;
  font-size:13.5px
}
.cp-tbl th {
  text-align:left;
  font-weight:400;
  color:var(--p2-mute);
  font-size:12px;
  padding:0 8px 8px 0;
  border-bottom:1px solid #ecebe8
}
.cp-tbl td {
  padding:10px 8px 10px 0;
  border-bottom:1px solid #f2f1ee;
  vertical-align:top
}
.st {
  display:inline-flex;
  align-items:center;
  gap:6px;
  font-size:12px;
  padding:3px 9px;
  border-radius:99px;
  white-space:nowrap
}
.st.ok {
  background:#e3f4ea;
  color:#1f6b3e
}
.st.miss {
  background:#fdf0dc;
  color:#8a5a12
}
.st.no {
  background:#fbe3e1;
  color:#9c2a22
}
.cp-dec {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:8px
}
.cp-dec>div {
  border-radius:10px;
  padding:12px;
  background:var(--sp-sand)
}
.cp-dec small {
  display:block;
  font-family:var(--p2-mono);
  font-size:10.5px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute);
  margin-bottom:6px
}
.cp-dec b {
  font-size:14px;
  font-weight:500
}
.cp-conf {
  display:flex;
  align-items:center;
  gap:12px;
  font-size:13px
}
.cp-conf .bar {
  flex:1;
  height:6px;
  border-radius:6px;
  background:#eceae6;
  overflow:hidden
}
.cp-conf .bar i {
  display:block;
  height:100%;
  border-radius:6px
}
.cp-guard {
  display:flex;
  gap:10px;
  align-items:flex-start;
  font-size:13.5px;
  line-height:1.45;
  background:#eef2ff;
  color:#24316b;
  padding:12px 14px;
  border-radius:10px
}
.cp-guard b {
  font-weight:500
}
@media(max-width:900px) {
  .cp-sim {
    grid-template-columns:1fr;
    justify-items:center
  }
  .cp-sim>div:last-child {
    width:100%
  }
  .cp-ints,.cp-dec {
    grid-template-columns:1fr 1fr
  }
}
/* patterns */
.cp-pats {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:16px
}
.cp-pat {
  background:var(--sp-sand);
  border-radius:18px;
  padding:24px;
  display:flex;
  flex-direction:column;
  gap:14px
}
.cp-pat .n {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  color:var(--p2-mute)
}
.cp-pat h4 {
  margin:0;
  font-size:18px;
  font-weight:500
}
.cp-pat p {
  margin:0;
  font-size:14px;
  line-height:1.5;
  color:var(--p2-ink-soft)
}
.cp-demo {
  background:var(--cp-navy);
  border-radius:12px;
  padding:16px;
  font-size:13px;
  color:#fff;
  display:flex;
  flex-direction:column;
  gap:8px;
  margin-top:auto;
  min-height:150px;
  justify-content:flex-end
}
.cp-demo .b {
  background:#1a3480;
  border-radius:10px;
  padding:8px 10px;
  line-height:1.4;
  align-self:flex-start;
  max-width:92%
}
.cp-demo .u {
  background:#15294a;
  align-self:flex-end
}
.cp-demo .c {
  font-size:11.5px;
  color:#9fb0d6;
  border:1px solid rgba(255,255,255,.14);
  border-radius:99px;
  padding:3px 9px;
  align-self:flex-start
}
.cp-demo .row {
  display:flex;
  gap:6px
}
.cp-demo .row span {
  flex:1;
  text-align:center;
  padding:7px;
  border-radius:99px;
  background:#15294a;
  font-size:12px
}
.cp-demo .row span.y {
  background:#2f5bff
}
.cp-orbs {
  display:flex;
  justify-content:space-around;
  align-items:flex-end
}
.cp-orbs div {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:8px;
  font-size:11.5px;
  color:#9fb0d6
}
.cp-orbs .orb {
  width:44px;
  height:44px
}
.cp-orbs .s1 .orb {
  animation-duration:9s
}
.cp-orbs .s2 .orb {
  animation-duration:4s
}
.cp-orbs .s3 .orb {
  animation-duration:1.4s
}
@media(max-width:1000px) {
  .cp-pats {
    grid-template-columns:1fr 1fr
  }
}
@media(max-width:640px) {
  .cp-pats {
    grid-template-columns:1fr
  }
}
@media(prefers-reduced-motion:reduce) {
  .orb,.dots i {
    animation:none
  }
}


/* Original: copilot-kit.css */
.ico {
  display:inline-grid;
  place-items:center;
  flex-shrink:0;
  font-style:normal
}
.ico svg {
  width:100%;
  height:100%
}
.cp-lab {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute)
}
/* mandate */
.cp-vs2 {
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(0,1fr);
  gap:16px
}
.cp-vs2>div {
  background:var(--sp-sand);
  border-radius:18px;
  padding:28px;
  display:flex;
  flex-direction:column;
  gap:20px
}
.cp-vs2 h4 {
  margin:4px 0 0;
  font-size:22px;
  font-weight:500
}
.cp-vs2 .sum {
  display:flex;
  align-items:baseline;
  gap:10px;
  border-top:1px solid rgba(0,0,0,.12);
  padding-top:16px;
  font-size:15px;
  color:var(--p2-ink-soft)
}
.cp-vs2 .sum b {
  font-size:32px;
  font-weight:300;
  color:var(--p2-ink);
  letter-spacing:-.02em
}
.mx {
  display:grid;
  grid-template-columns:64px repeat(5,minmax(0,1fr));
  gap:6px;
  align-items:stretch
}
.mx .rl {
  font-size:12px;
  color:var(--p2-mute);
  display:flex;
  align-items:center
}
.mx .ch {
  font-size:12px;
  text-align:center;
  padding:4px 0;
  color:var(--p2-ink-soft)
}
.mx .b {
  height:38px;
  border-radius:8px;
  border:1.5px dashed rgba(0,0,0,.28);
  display:grid;
  place-items:center
}
.mx .b .ico {
  width:16px;
  height:16px;
  color:rgba(0,0,0,.4)
}
.mx .b.w1 {
  transform:translateY(3px)
}
.mx .b.w2 {
  transform:translateY(-3px)
}
.mx .b.w3 {
  height:30px;
  align-self:center
}
.mx .sk {
  height:26px;
  border-radius:99px;
  display:grid;
  place-items:center;
  font-size:11px;
  font-weight:500
}
.mx .span {
  grid-column:2/-1;
  height:38px;
  border-radius:8px;
  border:1.5px solid var(--p2-ink);
  background:#fff;
  display:flex;
  align-items:center;
  gap:8px;
  padding:0 12px;
  font-size:13px;
  font-weight:500
}
.mx .span .ico {
  width:16px;
  height:16px
}
.mx .gap {
  grid-column:1/-1;
  height:4px
}
@media(max-width:900px) {
  .cp-vs2 {
    grid-template-columns:1fr
  }
}
/* leadership */
.cp-flow {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  background:var(--sp-sand);
  border-radius:18px;
  padding:28px 12px;
  align-items:stretch
}
.cp-node {
  padding:4px 20px;
  display:flex;
  flex-direction:column;
  gap:10px
}
.cp-node+.cp-node {
  border-left:1px solid rgba(0,0,0,.12)
}
.cp-node .who {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--p2-mute);
  display:flex;
  align-items:center;
  gap:8px
}
.cp-node .who .ico {
  width:18px;
  height:18px;
  color:var(--p2-ink)
}
.cp-node b {
  font-size:19px;
  font-weight:500
}
.cp-node p {
  font-size:14px;
  line-height:1.5;
  color:var(--p2-ink-soft);
  margin:0
}
.cp-node.me {
  border:1.5px solid var(--p2-ink);
  border-radius:14px;
  background:transparent;
  padding:18px 20px;
  margin:-12px 4px
}
.cp-node.me+.cp-node {
  border-left:0
}
.cp-node.me ul {
  margin:2px 0 0;
  padding:0;
  list-style:none;
  display:flex;
  flex-direction:column;
  gap:8px;
  font-size:14px
}
.cp-node.me li {
  display:flex;
  gap:8px;
  align-items:center
}
.cp-node.me li .ico {
  width:16px;
  height:16px;
  color:var(--cp-blue)
}
@media(max-width:900px) {
  .cp-flow {
    grid-template-columns:1fr 1fr;
    row-gap:28px
  }
  .cp-node+.cp-node {
    border-left:0
  }
  .cp-node.me {
    margin:0
  }
}
@media(max-width:560px) {
  .cp-flow {
    grid-template-columns:1fr
  }
}
/* architecture */
.cp-arch2 {
  display:grid;
  grid-template-columns:minmax(0,.9fr) 48px minmax(0,1.5fr) 48px minmax(0,1fr);
  align-items:center;
  background:var(--sp-sand);
  border-radius:18px;
  padding:32px
}
.a-col {
  display:flex;
  flex-direction:column;
  gap:4px
}
.a-hd {
  display:flex;
  align-items:center;
  gap:10px;
  margin-bottom:12px
}
.a-hd b {
  width:24px;
  height:24px;
  border-radius:50%;
  background:var(--p2-ink);
  color:#fff;
  display:grid;
  place-items:center;
  font-size:12px;
  font-weight:500
}
.a-hd span {
  font-family:var(--p2-mono);
  font-size:11px;
  letter-spacing:.06em;
  text-transform:uppercase
}
.a-in {
  display:flex;
  gap:12px;
  align-items:flex-start;
  padding:12px 4px;
  border-top:1px solid rgba(0,0,0,.1)
}
.a-in .ico {
  width:20px;
  height:20px;
  margin-top:1px
}
.a-in b,.a-eng b,.a-band b,.a-out b {
  display:block;
  font-size:14px;
  font-weight:500
}
.a-in small,.a-eng small,.a-band small,.a-out small {
  display:block;
  font-size:12.5px;
  color:var(--p2-mute);
  line-height:1.4;
  margin-top:2px
}
.a-conn {
  position:relative;
  height:2px;
  background:var(--p2-ink);
  margin:0 6px
}
.a-conn::after {
  content:"";
  position:absolute;
  right:-1px;
  top:-4px;
  border:5px solid transparent;
  border-left:7px solid var(--p2-ink);
  border-right:0
}
.a-core {
  background:#fff;
  border:1.5px solid var(--p2-ink);
  border-radius:16px;
  padding:20px;
  display:flex;
  flex-direction:column;
  gap:10px
}
.a-pats {
  display:flex;
  justify-content:center;
  gap:6px;
  flex-wrap:wrap
}
.a-pats span {
  font-size:12px;
  padding:5px 12px;
  border-radius:99px;
  background:var(--sp-sand)
}
.a-orch {
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  padding:10px;
  border-radius:12px;
  border:1px solid rgba(0,0,0,.12)
}
.a-orch .ico {
  width:20px;
  height:20px;
  color:var(--cp-blue)
}
.a-engs {
  display:grid;
  grid-template-columns:1fr 14px 1fr 14px 1fr;
  align-items:center
}
.a-engs>i.arw {
  height:1.5px;
  background:rgba(0,0,0,.35)
}
.a-eng {
  border-radius:12px;
  padding:14px 10px;
  text-align:center;
  border:1px solid rgba(0,0,0,.12)
}
.a-eng .ico {
  width:24px;
  height:24px;
  margin-bottom:6px
}
.a-eng.hi {
  background:var(--cp-navy);
  color:#fff;
  border-color:var(--cp-navy)
}
.a-eng.hi small {
  color:rgba(255,255,255,.65)
}
.a-band {
  display:flex;
  align-items:center;
  gap:12px;
  padding:10px 14px;
  border-radius:12px;
  background:var(--sp-sand)
}
.a-band .ico {
  width:20px;
  height:20px
}
.a-out {
  display:flex;
  align-items:center;
  gap:12px;
  padding:10px;
  border-radius:14px;
  color:#fff
}
.a-out .ico {
  width:34px;
  height:34px;
  padding:8px;
  border-radius:50%;
  background:rgba(255,255,255,.16)
}
.a-out small {
