:scope { --portfolio-neue: "Neue Haas Grotesk Display Pro", "Neue Haas Grotesk", "Helvetica Neue", Arial, sans-serif; }

/* A consistent editorial sans-serif; no display-font overrides. */
body, button, input, select, textarea, .p2-page, .p2-page *, .portfolio-nav, .portfolio-footer,
.hero, .section, .wwm-page, .wwm-page *, .ac-two, .ac-two * {
  font-family: var(--portfolio-neue) !important;
}
.small-label, .hero-kicker, .category, .p2-eyebrow, .p2-hero-meta,
.p2-next-eyebrow, .cp-lab, .sp-note, .sp-lab span, .sp-hl,
.portfolio-footer-eyebrow, .wwm-eyebrow {
  font-family: var(--portfolio-neue) !important;
  text-transform: uppercase;
  letter-spacing: .065em;
  font-weight: 500;
}

/* SVG arrows: dark on light backgrounds, white on dark backgrounds. */
.cta-icon { display: inline-block !important; width: 1em; height: 1em; background-position: center; background-repeat: no-repeat; background-size: contain; }
.cta-icon-up { background-image: url("assets/24-arrow-up-right-dark.svg"); }
.cta-icon-down { background-image: url("assets/24-arrow-down-dark.svg"); }
.portfolio-footer .cta-icon-up, .portfolio-footer .cta-icon-down,
a[style*="background:#111"] .cta-icon-up { background-image: url("assets/24-arrow-up-right.svg"); }
.portfolio-footer .cta-icon-down { background-image: url("assets/24-arrow-down.svg"); }

/* Navigation overlay: menu does not change the document height. */
.portfolio-nav { position: relative !important; isolation: isolate; }
.portfolio-nav-inner { position: relative; }
.portfolio-nav-toggle, .menu-toggle { width: 38px; height: 38px; align-items: center; justify-content: center; }
.menu-bars { display: block; width: 21px; height: 2px; background: currentColor; position: relative; transition: background .18s; }
.menu-bars::before, .menu-bars::after { content: ""; position: absolute; left: 0; width: 21px; height: 2px; background: currentColor; transition: transform .18s, top .18s; }
.menu-bars::before { top: -7px; }
.menu-bars::after { top: 7px; }
[aria-expanded="true"] > .menu-bars { background: transparent; }
[aria-expanded="true"] > .menu-bars::before { top: 0; transform: rotate(45deg); }
[aria-expanded="true"] > .menu-bars::after { top: 0; transform: rotate(-45deg); }

/* Avoid clipped equation panels and oversized headings. */
.p2-page .sp-out, .p2-page .sp-out .sp-eq, .p2-page .sp-out .sp-col,
.p2-page .cp-out, .p2-page .p2-section-head { min-width: 0; max-width: 100%; }
.p2-page .sp-out .sp-eq { grid-template-columns: minmax(0,1fr) auto minmax(0,1fr) auto minmax(0,1.25fr); }
.p2-page .p2-section-title { font-size: clamp(30px, 3.7vw, 56px) !important; line-height: 1.12 !important; overflow-wrap: anywhere; }
.p2-page .sp-out .sp-col { padding: clamp(14px,2vw,28px) !important; }
.p2-page .sp-out .sp-col * { max-width: 100%; overflow-wrap: anywhere; }
.p2-page .sp-out .sp-eq, .p2-page .sp-out .sp-col { box-sizing: border-box; }

/* Stream labels must sit above the phone visuals. */
.sp-hero-art .sp-hl { z-index: 25 !important; position: absolute !important; color: #111 !important; background: rgba(255,255,255,.94); padding: 5px 7px; border-radius: 3px; }

@media (max-width: 900px) {
  body > .portfolio-nav .portfolio-nav-inner { flex-wrap: nowrap !important; }
  body > .portfolio-nav .portfolio-nav-toggle { display: flex !important; }
  body > .portfolio-nav .portfolio-nav-links,
  body > .portfolio-nav .portfolio-nav-links.is-open {
    position: absolute !important; top: calc(100% - 1px) !important; left: 0 !important; right: 0 !important;
    width: 100% !important; flex-basis: auto !important; margin: 0 !important;
    padding: 20px 5% 28px !important; background: #fafafa !important;
    box-shadow: 0 18px 30px rgba(0,0,0,.12); z-index: 9999 !important;
  }
  body > .portfolio-nav .portfolio-nav-links:not(.is-open) { display: none !important; }
  body > .portfolio-nav .portfolio-nav-links.is-open { display: flex !important; }
  /* Private pages have a separate menu implementation. */
  .site-header, header:has(.menu-toggle) { position: relative; z-index: 1000; }
  .site-header .links.open, header:has(.menu-toggle) .links.open { position: absolute !important; top: 100% !important; left: 0; right: 0; z-index: 1001; }
}
@media (max-width: 700px) {
  .p2-page .p2-section-title { font-size: clamp(25px, 6.5vw, 34px) !important; line-height: 1.16 !important; }
  .p2-page .p2-hero-title { font-size: clamp(32px, 8vw, 45px) !important; }
  .p2-page .p2-hero-meta, .p2-page .p2-eyebrow { font-size: 10px !important; }
  /* Place the artwork immediately after the heading, before lengthy explanations. */
  .p2-page .p2-hero { display: flex !important; flex-direction: column !important; }
  .p2-page .p2-hero > .p2-wrap { display: contents !important; }
  .p2-page .p2-hero-meta { order: 0; margin: 10px 5% 8px !important; }
  .p2-page .p2-hero-title { order: 1; margin: 0 5% 10px !important; }
  .p2-page .p2-hero-video { order: 2; width: 100% !important; margin: 4px 0 16px !important; }
  .p2-page .portfolio-public-note, .p2-page .pt-public-note { order: 3; margin: 0 5% 12px !important; }
  .p2-page .cp-headline, .p2-page .sp-positioning-line { order: 4; margin: 0 5% 12px !important; }
  .p2-page .p2-hero-lede { order: 5; margin: 0 5% 22px !important; }
  .p2-page .sp-hero-art .sp-hl { z-index: 30 !important; font-size: 9px !important; max-width: 31%; white-space: normal !important; }
  .p2-page .sp-out .sp-eq { grid-template-columns: 1fr !important; }
  .p2-page .sp-out .sp-op { justify-self: center !important; }
  .p2-page .sp-out .sp-col { width: 100%; }
  .p2-page .p2-section-head, .p2-page .p2-section-head > * { min-width: 0; }
  .p2-page .p2-hero-lede { display: block !important; }
  .p2-page .p2-hero-detail { margin-top: 12px; }
  .p2-page .sp-hero-art .sp-hl { top: 6px !important; }
  .p2-page .p2-section { overflow-x: clip; }
  .ac-two .p2-section:last-of-type, .ac-two .p2-section:has(.sp-out) { padding-bottom: 32px !important; }
  .p2-page .portfolio-footer { margin-top: 24px !important; }
}

/* AccruPay outcome cards and following full-case-study panel */
.ac-two .sp-out, .ac-two .cp-out, .ac-two .p2-outcomes, .ac-two .ac-outcomes { margin-bottom: 28px !important; }
.ac-two .p2-next, .ac-two .p2-next-link, .ac-two .case-state-switch { margin-top: 24px !important; }

}


/* =============== accrupay-public.html =============== */
@scope (html[data-portfolio-page="accrupay-public"]) {
/* Original: styles.css */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
:scope,
body {
  width: 100%;
  overflow-x: hidden;
}
body {
  font-family: "Switzer", sans-serif;
  background: #ffffff;
  color: #000000;
  line-height: 1.4;
}
img {
  display: block;
  max-width: 100%;
}
a {
  color: inherit;
  text-decoration: none;
}
.section-pad {
  padding-left: 100px;
  padding-right: 100px;
}
.section-label {
  font-size: 16px;
  line-height: 1.3;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #555252;
}
main {
  position: relative;
}
/* NAV */

.nav {
  width: 100%;
  background: rgba(249, 249, 249, 0.82);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  position: fixed;
  top: 0;
  left: 0;
  z-index: 10000;
}
body {
  padding-top: 77px;
}
.nav-inner {
  width: 100%;
  padding: 24px 100px;
  /* matches section-pad EXACTLY */
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.logo {
  font-size: 24px;
  line-height: 1.3;
  font-weight: 400;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 24px;
}
.nav-links a {
  font-size: 16px;
  line-height: 1.3;
  font-weight: 400;
}
.nav-links a.active {
  font-weight: 700;
}
.nav-cta {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 4px 8px;
  height: 29px;
  border: 1px solid #000000;
  font-size: 16px;
  line-height: 21px;
  font-weight: 400;
}
.nav-mobile {
  display: none;
}
.mobile-menu {
  position: fixed;
  top: 0;
  left: 0;
  /* 🔥 ADD THIS */
  right: 0;
  width: 100vw;
  /* 🔥 FORCE FULL WIDTH */
  height: 100vh;
  /* 🔥 FORCE FULL HEIGHT */

  background: #F2F2F2;
  transform: translateX(100%);
  transition: transform 0.35s ease;
  z-index: 20000;
  overflow-y: auto;
}
.mobile-menu.active {
  transform: translateX(0);
  /* 👈 slide in */
}
.mobile-links {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 24px;
  /* 🔥 push links down */
  height: auto !important;
  gap: 0;
}
.mobile-links a {
  font-size: 16px;
  font-weight: 500;
}
.mobile-nav-cta {
  display: inline-flex !important;
  justify-content: center;
  align-items: center;
  padding: 4px 8px !important;
  padding-bottom: 24px;
  border: 1px solid #000000;
  width: auto !important;
  margin-top: 24px;
  line-height: 21px;
}
.menu-close {
  position: absolute;
  top: 24px;
  right: 24px;
  background: none;
  border: none;
  z-index: 10;
}
/* HERO */

.hero {
  padding-top: 56px;
  padding-bottom: 32px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: start;
  column-gap: 40px;
}
.hero-title h1 {
  font-size: 60px;
  line-height: 1.1;
  font-weight: 400;
}
.hero-copy {
  display: flex;
  justify-content: flex-end;
}
.hero-copy p {
  max-width: 823px;
  font-size: 24px;
  line-height: 1.3;
  font-weight: 300;
  text-align: right;
}
.hero-copy-inner {
  max-width: 823px;
  text-align: right;
}
.hero-copy-inner p:first-child {
  font-size: 20px;
  line-height: 1.3;
  font-weight: 300;
}
.hero-proof {
  margin-top: 16px;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 400;
  color: rgb(22, 22, 22);
}
/* SELECTED WORK */

.selected-work {
  padding-top: 0;
  padding-bottom: 48px;
}
.selected-work .section-label {
  margin-bottom: 24px;
}
.project-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
/* EXPERTISE */

.expertise {
  padding-top: 0;
  padding-bottom: 24px;
  display: grid;
  grid-template-columns: 309px 1fr;
  column-gap: 108px;
  align-items: center;
  min-height: 320px;
  border-bottom: 1px solid #ededed;
}
.expertise-copy {
  max-width: 823px;
}
.expertise-copy p {
  font-size: 20px;
  line-height: 1.4;
  font-weight: 400;
}
.expertise-copy p + p {
  margin-top: 24px;
}
.expertise-copy strong {
  font-weight: 700;
}
/* PROCESS */

.process-section {
  padding-top: 32px;
  padding-bottom: 24px;
  display: grid;
  grid-template-columns: 309px 1fr;
  column-gap: 108px;
  align-items: start;
}
.process-list {
  width: 100%;
  max-width: 1059px;
  /* match your hero width */
}
.process-section,
.expertise {
  max-width: 1440px;
  margin: 0 auto;
}
.process-row {
  display: grid;
  grid-template-columns: 80px 1.2fr 1fr;
  align-items: start;
  padding: 48px 0;
  border-top: 1px solid #eaeaea;
}
.process-row:first-child {
  padding-top: 0;
  border-top: none;
}
.process-number {
  font-size: 68px;
  line-height: 1;
  font-weight: 300;
  color: #a0a0a0;
}
.process-title {
  font-size: 20px;
  line-height: 1.333;
  font-weight: 500;
  color: #000000;
  padding-top: 12px;
  margin-right: 24px;
}
.process-items {
  padding-top: 2px;
  max-width: 420px;
}
.process-items p {
  font-size: 16px;
  line-height: 1.3125;
  font-weight: 400;
  color: #555252;
}
.process-items p + p {
  margin-top: 16px;
}
/* EXPERIENCE */

.experience {
  padding-top: 0;
  padding-bottom: 80px;
  border-top: 1px solid #ededed;
}
.experience .section-label {
  margin-top: 54px;
  margin-bottom: 32px;
}
.experience-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
}
.experience-card {
  height: 220px;
  border: 1px solid #e8e8e8;
  border-right: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #ffffff;
  position: relative;
  overflow: hidden;
}
.experience-card:last-child {
  border-right: 1px solid #e8e8e8;
}
.experience-inner {
  position: relative;
  width: 100%;
  height: 100%;
}
.experience-logo {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.logo-dark,
.logo-light {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.logo-light {
  opacity: 0;
}
.logo-svg {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding-inline: clamp(20px, 4vw, 36px);
}
.logo-svg svg {
  display: block;
  width: 100%;
  max-width: clamp(110px, 16vw, 140px);
  height: auto;
}
.logo-telegraph svg {
  max-width: clamp(130px, 18vw, 240px);
}
.experience-role {
  position: absolute;
  left: 50%;
  top: calc(50% + clamp(28px, 3.2vw, 42px));
  transform: translateX(-50%);
  color: #ffffff;
  font-size: clamp(12px, 1.2vw, 16px);
  opacity: 0;
  transition: opacity 0.25s ease;
  white-space: nowrap;
}
.experience-card:hover {
  background: #000;
}
.experience-card:hover .logo-dark {
  opacity: 0;
}
.experience-card:hover .logo-light {
  opacity: 1;
}
.experience-card:hover .experience-role {
  opacity: 1;
}
/* CONTACT BANNER */

.contact-banner {
  position: relative;
  width: 100%;
  height: 530px;
  overflow: hidden;
}
.contact-banner img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.contact-overlay {
  position: absolute;
  inset: 0;
  padding-top: 27px;
  padding-bottom: 26px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.contact-details p {
  font-size: 16px;
  line-height: 1.3125;
  font-weight: 400;
  color: #ffffff;
  margin-bottom: 12px;
}
.contact-details a {
  font-size: 16px;
  line-height: 1.3125;
  font-weight: 400;
  color: #ffffff;
  text-decoration: underline;
}
.passion-link {
  font-size: 32px;
  line-height: 1.3125;
  font-weight: 500;
  color: #ffffff;
  align-self: flex-start;
}
/* FOOTER */

.footer {
  width: 100%;
  background: #ebebeb;
}
.footer-inner {
  margin: 0 auto;
  padding: 72px 100px 48px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}
.footer-inner h2 {
  font-size: 48px;
  line-height: 1.3125;
  font-weight: 500;
}
.footer-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
}
.footer-links {
  display: flex;
  gap: 24px;
}
.footer-links a {
  font-size: 16px;
  line-height: 1.3125;
  font-weight: 400;
  text-decoration: underline;
}
.footer-right p {
  font-size: 16px;
  line-height: 1.3125;
  font-weight: 400;
  color: #6f6f6f;
}
/* RESPONSIVE */

@media (max-width: 1100px) {
  .section-pad,
  .nav-inner,
  .footer-inner {
    padding-left: 40px;
    padding-right: 40px;
  }
  .hero,
  .expertise,
  .process-section {
    grid-template-columns: 1fr;
    row-gap: 24px;
  }
  .hero-copy p {
    text-align: left;
  }
  .hero-copy-inner {
    text-align: left;
  }
  .hero-proof {
    font-size: 16px;
    margin-top: 12px;
  }
  .process-row {
    grid-template-columns: 60px 1fr;
    row-gap: 16px;
  }
  .process-items {
    grid-column: 2;
  }
  .experience-card:nth-child(2) {
    border-right: 1px solid #e8e8e8;
  }
  .experience-card:nth-child(3) {
    border-top: none;
  }
  .footer-inner {
    min-height: auto;
    flex-direction: column;
    align-items: flex-start;
    gap: 32px;
  }
  .footer-right {
    align-items: flex-start;
  }
}
@media (max-width: 700px) {
  .section-pad,
  .nav-inner,
  .footer-inner {
    padding-left: 20px;
    padding-right: 20px;
  }
  .nav-mobile {
    display: flex;
    justify-content: flex-end;
    position: absolute;
    top: 24px;
    right: 24px;
    z-index: 10;
  }
  .experience-role {
    font-size: 12px;
    bottom: 24px;
    top: auto;
  }
  .hero-title h1 {
    font-size: 60px;
  }
  .hero-copy p,
  .expertise-copy p,
  .passion-link {
    font-size: 24px;
  }
  .project-grid,
  .experience-grid {
    grid-template-columns: 1fr;
  }
  .experience-card {
    border-right: 1px solid #e8e8e8;
    border-top: none;
  }
  .experience-card {
    border-top: 1px solid #e8e8e8;
  }
  .nav-links,
  .footer-links {
    flex-wrap: wrap;
  }
  .bilingual-grid {
    display: flex !important;
    flex-direction: column !important;
    gap: 32px;
  }
  .fe-grid {
    display: flex !important;
    flex-direction: column !important;
    gap: 16px;
  }
  .fe-card img {
    width: 100%;
    height: auto !important;
    object-fit: contain;
  }
  .outcomes-grid {
    display: flex !important;
    flex-direction: column !important;
    gap: 32px;
  }
  .outcomes-image img {
    width: 100%;
    height: auto;
  }
  .velvet-logo {
    position: relative;
    bottom: auto;
    left: auto;
    transform: none;
    margin: 24px auto 0;
    display: block;
    width: 70%;
  }
  .coding-grid {
    display: flex !important;
    flex-direction: column !important;
    gap: 16px;
  }
  /* 🔥 FORCE STACK */
  .coding-inner {
    display: flex !important;
    flex-direction: column !important;
    gap: 24px;
  }
  /* 🔥 SWITCH VIDEOS */
  .video-desktop {
    display: none !important;
  }
  .video-mobile {
    display: block !important;
    width: 100%;
    height: auto;
  }
  .section-dark .project-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .section-dark .project-text {
    max-width: 100%;
  }
  .section-dark .project-image-wrap {
    padding: 16px;
  }
  .design-approach-section .project-grid {
    grid-template-columns: 1fr;
  }
  .design-approach-section .project-text {
    max-width: 100%;
  }
  .timeline-grid {
    grid-template-columns: 1fr !important;
    gap: 32px;
  }
  .timeline-right {
    width: 100%;
  }
  .vr-banner {
    height: 270px;
  }
  .vr-link {
    font-size: 24px;
  }
  .project-card-clean {
    width: 100% !important;
  }
  .project-card-clean-image {
    width: 100% !important;
    height: auto !important;
  }
  .project-card-clean-image img {
    width: 100% !important;
    height: auto !important;
    object-fit: cover;
  }
  @media (max-width: 768px) {
    .experience-grid {
      grid-template-columns: 1fr 1fr;
    }
    .experience-card {
      height: 120px;
      border-right: 1px solid #e8e8e8;
      border-top: none;
    }
    .experience-card:nth-child(1),
.experience-card:nth-child(2) {
      border-top: 1px solid #e8e8e8;
    }
    .experience-role {
      font-size: 12px;
      top: calc(50% + 20px);
    }
    .project-grid {
      grid-template-columns: 1fr;
      gap: 40px;
    }
    .project-text {
      max-width: 100%;
    }
    .project-image-wrap {
      padding: 16px;
    }
    .section-divider {
      width: calc(100% - 40px);
      margin: 60px auto 0;
    }
  }
  /* ALL IMAGE GROUPS STACK */

.bilingual-images-top,
.bilingual-images-bottom {
    display: flex !important;
    flex-direction: column !important;
    gap: 16px;
    width: 100%;
  }
  /* IMAGES FULL WIDTH, NATURAL HEIGHT */

.bilingual-images-top img,
.bilingual-images-bottom img {
    width: 100%;
    height: auto !important;
    object-fit: contain;
    /* 🔥 important */
  }
  /* REMOVE DESKTOP HEIGHT CONSTRAINTS */

.bilingual-images-top img,
.bilingual-images-bottom img {
    max-height: none;
  }
