  background:#0c0c0c;
  border-radius:4.9em;
  padding:.72em;
  flex-shrink:0;
  box-shadow:0 0 0 .28em #ddd3c0,0 0 0 .36em #a8997b,0 0 0 .42em #eee7d9,0 5em 6em -3em rgba(60,45,20,.38),0 2em 2.4em -2em rgba(0,0,0,.3)
