  align-items:center;
  justify-content:center;
  gap:5cqw;
  transition:opacity .8s cubic-bezier(.22,1,.36,1),scale .8s cubic-bezier(.22,1,.36,1)
}
.sp-lay .ph {
  --pw:19cqw
}
.sp-lay.after .ph {
  --pw:21.5cqw
