.sp-tag small {
  font-size:inherit;
  opacity:.75;
  font-weight:400
}
.sp-ustage {
  aspect-ratio:16/8.6
}
@media(max-width:700px) {
  .sp-unify {
    padding:20px
  }
  .sp-ustage {
    aspect-ratio:4/3.8
  }
  .sp-lay {
    gap:2cqw
  }
  .sp-lay .ph {
    --pw:28cqw
  }
  .sp-lay.after .ph {
    --pw:36cqw
  }
  .sp-ann {
    display:none
  }
  .sp-tag small {
    display:none
  }
