/* ---------- property card: one type token ---------- */
.p2-page .p2-bili-card,.p2-page .p2-bili-card[data-dir="rtl"] .card-arabic {
  font-family:"Switzer","IBM Plex Sans Arabic",sans-serif
}
.p2-page .p2-spec-list li {
  grid-template-columns:96px 1fr
}
.p2-spec-list .v small {
  display:block;
  color:var(--p2-mute);
  font-size:12px;
  margin-top:2px
}
/* ---------- outcomes equation ---------- */
.sp-eq {
  display:grid;
  grid-template-columns:minmax(0,1fr) auto minmax(0,1fr) auto minmax(0,1.25fr);
  align-items:stretch;
  gap:16px
}
.sp-op {
  align-self:center;
  width:52px;
  height:52px;
  border-radius:50%;
  background:#fff;
  border:1px solid rgba(0,0,0,.12);
  display:grid;
  place-items:center;
  font-size:26px;
  font-weight:300;
  line-height:1
}
.sp-col.res {
  background:#141414;
  color:#fff
}
.sp-col.res span {
  color:rgba(255,255,255,.6)
}
.sp-res {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:24px 20px
}
.sp-res b {
  display:block;
  font-size:clamp(32px,3.4vw,48px);
  font-weight:300;
  letter-spacing:-.03em;
  line-height:1
}
.sp-res small {
  display:block;
  font-size:13px;
  line-height:1.4;
  color:rgba(255,255,255,.7);
  margin-top:8px
}
.sp-col.res p {
