}
.cp-arch2.motion .a-in,.cp-arch2.motion .a-orch,.cp-arch2.motion .a-eng,.cp-arch2.motion .a-band,.cp-arch2.motion .a-out {
  transition:opacity .35s,box-shadow .35s,background .35s,transform .35s
}
.cp-arch2.motion .a-in,.cp-arch2.motion .a-band,.cp-arch2.motion .a-orch {
  opacity:.45
}
.cp-arch2.motion .a-out {
  opacity:.8
}
.cp-arch2.motion .act,.cp-arch2.motion .on {
  opacity:1!important
}
.cp-arch2.motion .a-in.act,.cp-arch2.motion .a-in.on {
  background:#fff
}
.cp-arch2.motion .a-orch.act,.cp-arch2.motion .a-band.act,.cp-arch2.motion .a-orch.on,.cp-arch2.motion .a-band.on {
  box-shadow:0 0 0 2px var(--cp-blue)
}
.cp-arch2.motion .a-out.act,.cp-arch2.motion .a-out.on {
  box-shadow:0 0 0 2px var(--cp-blue);
  opacity:1
}
.a-eng {
  background:#fff
}
.a-eng.hi {
  background:#fff;
  color:var(--p2-ink);
  border-color:rgba(0,0,0,.12)
}
.a-eng.hi small {
  color:var(--p2-mute)
}
.cp-arch2.motion .a-eng small {
  opacity:0;
  transition:opacity .35s
}
.cp-arch2.motion .a-eng.act,.cp-arch2.motion .a-eng.on {
  background:var(--cp-navy);
  color:#fff;
  border-color:var(--cp-navy)
}
.cp-arch2.motion .a-eng.act small,.cp-arch2.motion .a-eng.on small {
  opacity:1;
  color:rgba(255,255,255,.7)
}
.a-out .bub {
  width:46%;
  max-width:none;
  flex-shrink:0
}
.a-eng small {
  min-height:2.9em
}
.a-now {
  min-height:22px
}
.a-conn {
  overflow:visible
}
.a-conn::before {
  content:"";
  position:absolute;
  top:-3px;
  left:0;
  width:8px;
  height:8px;
  border-radius:50%;
  background:var(--cp-blue);
  opacity:0
}
.a-conn.act::before {
  animation:a-run 1.2s ease-in-out
}

@media(max-width:1000px) {
  .a-conn.act::before {
    animation:none
  }
}
@media(prefers-reduced-motion:reduce) {
  .a-conn.act::before {
    animation:none
  }
}
