/* Original: accru-kit.css */
:scope {
  --cp-blue:#5b4bd6;
  --cp-navy:#151517;
  --ac-green:#2f9e6b;
  --ac-lilac:#8b6cff;
  --ac-serif:Charter,"Bitstream Charter","Iowan Old Style",Georgia,serif
}
/* hero browser mock */
.ac-hero {
  container-type:inline-size;
  position:relative;
  overflow:hidden;
  background:var(--sp-sand)!important;
  display:grid;
  place-items:center
}
.ac-hero::before {
  content:"";
  position:absolute;
  width:46cqw;
  height:46cqw;
  left:-8cqw;
  top:-10cqw;
  border-radius:50%;
  background:radial-gradient(circle at 40% 40%,#fff 0 8%,#cfeede 30%,#e6dcff 60%,transparent 72%);
  filter:blur(1cqw);
  opacity:.9
}
.ac-hero::after {
  content:"";
  position:absolute;
  width:40cqw;
  height:40cqw;
  right:-6cqw;
  bottom:-14cqw;
  border-radius:50%;
  background:radial-gradient(circle,#e6dcff,transparent 65%);
  filter:blur(2cqw)
}
.am-b {
  position:relative;
  z-index:1;
  width:64cqw;
  background:#fafaf9;
  border-radius:1.2cqw;
  box-shadow:0 3cqw 5cqw -2cqw rgba(30,25,50,.25),0 0 0 1px rgba(0,0,0,.05);
  overflow:hidden;
  font-size:1cqw
}
.am-bar {
  display:flex;
  align-items:center;
  gap:.6cqw;
  padding:1cqw 1.4cqw;
  border-bottom:1px solid #ecebe8;
  background:#fff
}
.am-bar i {
  width:.8cqw;
  height:.8cqw;
  border-radius:50%;
  background:#e2e0dc
}
.am-bar b {
  margin-left:1.4cqw;
  font-weight:500;
  font-size:1.25cqw
}
.am-bar span {
  margin-left:auto;
  display:flex;
  gap:1.6cqw;
  color:#7a776f;
  font-size:1cqw
}
.am-bar em {
  font-style:normal;
  background:#151517;
  color:#fff;
  border-radius:99px;
  padding:.4cqw 1.2cqw
}
.am-hero {
  position:relative;
  padding:4cqw 4cqw 2.6cqw;
  text-align:center
}
.am-hero h3 {
  font-family:var(--ac-serif);
  font-weight:400;
  font-size:3.4cqw;
  line-height:1.1;
  margin:0
}
.am-hero h3 u {
  text-decoration:none;
  background:linear-gradient(transparent 62%,#bfe3ff 62% 88%,transparent 88%)
}
.am-hero p {
  margin:1.2cqw auto 0;
  max-width:40cqw;
  font-size:1.25cqw;
  color:#6b675f
}
.am-code {
  margin:0 4cqw 3cqw;
  background:#f2f1ee;
  border-radius:.8cqw;
  padding:1.4cqw 1.8cqw;
