  width: 100%;
  height: 100%;       /* ✅ fill grid cell */
  display: block;
  object-fit: cover;  /* ✅ clean cropping */
}

/* CAPTION */
.code-caption {
  margin-top: 8px;
  font-size: 12px;
  opacity: 0.3;
}

/* MOBILE */
@media (max-width: 768px) {

  .code-section {
    padding-left: 24px;
  }

  .code-inner {
    grid-template-columns: 1fr;
    row-gap: 24px;
  }

  .code-media-col {
    margin-right: 0;
  }

  .code-media {
    grid-template-columns: 1fr;
    aspect-ratio: auto; /* ✅ remove lock on mobile */
  }

  .code-media video,
  .code-media img {
    height: auto; /* ✅ natural stacking */
  }
}
