@media (max-width: 700px) {
  .p2-wrap { padding-left: 24px; padding-right: 24px; }
}

/* reveal animation */
.p2-rise {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1), transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}

.p2-rise.is-in {
  opacity: 1;
  transform: none;
}

/* ============ HERO ============ */

.p2-hero {
  position: relative;
  padding-top: 64px;
  padding-bottom: 0;
  background: #ffffff;
}

.p2-hero-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  font-family: var(--p2-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--p2-ink-soft);
  text-transform: uppercase;
  margin-bottom: 56px;
}

.p2-hero-meta .slash {
  color: var(--p2-mute);
}

.p2-hero-meta .meta-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.p2-hero-meta .dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #0a0a0a;
  display: inline-block;
}

.p2-hero-title {
  font-size: clamp(48px, 7.2vw, 104px);
  line-height: 0.96;
  font-weight: 400;
  letter-spacing: -0.025em;
  margin-bottom: 32px;
  text-wrap: balance;
}

.p2-hero-title em {
  font-style: normal;
  font-weight: 300;
}

.p2-hero-lede {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  padding-bottom: 48px;
}

.p2-hero-sub {
  font-size: clamp(22px, 2vw, 28px);
  line-height: 1.25;
  font-weight: 300;
  color: var(--p2-ink);
  max-width: 540px;
}

.p2-hero-detail {
  font-size: 14px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
  max-width: 460px;
  justify-self: end;
}

.p2-hero-detail strong { color: var(--p2-ink); font-weight: 600; }
.p2-hero-detail p + p { margin-top: 8px; }

@media (max-width: 900px) {
  .p2-hero-lede { grid-template-columns: 1fr; gap: 32px; }
  .p2-hero-detail { justify-self: start; }
}

/* ============ HERO VIDEO ============ */

.p2-hero-video {
  position: relative;
  width: calc(100% - 240px);
  max-width: 1100px;
  margin: 0 auto;
  aspect-ratio: 16 / 9;
  background: #04182b;
  overflow: hidden;
  border-radius: 24px;
}

.p2-video-fallback.hidden {
  display: none !important;
}

.p2-hero-video video,
.p2-hero-video .p2-video-fallback {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  background: #04182b;
}

.p2-video-fallback {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #efe9e1 0%, #e6dfd4 50%, #d9d0c1 100%);
  font-family: var(--p2-mono);
  font-size: 14px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #7a6b58;
}

.p2-video-fallback .fb-inner {
  text-align: center;
}

.p2-video-fallback .fb-play {
  width: 88px;
  height: 88px;
  border: 1.5px solid #7a6b58;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
}

.p2-video-fallback .fb-play::after {
  content: "";
  width: 0;
  height: 0;
  border-left: 18px solid #7a6b58;
  border-top: 12px solid transparent;
  border-bottom: 12px solid transparent;
  margin-left: 4px;
}

.p2-hero-video .p2-corner {
  position: absolute;
  top: 16px;
  left: 16px;
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  color: #ffffff;
  background: rgba(0,0,0,0.5);
  padding: 6px 10px;
  text-transform: uppercase;
  z-index: 2;
}

.p2-hero-video .p2-corner.right {
  left: auto;
  right: 16px;
}

@media (max-width: 900px) {
  .p2-hero-video {
    width: calc(100% - 80px);
  }
}

@media (max-width: 700px) {
  .p2-hero-video {
    width: calc(100% - 48px);
    border-radius: 16px;
  }
}

/* ============ STAT TICKER ============ */

.p2-stats {
  background: #0a0a0a;
  color: #fff;
  padding-top: 80px;
  padding-bottom: 80px;
  margin-top: 80px;
}

.p2-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-top: 1px solid rgba(255,255,255,0.12);
  border-bottom: 1px solid rgba(255,255,255,0.12);
}

.p2-stat {
  padding: 40px 32px 40px 0;
  border-right: 1px solid rgba(255,255,255,0.12);
  position: relative;
}

.p2-stat:last-child { border-right: none; }

.p2-stat .stat-no {
  font-family: var(--p2-mono);
  font-size: 11px;
  color: rgba(255,255,255,0.4);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin-bottom: 24px;
}

.p2-stat .stat-num {
  font-size: clamp(48px, 6vw, 76px);
  line-height: 0.95;
  letter-spacing: -0.025em;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  margin-bottom: 16px;
}

.p2-stat .stat-num .unit {
  font-size: 0.5em;
  margin-left: 0.05em;
  color: rgba(255,255,255,0.65);
}

.p2-stat .stat-label {
  font-size: 13px;
  line-height: 1.4;
  color: rgba(255,255,255,0.65);
}

@media (max-width: 900px) {
  .p2-stats-grid { grid-template-columns: 1fr 1fr; }
  .p2-stat:nth-child(2) { border-right: none; }
  .p2-stat:nth-child(1), .p2-stat:nth-child(2) {
    border-bottom: 1px solid rgba(255,255,255,0.12);
  }
}

@media (max-width: 560px) {
  .p2-stats-grid { grid-template-columns: 1fr; }
  .p2-stat { border-right: none; border-bottom: 1px solid rgba(255,255,255,0.12); padding: 28px 0; }
  .p2-stat:last-child { border-bottom: none; }
}

/* ============ MARQUEE ============ */

.p2-marquee {
  background: #0a0a0a;
  color: #fff;
  padding: 24px 0;
  margin-top: -1px;
  overflow: hidden;
  border-top: 1px solid rgba(255,255,255,0.12);
}

.p2-marquee-track {
  display: inline-flex;
  align-items: center;
  gap: 56px;
  white-space: nowrap;
  animation: p2-marquee 38s linear infinite;
  font-family: var(--p2-mono);
  font-size: 13px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.7);
}

.p2-marquee-track span.dot {
  width: 4px; height: 4px;
  background: rgba(255,255,255,0.3);
  border-radius: 50%;
  display: inline-block;
}

.p2-marquee-track strong {
  color: #fff;
  font-weight: 600;
}



/* ============ SECTION HEADERS ============ */

.p2-section {
  padding-top: 120px;
  padding-bottom: 0;
}

.p2-section-head {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  margin-bottom: 64px;
}

.p2-eyebrow {
  font-family: var(--p2-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--p2-mute);
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.p2-eyebrow .num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px; height: 22px;
  border: 1px solid var(--p2-mute);
  border-radius: 50%;
  font-size: 10px;
}

.p2-section-title {
  font-size: clamp(34px, 4.4vw, 56px);
  line-height: 1.05;
  letter-spacing: -0.02em;
  font-weight: 400;
  max-width: 720px;
}

.p2-section-blurb {
  font-size: 16px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
  max-width: 460px;
  justify-self: end;
}

@media (max-width: 900px) {
  .p2-section-head { grid-template-columns: 1fr; gap: 24px; }
  .p2-section-blurb { justify-self: start; }
  .p2-section { padding-top: 80px; }
}

/* ============ DEVICE SHOWCASE ============ */

.p2-device {
  position: relative;
  background: var(--p2-cream);
  padding: 96px 0;
  overflow: hidden;
}

.p2-device-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  align-items: end;
}

.p2-device-tile {
  background: #ffffff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 30px 60px -30px rgba(0,0,0,0.18);
  aspect-ratio: 9/19;
  position: relative;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.p2-device-tile.center { transform: translateY(-40px); }
.p2-device-tile.right { transform: translateY(20px); }

.p2-device-tile:hover { transform: translateY(-60px); }
.p2-device-tile.right:hover { transform: translateY(0); }
.p2-device-tile.left:hover { transform: translateY(-20px); }

.p2-device-tile img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.p2-device-tile video {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
  display: block;
  background: #000;
}

.p2-device-tag {
  position: absolute;
  top: 16px; left: 16px;
  font-family: var(--p2-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(0,0,0,0.55);
  background: rgba(255,255,255,0.9);
  padding: 5px 9px;
  border-radius: 999px;
  z-index: 2;
}

@media (max-width: 900px) {
  .p2-device-grid { grid-template-columns: 1fr; gap: 24px; }
  .p2-device-tile.center, .p2-device-tile.right { transform: none; }
  .p2-device-tile { aspect-ratio: 16/9; }
}

/* ============ INTERACTIVE BILINGUAL SANDBOX ============ */

.p2-bili {
  padding-top: 120px;
  padding-bottom: 120px;
}

.p2-bili-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--p2-line);
}

.p2-bili-hint {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--p2-mute);
}

.p2-toggle {
  display: inline-flex;
  background: #f2f2f2;
  border: 1px solid var(--p2-line);
  border-radius: 999px;
  padding: 4px;
  position: relative;
}

.p2-toggle button {
  position: relative;
  z-index: 1;
  background: none;
  border: none;
  cursor: pointer;
  padding: 10px 20px;
  font-family: var(--p2-mono);
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--p2-mute);
  border-radius: 999px;
  transition: color 0.3s ease;
}

.p2-toggle button[aria-pressed="true"] {
  color: #fff;
}

.p2-toggle .p2-toggle-pill {
  position: absolute;
  top: 4px; bottom: 4px;
  left: 4px;
  width: calc(50% - 4px);
  background: #0a0a0a;
  border-radius: 999px;
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}

.p2-toggle[data-dir="rtl"] .p2-toggle-pill {
  transform: translateX(100%);
}

.p2-bili-stage {
  display: grid;
  grid-template-columns: 380px 1fr;
  gap: 56px;
  align-items: start;
}

@media (max-width: 900px) {
  .p2-bili-stage { grid-template-columns: 1fr; gap: 32px; }
}

.p2-bili-spec {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.p2-bili-spec h3 {
  font-size: 24px;
  line-height: 1.2;
  font-weight: 400;
  letter-spacing: -0.01em;
}

.p2-bili-spec p {
  font-size: 14px;
  line-height: 1.55;
  color: var(--p2-ink-soft);
}

.p2-spec-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  border-top: 1px solid var(--p2-line);
}

.p2-spec-list li {
  display: grid;
  grid-template-columns: 88px 1fr;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--p2-line);
  font-size: 13px;
  color: var(--p2-ink-soft);
  align-items: center;
}

.p2-spec-list li .k {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--p2-mute);
}

.p2-spec-list li .v {
  font-variant-numeric: tabular-nums;
  transition: opacity 0.4s ease;
}

.p2-bili-card-wrap {
  background: var(--p2-paper);
  border-radius: 18px;
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 520px;
  position: relative;
  overflow: hidden;
}

.p2-bili-card-wrap::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 1px 1px, rgba(0,0,0,0.06) 1px, transparent 0);
  background-size: 24px 24px;
  opacity: 0.5;
  pointer-events: none;
}

.p2-bili-card {
  width: 100%;
  max-width: 380px;
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 30px 60px -30px rgba(0,0,0,0.25), 0 2px 6px rgba(0,0,0,0.04);
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
  position: relative;
  z-index: 1;
}

.p2-bili-card[data-dir="rtl"] {
  direction: rtl;
}

.p2-bili-card .card-media {
  width: 100%;
  aspect-ratio: 4/3;
  background:
    linear-gradient(135deg, rgba(0,0,0,0.05), transparent 50%),
    linear-gradient(180deg, #c9b893 0%, #b09971 60%, #927b56 100%);
  position: relative;
}

.p2-bili-card .card-media::after {
  /* villa silhouette */
  content: "";
  position: absolute;
  left: 12%; right: 12%; bottom: 8%; top: 38%;
  background:
    linear-gradient(180deg, transparent 30%, rgba(0,0,0,0.1) 100%),
    linear-gradient(180deg, #f5efe4 0%, #ede4d2 100%);
  clip-path: polygon(0 80%, 8% 80%, 8% 35%, 22% 22%, 38% 35%, 38% 50%, 62% 50%, 62% 35%, 78% 22%, 92% 35%, 92% 80%, 100% 80%, 100% 100%, 0 100%);
}

.p2-bili-card .card-tag {
  position: absolute;
  top: 16px; left: 16px;
  background: rgba(255,255,255,0.95);
  font-family: var(--p2-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 999px;
  color: #0a0a0a;
}

.p2-bili-card[data-dir="rtl"] .card-tag { left: auto; right: 16px; }

.p2-bili-card .card-fav {
  position: absolute;
  top: 16px; right: 16px;
  width: 32px; height: 32px;
  background: rgba(255,255,255,0.95);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.p2-bili-card[data-dir="rtl"] .card-fav { right: auto; left: 16px; }

.p2-bili-card .card-fav svg {
  width: 16px; height: 16px;
  fill: #0a0a0a;
}

.p2-bili-card .card-body {
  padding: 20px 22px 22px;
}

.p2-bili-card .card-row1 {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 4px;
}

.p2-bili-card .card-title {
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.01em;
}

.p2-bili-card .card-price {
  font-size: 18px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: #0a0a0a;
}

.p2-bili-card .card-loc {
  font-size: 13px;
  color: var(--p2-ink-soft);
  margin-bottom: 18px;
}

.p2-bili-card .card-feats {
  display: flex;
  gap: 18px;
  font-size: 12px;
  color: var(--p2-ink-soft);
  margin-bottom: 18px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--p2-line);
}

.p2-bili-card .card-feats span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.p2-bili-card .card-feats svg {
  width: 14px; height: 14px;
  stroke: var(--p2-ink-soft);
  fill: none;
  stroke-width: 1.5;
}

.p2-bili-card[data-dir="rtl"] .card-feats svg {
  transform: scaleX(-1);
}

.p2-bili-card .card-cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  font-weight: 500;
}

.p2-bili-card .card-cta .arr {
  width: 28px; height: 28px;
  border: 1px solid #0a0a0a;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background 0.3s, color 0.3s;
}

.p2-bili-card .card-cta:hover .arr {
  background: #0a0a0a;
  color: #fff;
}

.p2-bili-card .card-cta .arr svg {
  width: 12px; height: 12px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
}

.p2-bili-card[data-dir="rtl"] .card-cta .arr svg {
  transform: scaleX(-1);
}

.p2-bili-card[data-dir="rtl"] .card-arabic {
  font-family: "Noto Naskh Arabic", "Tajawal", Georgia, serif;
}

/* ============ PROCESS STEPPER ============ */

.p2-process {
  padding-top: 120px;
  padding-bottom: 80px;
}

.p2-process-tabs {
  display: flex;
  gap: 0;
  border-top: 1px solid var(--p2-line);
  border-bottom: 1px solid var(--p2-line);
  margin-bottom: 56px;
}

.p2-process-tab {
  flex: 1;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  padding: 24px 28px;
  border-right: 1px solid var(--p2-line);
  position: relative;
  transition: background 0.3s ease;
}

.p2-process-tab:last-child { border-right: none; }

.p2-process-tab:hover { background: #fafafa; }

.p2-process-tab .tab-no {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--p2-mute);
  margin-bottom: 12px;
}

.p2-process-tab .tab-title {
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--p2-ink);
  line-height: 1.25;
}

.p2-process-tab[aria-selected="true"] {
  background: #0a0a0a;
}

.p2-process-tab[aria-selected="true"] .tab-no { color: rgba(255,255,255,0.5); }
.p2-process-tab[aria-selected="true"] .tab-title { color: #fff; }

.p2-process-tab::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: -1px;
  height: 2px;
  background: #0a0a0a;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.p2-process-panels {
  position: relative;
}

.p2-process-panel {
  display: none;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: start;
}

.p2-process-panel.is-active {
  display: grid;
  animation: p2-fade-up 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
}



.p2-process-text h4 {
  font-size: 24px;
  font-weight: 500;
  letter-spacing: -0.01em;
  margin-bottom: 16px;
  line-height: 1.25;
}

.p2-process-text p {
  font-size: 15px;
  line-height: 1.6;
  color: var(--p2-ink-soft);
  margin-bottom: 14px;
}

.p2-process-text ul {
  margin-top: 16px;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.p2-process-text li {
  font-size: 14px;
  line-height: 1.5;
  color: var(--p2-ink-soft);
  padding-left: 20px;
  position: relative;
}

.p2-process-text li::before {
  content: "";
  position: absolute;
  left: 0; top: 9px;
  width: 8px; height: 1px;
  background: var(--p2-mute);
}

.p2-process-media {
  background: var(--p2-cream);
  border-radius: 18px;
  overflow: hidden;
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.p2-process-media img,
.p2-process-media video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

@media (max-width: 900px) {
  .p2-process-panel { grid-template-columns: 1fr; gap: 32px; }
  .p2-process-tabs { flex-direction: column; }
  .p2-process-tab { border-right: none; border-bottom: 1px solid var(--p2-line); }
  .p2-process-tab:last-child { border-bottom: none; }
}

/* ============ DESIGN SYSTEM REVEAL ============ */

.p2-ds {
  padding-top: 120px;
  padding-bottom: 120px;
  background: #fafaf8;
  margin-top: 80px;
}

.p2-ds-stage {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

@media (max-width: 900px) {
  .p2-ds-stage { grid-template-columns: 1fr; gap: 40px; }
}

.p2-ds-text h3 {
  font-size: clamp(28px, 3vw, 40px);
  line-height: 1.1;
  letter-spacing: -0.02em;
  font-weight: 400;
  margin-bottom: 24px;
}

.p2-ds-text p {
  font-size: 15px;
  line-height: 1.6;
  color: var(--p2-ink-soft);
  margin-bottom: 16px;
}

.p2-ds-pills {
  display: flex;
  gap: 8px;
  margin-top: 28px;
  flex-wrap: wrap;
}

.p2-ds-pill {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 8px 14px;
  border: 1px solid var(--p2-line);
  background: #fff;
  cursor: pointer;
  border-radius: 999px;
  color: var(--p2-ink-soft);
  transition: all 0.3s ease;
}

.p2-ds-pill[aria-pressed="true"] {
  background: #0a0a0a;
  color: #fff;
  border-color: #0a0a0a;
}

.p2-ds-viz {
  background: #fff;
  border-radius: 18px;
  padding: 40px;
  aspect-ratio: 1/1;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  box-shadow: 0 30px 60px -40px rgba(0,0,0,0.18);
}

.p2-ds-viz-stage {
  width: 100%;
  height: 100%;
  position: relative;
}

/* atoms */
.p2-ds-atom {
  position: absolute;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  transition: all 0.6s cubic-bezier(0.22, 1, 0.36, 1);
  font-family: var(--p2-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--p2-mute);
}

.p2-ds-atom .swatch {
  width: 48px; height: 48px;
  background: #0a0a0a;
  border-radius: 4px;
}

.p2-ds-atom.color1 { top: 0%; left: 0%; }
.p2-ds-atom.color1 .swatch { background: #0a0a0a; }
.p2-ds-atom.color2 { top: 0%; left: 30%; }
.p2-ds-atom.color2 .swatch { background: #d4a548; border-radius: 4px;}
.p2-ds-atom.color3 { top: 0%; left: 60%; }
.p2-ds-atom.color3 .swatch { background: #efe9e1; border: 1px solid #e0d8cc; }

.p2-ds-atom.type1 { top: 38%; left: 0%; }
.p2-ds-atom.type1 .swatch {
  background: none;
  width: auto; height: auto;
  font-family: "Switzer", sans-serif;
  font-size: 28px;
  font-weight: 500;
  color: #0a0a0a;
  letter-spacing: -0.02em;
}
.p2-ds-atom.type1 .swatch::before { content: "Aa"; }

.p2-ds-atom.space1 { top: 38%; left: 38%; }
.p2-ds-atom.space1 .swatch {
  background: none;
  width: 48px; height: 6px;
  border-top: 1px solid #0a0a0a;
  border-bottom: 1px solid #0a0a0a;
  position: relative;
}
.p2-ds-atom.space1 .swatch::before {
  content: "";
  position: absolute; left: 0; right: 0; top: 50%;
  border-top: 1px dashed var(--p2-mute);
}

/* molecules (buttons, inputs) */
.p2-ds-mol {
  position: absolute;
  opacity: 0;
  transform: translateY(20px) scale(0.95);
  transition: all 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  font-family: "Switzer", sans-serif;
}

.p2-ds-mol.btn {
  top: 60%; left: 0;
  background: #0a0a0a;
  color: #fff;
  font-size: 13px;
  padding: 12px 20px;
  border-radius: 8px;
}

.p2-ds-mol.input {
  top: 60%; left: 35%;
  background: #fff;
  border: 1px solid #ddd;
  font-size: 13px;
  padding: 12px 16px;
  border-radius: 8px;
  width: 160px;
  color: var(--p2-mute);
}

.p2-ds-mol.input::after { content: "Searchâ€¦"; }

/* organisms (card preview) */
.p2-ds-org {
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: scale(0.94);
  transition: all 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 16px 40px -16px rgba(0,0,0,0.18);
  border: 1px solid #ededed;
}

.p2-ds-org .org-img {
  height: 60%;
  background: linear-gradient(135deg, #d9c69b, #9a8259);
}

.p2-ds-org .org-body {
  padding: 20px;
}

.p2-ds-org .org-title {
  font-size: 16px;
  font-weight: 500;
  margin-bottom: 8px;
}

.p2-ds-org .org-meta {
  font-size: 12px;
  color: var(--p2-ink-soft);
}

/* mode states */
.p2-ds-viz[data-mode="atoms"] .p2-ds-mol,
.p2-ds-viz[data-mode="atoms"] .p2-ds-org { opacity: 0; pointer-events: none; }

.p2-ds-viz[data-mode="molecules"] .p2-ds-mol { opacity: 1; transform: none; pointer-events: auto; }
.p2-ds-viz[data-mode="molecules"] .p2-ds-org { opacity: 0; pointer-events: none; }
.p2-ds-viz[data-mode="molecules"] .p2-ds-atom { opacity: 0.35; }

.p2-ds-viz[data-mode="organisms"] .p2-ds-mol,
.p2-ds-viz[data-mode="organisms"] .p2-ds-atom { opacity: 0; pointer-events: none; }
.p2-ds-viz[data-mode="organisms"] .p2-ds-org { opacity: 1; transform: none; pointer-events: auto; }

/* ============ IMAGE STRIP ============ */

.p2-strip {
  padding-top: 80px;
  padding-bottom: 0;
}

.p2-strip-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.p2-strip-grid img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  border-radius: 8px;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.p2-strip-grid > div {
  overflow: hidden;
  border-radius: 8px;
  display: block;
  position: relative;
}

.p2-strip-grid > div:hover img {
  transform: scale(1.04);
}

.p2-strip-grid > div::after {
  content: attr(data-cap);
  position: absolute;
  left: 12px;
  bottom: 12px;
  font-family: var(--p2-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #fff;
  background: rgba(0,0,0,0.6);
  padding: 5px 9px;
  border-radius: 999px;
}

@media (max-width: 900px) {
  .p2-strip-grid { grid-template-columns: 1fr 1fr; }
}

/* ============ OUTCOMES ============ */

.p2-outcomes {
  padding-top: 120px;
  padding-bottom: 120px;
}

.p2-outcomes-head {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  margin-bottom: 64px;
}

.p2-outcomes-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  border-top: 1px solid var(--p2-line);
}

.p2-outcomes-item {
  padding: 40px 0;
  border-bottom: 1px solid var(--p2-line);
  border-right: 1px solid var(--p2-line);
  padding-right: 32px;
  padding-left: 0;
  display: grid;
  grid-template-rows: auto 1fr auto;
  min-height: 220px;
}

.p2-outcomes-item:nth-child(3n) { border-right: none; padding-right: 0; }
.p2-outcomes-item:nth-child(3n/**/+2),
.p2-outcomes-item:nth-child(3n/**/+3) { padding-left: 32px; }

.p2-outcomes-item .o-num {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--p2-mute);
  margin-bottom: 24px;
}

.p2-outcomes-item .o-big {
  font-size: clamp(36px, 4vw, 56px);
  line-height: 1;
  letter-spacing: -0.025em;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  margin-bottom: 12px;
}

.p2-outcomes-item .o-big .unit {
  font-size: 0.5em;
  color: var(--p2-ink-soft);
  margin-left: 0.1em;
}

.p2-outcomes-item .o-label {
  font-size: 14px;
  line-height: 1.4;
  color: var(--p2-ink-soft);
}

@media (max-width: 700px) {
  .p2-outcomes-grid { grid-template-columns: 1fr; }
  .p2-outcomes-item { border-right: none; padding-left: 0 !important; padding-right: 0 !important; }
}

.p2-outcomes-summary {
  margin-top: 48px;
  padding: 32px;
  background: #0a0a0a;
  color: #fff;
  border-radius: 18px;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  gap: 32px;
}

.p2-outcomes-summary p {
  font-size: clamp(18px, 1.8vw, 22px);
  line-height: 1.35;
  font-weight: 400;
  max-width: 760px;
}

.p2-outcomes-summary .o-source {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
}

@media (max-width: 700px) {
  .p2-outcomes-summary { grid-template-columns: 1fr; }
}

/* ============ REFLECTION / NEXT ============ */

.p2-reflect {
  padding-top: 0;
  padding-bottom: 120px;
}

.p2-reflect-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: start;
}

@media (max-width: 900px) {
  .p2-reflect-grid { grid-template-columns: 1fr; gap: 32px; }
}

.p2-reflect h3 {
  font-size: clamp(28px, 3vw, 40px);
  line-height: 1.1;
  letter-spacing: -0.02em;
  font-weight: 400;
  margin-bottom: 0;
}

.p2-reflect ul {
  list-style: none;
  padding: 0;
  margin: 0;
  border-top: 1px solid var(--p2-line);
}

.p2-reflect li {
  font-size: 15px;
  line-height: 1.45;
  color: var(--p2-ink);
  padding: 18px 0;
  border-bottom: 1px solid var(--p2-line);
  display: grid;
  grid-template-columns: 24px 1fr;
  gap: 16px;
  align-items: baseline;
}

.p2-reflect li .num {
  font-family: var(--p2-mono);
  font-size: 11px;
  color: var(--p2-mute);
  letter-spacing: 0.1em;
}

/* ============ NEXT PROJECT ============ */

.p2-next {
  background: #0a0a0a;
  color: #fff;
  padding-top: 80px;
  padding-bottom: 80px;
}

.p2-next-eyebrow {
  font-family: var(--p2-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  margin-bottom: 24px;
}

.p2-next-link {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  gap: 32px;
  text-decoration: none;
  color: #fff;
  padding: 32px 0;
  border-top: 1px solid rgba(255,255,255,0.15);
  border-bottom: 1px solid rgba(255,255,255,0.15);
  transition: padding 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.p2-next-link:hover {
  padding-left: 16px;
}

.p2-next-link h3 {
  font-size: clamp(32px, 4.4vw, 56px);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.05;
}

.p2-next-link .arrow {
  font-size: 32px;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.p2-next-link:hover .arrow {
  transform: translateX(12px);
}

/* ============ MISC ============ */

.p2-hr {
  border: 0;
  border-top: 1px solid var(--p2-line);
  margin: 0;
}

.p2-page .contact-banner { margin-top: 0; }


.p2-section-title em,.p2-next-link em,.p2-process-text h4 em{font-style:normal}

/* no scroll-reveal */
.p2-rise,.p2-rise.is-in{opacity:1!important;transform:none!important;transition:none!important}


