.sheet{flex:1;min-height:0;margin-top:-2.4em;background:#fff;border-radius:2.4em 2.4em 0 0;position:relative;z-index:3;padding:1.9em 1.8em 2.4em;display:flex;flex-direction:column;gap:1.15em}
.ttl{display:flex;justify-content:space-between;align-items:flex-start;gap:1em}
.ttl b{display:block;font-size:2em;color:#141414}.ttl small{display:block;font-size:1.08em;color:#8b8b8b;margin-top:.3em}
.ttl .p{text-align:end;flex-shrink:0}.ttl .p b{font-size:1.45em;font-weight:600;font-family:"Switzer",sans-serif}
.ft{display:flex;gap:.6em}.ft span{flex:1;background:#f5f5f3;border-radius:1.25em;padding:.95em .4em;display:flex;flex-direction:column;align-items:center;gap:.35em}
.ft svg{width:1.7em;height:1.7em;color:#141414}.ft i{font-style:normal;font-size:1.05em}
.mort{background:#f5f5f3;border-radius:1.6em;padding:1.25em 1.4em;display:flex;flex-direction:column;gap:.55em}
.mort .h{display:flex;justify-content:space-between;font-size:1.02em;color:#8b8b8b}.mort .h u{text-decoration:none;color:#141414;font-weight:500}
.mort b{font-size:2em;font-weight:300;letter-spacing:-.02em}
.bar{height:.5em;border-radius:1em;background:#ededed;overflow:hidden}.bar i{display:block;height:100%;width:62%;background:#141414;border-radius:1em}
.mort small{font-size:.98em;color:#8b8b8b}
.cta{margin-top:auto;display:flex;gap:.7em}
.btn{flex:1;height:4.7em;border-radius:2.4em;background:#141414;color:#fff;display:grid;place-items:center}.btn i{font-style:normal;font-size:1.25em;font-weight:500}
.sq{width:4.7em;height:4.7em;border-radius:50%;background:#f5f5f3;display:grid;place-items:center}.sq svg{width:1.8em;height:1.8em}
.home{flex:1;min-height:0;border-radius:2em;background:#cbbd9f center/cover;position:relative;overflow:hidden}
.home .ov{position:absolute;inset:auto 0 0;padding:4em 1.5em 1.4em;background:linear-gradient(180deg,transparent,rgba(20,24,14,.68));color:#fff;display:flex;flex-direction:column;gap:.45em}
.home .ov small{font-size:1em;opacity:.85}.home .ov b{font-size:1.7em;font-weight:600}
.home .bar{background:rgba(255,255,255,.3)}.home .bar i{width:85%;background:#fff}
.home .meta{display:flex;justify-content:space-between;font-size:.98em;opacity:.9}
.rqs{display:flex;flex-direction:column;gap:.6em;flex-shrink:0}
.rq{display:flex;align-items:center;gap:1em;background:#f5f5f3;border-radius:1.4em;padding:.8em}
.rq .ic{width:3.5em;height:3.5em;border-radius:1.1em;display:grid;place-items:center;flex-shrink:0}.rq .ic svg{width:1.6em;height:1.6em}
.rq .tx{flex:1;min-width:0}.rq b{display:block;font-size:1.12em;font-weight:600}.rq small{display:block;font-size:.95em;color:#8b8b8b}
.pill{font-size:.92em;padding:.3em .8em;border-radius:2em;white-space:nowrap;font-weight:500}
.pay{background:#dcefe0;color:#141414;border-radius:1.7em;padding:1.2em 1.4em;display:flex;justify-content:space-between;align-items:center;flex-shrink:0;margin-bottom:.4em}
.pay small{display:block;font-size:.98em;opacity:.6}.pay b{display:block;font-size:1.6em;font-weight:600}
.pay span{background:#141414;color:#fff;border-radius:2em;padding:.7em 1.5em}.pay span i{font-style:normal;font-size:1.1em;font-weight:600}
.lg{flex:1;padding:3.5em 2.2em 3em;display:flex;flex-direction:column;gap:1.1em}
.lg .lgo{align-self:flex-start;width:5.2em;height:5.2em;border-radius:50%;display:grid;place-items:center;color:#fff;margin-bottom:1em}.lg .lgo i{font-style:normal;font-size:2.1em;font-weight:500}
.lg>b{font-size:2.6em;line-height:1.08;color:#141414}
.lg p{font-size:1.1em;color:#8b8b8b;margin:0 0 1em}
.fld{height:4.4em;border-radius:2.2em;background:#f5f5f3;border:1px solid #eaeaea;padding:0 1.5em;display:flex;align-items:center}.fld i{font-style:normal;font-size:1.12em;color:#b0b0b0}
.lg .btn{flex:none;margin-top:auto}.lg .alt{text-align:center;font-size:1.05em;color:#8b8b8b}
.ph.wire .scr{filter:grayscale(1) contrast(.9)}
.ph.wire .ed-photo{background-image:none!important;background:repeating-linear-gradient(45deg,#e4e1dc 0 .6em,#eeece8 .6em 1.2em)}

.lg.v1{padding-top:2.5em}.lg.v1 .lgo{border-radius:.5em;width:100%;height:4.6em;align-self:stretch;justify-content:start;padding-left:1.2em;margin-bottom:1.6em}.lg.v1 .lgo i{font-size:1.4em;font-weight:700}
.lg.v1>b{font-family:Arial,Helvetica,sans-serif;font-weight:700;font-size:2.3em;letter-spacing:-.01em}.lg.v1 .fld{border-radius:.4em;background:#eef1f6;border:0}.lg.v1 .btn{border-radius:.4em}
.lg.v2{background:#0e5e45;color:#fff}.lg.v2 .lgo{background:#fff!important;color:#0e5e45}.lg.v2 .ed-eb,.lg.v2 p,.lg.v2 .alt{color:rgba(255,255,255,.7)}
.lg.v2>b{font-family:Georgia,serif;font-weight:400;color:#fff;font-size:2.8em;letter-spacing:0}.lg.v2 .fld{background:transparent;border:0;border-bottom:1px solid rgba(255,255,255,.5);border-radius:0;padding:0}.lg.v2 .fld i{color:rgba(255,255,255,.6)}
.lg.v2 .btn{background:transparent!important;border:1.5px solid #fff;border-radius:0}
.lg.v3{background:#fff4ec;align-items:center;text-align:center}.lg.v3 .lgo{align-self:center;border-radius:1.4em}.lg.v3>b{font-weight:800;font-size:2.4em;color:#b6451a;letter-spacing:-.02em}
.lg.v3 .fld{align-self:stretch;border-radius:2.2em;border:2px solid #f2c9b1;background:#fff}.lg.v3 .btn{align-self:stretch;border-radius:2.4em;box-shadow:0 .6em 1.2em -.4em rgba(226,102,45,.6)}
/* ---------- hero art ---------- */
.sp-hero-art{container-type:inline-size;position:relative;background:var(--sp-sand)!important;overflow:hidden}
.sp-hero-art .p2-corner{background:rgba(35,38,29,.85)}
@media(max-width:1100px){.sp-hero-art .p2-corner.right{display:none}}
.sp-hero-art .ph{position:absolute;--pw:20cqw;top:6.5cqw;animation:sp-float 8s ease-in-out infinite}
.sp-hero-art .ph.h1{left:12cqw}.sp-hero-art .ph.h2{left:40cqw;animation-delay:-2.6s}.sp-hero-art .ph.h3{left:68cqw;animation-delay:-5.2s}
.sp-hl{position:absolute;top:2.4cqw;width:20cqw;text-align:center;font-family:var(--p2-mono);font-size:max(9px,1.05cqw);letter-spacing:.06em;text-transform:uppercase;color:var(--p2-ink)}
.sp-hsys{position:absolute;left:12cqw;right:12cqw;bottom:2.2cqw;display:flex;justify-content:space-between;align-items:center;gap:2cqw;background:#141414;color:#fff;border-radius:1.2cqw;padding:1.1cqw 1.8cqw;z-index:3}
.sp-hsys span{font-family:var(--p2-mono);font-size:max(9px,1cqw);letter-spacing:.06em;text-transform:uppercase;color:rgba(255,255,255,.65)}.sp-hsys b{font-size:max(10px,1.35cqw);font-weight:500}
@media(max-width:700px){.sp-hsys span{display:none}}

.sp-fc{position:absolute;z-index:4;background:rgba(255,255,255,.95);border-radius:1.2cqw;padding:1.1cqw 1.4cqw;display:flex;align-items:center;gap:1cqw;box-shadow:0 2cqw 3cqw -1.5cqw rgba(0,0,0,.22);font-size:max(10px,1.15cqw);line-height:1.3}
.sp-fc .ok{width:2.6cqw;height:2.6cqw;border-radius:50%;background:#36412a;color:#fff;display:grid;place-items:center;flex-shrink:0}
.sp-fc .ok svg{width:1.3cqw;height:1.3cqw;fill:none;stroke:currentColor;stroke-width:2.4}
.sp-fc b{display:block;font-weight:500}.sp-fc small{color:var(--p2-mute)}
.sp-fc.a{left:8cqw;bottom:12cqw}.sp-fc.b{right:7cqw;top:14cqw}.sp-fc.b .ok{background:#9a7b4f}

/* ---------- unify ---------- */
.sp-unify{background:var(--sp-sand);border-radius:18px;padding:32px;position:relative;overflow:hidden}
.sp-unify-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:8px;flex-wrap:wrap}
.sp-ustage{container-type:inline-size;position:relative;aspect-ratio:16/8}
.sp-lay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:5cqw;transition:opacity .8s cubic-bezier(.22,1,.36,1),scale .8s cubic-bezier(.22,1,.36,1)}
.sp-lay .ph{--pw:19cqw}
.sp-lay.after .ph{--pw:21.5cqw}
.sp-unify[data-state="before"] .after,.sp-unify[data-state="after"] .before{opacity:0;scale:.94;pointer-events:none}

.sp-ann{position:absolute;width:24cqw;font-size:max(11px,1.35cqw);line-height:1.4;color:var(--p2-ink-soft)}
.sp-ann b{display:block;font-family:var(--p2-mono);font-size:max(9px,1cqw);letter-spacing:.14em;text-transform:uppercase;color:var(--p2-ink);font-weight:500;margin-bottom:.5cqw}
.sp-ann.l{left:4cqw;top:30%;text-align:right}.sp-ann.r{right:4cqw;top:55%}
.sp-ann::after{content:"";position:absolute;top:1cqw;height:1px;width:8cqw;background:var(--p2-ink)}
.sp-ann.l::after{left:calc(100% + 1.5cqw)}.sp-ann.r::after{right:calc(100% + 1.5cqw)}


/* ---------- methodology art ---------- */
.sp-art{container-type:inline-size;background:var(--sp-sand);border-radius:18px;aspect-ratio:4/3;position:relative;overflow:hidden}
.sp-art .cap{position:absolute;left:16px;bottom:14px;font-family:var(--p2-mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--p2-ink-soft);z-index:5}
/* board */
.sp-board{position:absolute;inset:0;background:var(--sp-sand);background-image:radial-gradient(circle at 1px 1px,rgba(0,0,0,.09) 1px,transparent 0);background-size:16px 16px}
.sp-tool{position:absolute;top:2.4cqw;left:50%;translate:-50% 0;display:flex;gap:1.6cqw;background:#fff;border-radius:1.4cqw;padding:1cqw 1.8cqw;box-shadow:0 .6cqw 2cqw rgba(0,0,0,.08);z-index:3}
.sp-tool i{width:2.2cqw;height:2.2cqw;border-radius:.5cqw;background:#e8e4dc}.sp-tool i:nth-child(3){background:#f6e3a6}.sp-tool i:nth-child(4){background:#141414;border-radius:50%}
.sp-sec{position:absolute;top:10cqw;height:52cqw;width:22.5cqw;border-radius:1.4cqw;opacity:0;scale:.97;transition:opacity .5s .8s,scale .5s .8s}
.sp-sec span{position:absolute;top:-.2cqw;left:1.2cqw;translate:0 -50%;font-size:max(9px,1.45cqw);font-weight:500;padding:.5cqw 1.1cqw;border-radius:.7cqw;color:#fff;white-space:nowrap}
.is-active .sp-sec{opacity:1;scale:1}
.sp-st{position:absolute;width:19cqw;min-height:15cqw;padding:1.4cqw;font-size:max(9px,1.55cqw);line-height:1.3;box-shadow:0 .5cqw 1.2cqw -.4cqw rgba(0,0,0,.22),0 .1cqw .2cqw rgba(0,0,0,.08);border-radius:.4cqw;display:flex;flex-direction:column;justify-content:space-between;gap:1cqw;transition:left 1s cubic-bezier(.22,1,.36,1),top 1s cubic-bezier(.22,1,.36,1),rotate 1s;z-index:2;color:#1d1a15}
.sp-st small{font-size:max(8px,1.2cqw);color:rgba(0,0,0,.5);display:flex;align-items:center;gap:.6cqw}
.sp-st small::before{content:"";width:1.6cqw;height:1.6cqw;border-radius:50%;background:currentColor;opacity:.5}
.sp-cur{position:absolute;z-index:4;left:60%;top:70%;transition:left 1.4s cubic-bezier(.22,1,.36,1),top 1.4s cubic-bezier(.22,1,.36,1);pointer-events:none}
.sp-cur svg{width:2.4cqw;height:2.4cqw;display:block}
.sp-cur span{display:inline-block;margin:.2cqw 0 0 1.6cqw;background:#c94235;color:#fff;font-size:max(9px,1.3cqw);padding:.3cqw .9cqw;border-radius:.6cqw .6cqw .6cqw 0}
/* IA wire */
.sp-ia2 .ph{--pw:25cqw;position:absolute;left:50%;top:9cqw;translate:-50% 0}
.sp-strip{position:absolute;top:3cqw;left:3.4cqw;display:flex;align-items:center;gap:1cqw;font-size:max(10px,1.4cqw)}
.sp-strip s{color:var(--p2-mute)}.sp-strip b{font-weight:500}
.sp-co{position:absolute;width:27cqw;font-size:max(10px,1.45cqw);line-height:1.35;color:var(--p2-ink-soft);opacity:0;translate:0 1cqw;transition:opacity .5s,translate .5s}
.sp-co b{display:block;color:var(--p2-ink);font-weight:500;margin-bottom:.3cqw}
.sp-co .n{font-family:var(--p2-mono);font-size:max(9px,1.1cqw);color:var(--p2-mute);letter-spacing:.1em}
.sp-co::after{content:"";position:absolute;top:1.1cqw;height:1px;background:var(--p2-ink);width:var(--ln,9cqw)}
.sp-co::before{content:"";position:absolute;top:.6cqw;width:1.1cqw;height:1.1cqw;border-radius:50%;background:var(--sp-gold);border:2px solid #fff;box-shadow:0 0 0 1px var(--p2-ink)}
.sp-co.l{left:3.4cqw;text-align:right}.sp-co.l::after{left:calc(100% + 1cqw)}.sp-co.l::before{left:calc(100% + 1cqw + var(--ln,9cqw))}
.sp-co.r{right:3.4cqw}.sp-co.r::after{right:calc(100% + 1cqw)}.sp-co.r::before{right:calc(100% + 1cqw + var(--ln,9cqw))}
.is-active .sp-co{opacity:1;translate:0 0}
.is-active .sp-co:nth-of-type(2){transition-delay:.15s}.is-active .sp-co:nth-of-type(3){transition-delay:.3s}.is-active .sp-co:nth-of-type(4){transition-delay:.45s}
/* system sheet */
.sp-sys{position:absolute;inset:3.4cqw 3.4cqw 8cqw;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:2cqw}
.sp-fr{background:#fff;border-radius:1.6cqw;padding:2.2cqw;display:flex;flex-direction:column;gap:1.6cqw;box-shadow:0 1cqw 2.4cqw -1.4cqw rgba(0,0,0,.18);opacity:0;translate:0 1.5cqw;transition:opacity .5s,translate .5s;min-width:0;overflow:hidden}
.is-active .sp-fr{opacity:1;translate:0 0}
.is-active .sp-fr:nth-child(2){transition-delay:.12s}.is-active .sp-fr:nth-child(3){transition-delay:.24s}.is-active .sp-fr:nth-child(4){transition-delay:.36s}
.sp-fl{display:flex;justify-content:space-between;font-family:var(--p2-mono);font-size:max(8px,1.15cqw);letter-spacing:.12em;text-transform:uppercase;color:var(--p2-mute)}
.sp-sw{display:flex;gap:1cqw}.sp-sw i{flex:1;aspect-ratio:1;border-radius:50%;box-shadow:inset 0 0 0 1px rgba(0,0,0,.08)}
.sp-ty{display:flex;align-items:baseline;gap:1.4cqw}.sp-ty b{font-size:4cqw;font-weight:400;letter-spacing:-.03em;line-height:1}.sp-ty span{font-family:"IBM Plex Sans Arabic",sans-serif;font-size:3.4cqw;line-height:1}.sp-ty small{margin-left:auto;font-family:var(--p2-mono);font-size:max(8px,1.1cqw);color:var(--p2-mute)}
.sp-at{display:flex;flex-wrap:wrap;gap:1cqw;align-items:center}
.sp-b{font-size:max(9px,1.4cqw);padding:1cqw 1.8cqw;border-radius:99px;background:#141414;color:#fff;white-space:nowrap}
.sp-b.g{background:transparent;color:#141414;box-shadow:inset 0 0 0 1px #141414}.sp-b.y{background:var(--sp-gold);color:#141414}
.sp-tg{width:4.4cqw;height:2.5cqw;border-radius:99px;background:#141414;position:relative}.sp-tg::after{content:"";position:absolute;right:.35cqw;top:.35cqw;width:1.8cqw;height:1.8cqw;border-radius:50%;background:#fff}
.sp-ck{width:2.5cqw;height:2.5cqw;border-radius:.6cqw;background:var(--sp-gold);display:grid;place-items:center}.sp-ck svg{width:1.6cqw;height:1.6cqw;fill:none;stroke:#141414;stroke-width:3}
.sp-chip{font-size:max(9px,1.25cqw);padding:.7cqw 1.4cqw;border-radius:99px;background:rgba(212,165,72,.2);color:#7d5a10}
.sp-in{display:flex;align-items:center;gap:1cqw;border:1px solid #e6e1d8;border-radius:1.2cqw;padding:1.2cqw 1.4cqw;font-size:max(9px,1.35cqw);color:var(--p2-mute)}
.sp-in svg{width:1.8cqw;height:1.8cqw;fill:none;stroke:currentColor;stroke-width:2}.sp-in kbd{margin-left:auto;font-family:var(--p2-mono);font-size:max(8px,1.05cqw);background:#f2efe9;padding:.3cqw .7cqw;border-radius:.5cqw}
.sp-seg{display:flex;background:#f2efe9;border-radius:1.2cqw;padding:.5cqw}.sp-seg span{flex:1;text-align:center;font-size:max(9px,1.3cqw);padding:.8cqw;border-radius:.9cqw;color:var(--p2-ink-soft)}.sp-seg span.on{background:#fff;color:#141414;box-shadow:0 .2cqw .6cqw rgba(0,0,0,.08)}
.sp-oc{display:flex;gap:1.4cqw;align-items:center;flex:1;min-height:0}
.sp-oc .im{width:40%;align-self:stretch;border-radius:1.2cqw;background:#cbbd9f center/cover}
.sp-oc b{display:block;font-size:max(10px,1.6cqw);font-weight:500}.sp-oc small{display:block;font-size:max(9px,1.2cqw);color:var(--p2-mute);margin:.3cqw 0 1cqw}.sp-oc em{font-style:normal;font-size:max(10px,1.5cqw);font-weight:600}
/* parity */
.sp-par2{position:absolute;inset:3cqw 3cqw 8cqw;display:flex;justify-content:center;align-items:center;gap:9cqw}
.sp-par2 .ph{--pw:28.5cqw}
.sp-axis{position:absolute;left:50%;top:0;bottom:0;border-left:1px dashed var(--p2-ink)}
.sp-axis span{position:absolute;top:50%;left:0;translate:-50% -50%;writing-mode:vertical-rl;background:var(--sp-sand);padding:1cqw 0;font-family:var(--p2-mono);font-size:max(8px,1.1cqw);letter-spacing:.14em;text-transform:uppercase;white-space:nowrap}
.sp-plab{position:absolute;top:0;font-family:var(--p2-mono);font-size:max(8px,1.1cqw);letter-spacing:.14em;text-transform:uppercase;color:var(--p2-ink-soft)}

/* bilingual card photo */
.p2-bili-card .card-media{background:#cbbd9f url("https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=900&q=70") center/cover!important}
.p2-bili-card .card-media::after{display:none!important}

/* locked */
.sp-lock{background:#23261d;color:#fff;padding:120px 0}
.sp-lock .p2-section-title{color:#fff}.sp-lock .p2-section-blurb{color:rgba(255,255,255,.65)}
.sp-lock .p2-eyebrow{color:rgba(255,255,255,.5)}.sp-lock .p2-eyebrow .num{border-color:rgba(255,255,255,.5)}
.sp-lock-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:56px;align-items:start}
.sp-chapters{list-style:none;margin:0;padding:0;border-top:1px solid rgba(255,255,255,.14)}
.sp-chapters li{display:grid;grid-template-columns:40px minmax(0,1fr) auto;gap:16px;align-items:center;padding:20px 0;border-bottom:1px solid rgba(255,255,255,.14)}
.sp-chapters .n{font-family:var(--p2-mono);font-size:11px;color:rgba(255,255,255,.45)}
.sp-chapters .t{font-size:18px}.sp-chapters .t small{display:block;font-size:13px;color:rgba(255,255,255,.55);margin-top:4px}
.sp-chapters svg{width:14px;height:14px;stroke:rgba(255,255,255,.55);fill:none;stroke-width:1.6}
.sp-gate{background:#fff;color:var(--p2-ink);border-radius:18px;padding:36px;display:flex;flex-direction:column;gap:16px;position:sticky;top:100px}
.sp-gate h3{font-size:28px;font-weight:400;letter-spacing:-.01em;line-height:1.15}
.sp-gate p{font-size:14px;line-height:1.55;color:var(--p2-ink-soft)}
.sp-gate .password-row{margin-top:8px}
.sp-gate .error-message{min-height:18px;font-size:13px;color:#a33a2c}
.sp-gate .alt a{color:var(--p2-ink);text-decoration:underline;text-underline-offset:3px}
@media(max-width:900px){.sp-lock-grid{grid-template-columns:1fr}.sp-gate{position:static}.sp-lock{padding:80px 0}}

/* ---------- type: no mono, no italics ---------- */
.p2-page .p2-hero-title em,.p2-page .p2-section-title em,.p2-page .p2-next-link em,.p2-page h3 em,.p2-page h4 em{font-style:normal;color:var(--p2-mute)}
.p2-page .p2-eyebrow,.p2-page .tab-no,.p2-page .stat-no,.p2-page .p2-corner,.p2-page .sp-note,.p2-page .p2-bili-hint,.p2-page .p2-next-eyebrow,.p2-page .cap{letter-spacing:.06em}

/* ---------- role ---------- */
.sp-org{container-type:inline-size;background:var(--sp-sand);border-radius:18px;padding:48px 32px 32px}
.sp-streams{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:3cqw}
.sp-stream{display:flex;flex-direction:column;align-items:center;gap:22px;text-align:center;position:relative;padding-bottom:44px}
.sp-stream::after{content:"";position:absolute;bottom:0;left:50%;height:30px;border-left:1px solid var(--p2-ink)}
.sp-stream .ph{--pw:min(27cqw,330px)}
.sp-lab span{display:block;font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute)}
.sp-lab b{display:block;font-size:20px;font-weight:500;margin-top:6px}
.sp-stream>p{font-size:14px;line-height:1.5;color:var(--p2-ink-soft);max-width:28ch;margin:0}
.sp-base{display:flex;justify-content:space-between;align-items:center;gap:8px 16px;flex-wrap:wrap;background:#fff;border-radius:14px;padding:20px 24px}
.sp-base span{font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute)}
.sp-base b{font-size:17px;font-weight:500}
.sp-base.sys{background:var(--sp-olive);color:#fff}.sp-base.sys span{color:rgba(255,255,255,.7)}
.sp-wire{height:20px;width:0;margin:0 auto;border-left:1px solid var(--p2-ink)}
.sp-own{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:32px;margin-top:56px}
.sp-own div{border-top:1px solid var(--p2-ink);padding-top:18px}
.sp-own span{font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;color:var(--p2-mute)}
.sp-own h4{font-size:19px;font-weight:500;margin:10px 0 8px}
.sp-own p{font-size:14px;line-height:1.55;color:var(--p2-ink-soft);margin:0}
@media(max-width:900px){.sp-own{grid-template-columns:1fr 1fr}}
@media(max-width:700px){.sp-org{padding:28px 14px 14px}.sp-stream .ph{--pw:27cqw}.sp-lab b{font-size:14px}.sp-stream>p{display:none}.sp-own{grid-template-columns:1fr}}

/* ---------- outcomes ---------- */
.sp-out{padding-bottom:40px}
.sp-attr{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.sp-col{background:var(--sp-sand);border-radius:18px;padding:28px}
.sp-col.me{background:var(--sp-olive);color:#fff}
.sp-col span{display:block;font-family:var(--p2-mono);font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute);margin-bottom:20px}
.sp-col.me span{color:rgba(255,255,255,.7)}
.sp-col ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.sp-col li{font-size:16px;line-height:1.4;padding:12px 0;border-top:1px solid rgba(0,0,0,.12)}
.sp-col.me li{border-color:rgba(255,255,255,.2)}
@media(max-width:900px){.sp-attr{grid-template-columns:1fr}}

.p2-page .stat-num{font-size:clamp(40px,5vw,72px)}
.p2-page .p2-stats-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
@media(max-width:1000px){.p2-page .p2-stats-grid{grid-template-columns:repeat(2,minmax(0,1fr));row-gap:32px}.p2-page .p2-stat{padding-left:0!important}}
.sp-stream .ph{text-align:start}

/* ---------- before/after tags ---------- */
.sp-pc{display:flex;flex-direction:column;align-items:center;gap:2cqw}
.sp-tag{display:inline-flex;align-items:center;gap:.7cqw;font-size:max(11px,1.35cqw);font-weight:500;padding:.8cqw 1.6cqw;border-radius:99px;white-space:nowrap;color:#fff;background:#b3261e;box-shadow:0 .6cqw 1.4cqw -.6cqw rgba(179,38,30,.6)}
.sp-tag.ok{background:#141414;box-shadow:0 .6cqw 1.4cqw -.6cqw rgba(0,0,0,.5)}
.sp-tag small{font-size:inherit;opacity:.75;font-weight:400}
.sp-ustage{aspect-ratio:16/8.6}
@media(max-width:700px){.sp-unify{padding:20px}.sp-ustage{aspect-ratio:4/3.8}.sp-lay{gap:2cqw}.sp-lay .ph{--pw:28cqw}.sp-lay.after .ph{--pw:36cqw}.sp-ann{display:none}.sp-tag small{display:none}}

/* ---------- property card: one type token ---------- */
.p2-page .p2-bili-card,.p2-page .p2-bili-card[data-dir="rtl"] .card-arabic{font-family:"Switzer","IBM Plex Sans Arabic",sans-serif}
.p2-page .p2-spec-list li{grid-template-columns:96px 1fr}
.p2-spec-list .v small{display:block;color:var(--p2-mute);font-size:12px;margin-top:2px}

/* ---------- outcomes equation ---------- */
.sp-eq{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr) auto minmax(0,1.25fr);align-items:stretch;gap:16px}
.sp-op{align-self:center;width:52px;height:52px;border-radius:50%;background:#fff;border:1px solid rgba(0,0,0,.12);display:grid;place-items:center;font-size:26px;font-weight:300;line-height:1}
.sp-col.res{background:#141414;color:#fff}.sp-col.res span{color:rgba(255,255,255,.6)}
.sp-res{display:grid;grid-template-columns:1fr 1fr;gap:24px 20px}
.sp-res b{display:block;font-size:clamp(32px,3.4vw,48px);font-weight:300;letter-spacing:-.03em;line-height:1}
.sp-res small{display:block;font-size:13px;line-height:1.4;color:rgba(255,255,255,.7);margin-top:8px}
.sp-col.res p{margin:24px 0 0;padding-top:16px;border-top:1px solid rgba(255,255,255,.2);font-size:14px;line-height:1.5;color:rgba(255,255,255,.8)}
.sp-col.me{background:var(--sp-sand);color:var(--p2-ink)}.sp-col.me span{color:var(--p2-mute)}.sp-col.me li{border-color:rgba(0,0,0,.12)}
.sp-col.tm{background:#fff;box-shadow:inset 0 0 0 1px rgba(0,0,0,.1)}
@media(max-width:1000px){.sp-eq{grid-template-columns:1fr}.sp-op{justify-self:center}}

.sp-conf{max-width:760px;margin:0 0 28px;padding:14px 18px;border-radius:12px;background:var(--sp-sand);border:1px solid rgba(0,0,0,.08);font-size:14px;line-height:1.5;color:var(--p2-ink-soft)}
.sp-conf strong{color:var(--p2-ink);font-weight:500}

/* no staged reveals inside illustrations */
.sp-co,.sp-fr,.sp-sec{opacity:1!important;translate:none!important;scale:none!important;transition:none!important}


/* Original: partner-copilot-kit.css */
.ico{display:inline-grid;place-items:center;flex-shrink:0;font-style:normal}.ico svg{width:100%;height:100%}
.cp-lab{font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute)}

/* mandate */
.cp-vs2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}
.cp-vs2>div{background:var(--sp-sand);border-radius:18px;padding:28px;display:flex;flex-direction:column;gap:20px}
.cp-vs2 h4{margin:4px 0 0;font-size:22px;font-weight:500}
.cp-vs2 .sum{display:flex;align-items:baseline;gap:10px;border-top:1px solid rgba(0,0,0,.12);padding-top:16px;font-size:15px;color:var(--p2-ink-soft)}
.cp-vs2 .sum b{font-size:32px;font-weight:300;color:var(--p2-ink);letter-spacing:-.02em}
.mx{display:grid;grid-template-columns:64px repeat(5,minmax(0,1fr));gap:6px;align-items:stretch}
.mx .rl{font-size:12px;color:var(--p2-mute);display:flex;align-items:center}
.mx .ch{font-size:12px;text-align:center;padding:4px 0;color:var(--p2-ink-soft)}
.mx .b{height:38px;border-radius:8px;border:1.5px dashed rgba(0,0,0,.28);display:grid;place-items:center}
.mx .b .ico{width:16px;height:16px;color:rgba(0,0,0,.4)}
.mx .b.w1{transform:translateY(3px)}.mx .b.w2{transform:translateY(-3px)}.mx .b.w3{height:30px;align-self:center}
.mx .sk{height:26px;border-radius:99px;display:grid;place-items:center;font-size:11px;font-weight:500}
.mx .span{grid-column:2/-1;height:38px;border-radius:8px;border:1.5px solid var(--p2-ink);background:#fff;display:flex;align-items:center;gap:8px;padding:0 12px;font-size:13px;font-weight:500}
.mx .span .ico{width:16px;height:16px}
.mx .gap{grid-column:1/-1;height:4px}
@media(max-width:900px){.cp-vs2{grid-template-columns:1fr}}

/* leadership */
.cp-flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));background:var(--sp-sand);border-radius:18px;padding:28px 12px;align-items:stretch}
.cp-node{padding:4px 20px;display:flex;flex-direction:column;gap:10px}
.cp-node+.cp-node{border-left:1px solid rgba(0,0,0,.12)}
.cp-node .who{font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute);display:flex;align-items:center;gap:8px}
.cp-node .who .ico{width:18px;height:18px;color:var(--p2-ink)}
.cp-node b{font-size:19px;font-weight:500}.cp-node p{font-size:14px;line-height:1.5;color:var(--p2-ink-soft);margin:0}
.cp-node.me{border:1.5px solid var(--p2-ink);border-radius:14px;background:transparent;padding:18px 20px;margin:-12px 4px}
.cp-node.me+.cp-node{border-left:0}
.cp-node.me ul{margin:2px 0 0;padding:0;list-style:none;display:flex;flex-direction:column;gap:8px;font-size:14px}
.cp-node.me li{display:flex;gap:8px;align-items:center}.cp-node.me li .ico{width:16px;height:16px;color:var(--cp-blue)}
@media(max-width:900px){.cp-flow{grid-template-columns:1fr 1fr;row-gap:28px}.cp-node+.cp-node{border-left:0}.cp-node.me{margin:0}}
@media(max-width:560px){.cp-flow{grid-template-columns:1fr}}

/* architecture */
.cp-arch2{display:grid;grid-template-columns:minmax(0,.9fr) 48px minmax(0,1.5fr) 48px minmax(0,1fr);align-items:center;background:var(--sp-sand);border-radius:18px;padding:32px}
.a-col{display:flex;flex-direction:column;gap:4px}
.a-hd{display:flex;align-items:center;gap:10px;margin-bottom:12px}
.a-hd b{width:24px;height:24px;border-radius:50%;background:var(--p2-ink);color:#fff;display:grid;place-items:center;font-size:12px;font-weight:500}
.a-hd span{font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase}
.a-in{display:flex;gap:12px;align-items:flex-start;padding:12px 4px;border-top:1px solid rgba(0,0,0,.1)}
.a-in .ico{width:20px;height:20px;margin-top:1px}
.a-in b,.a-eng b,.a-band b,.a-out b{display:block;font-size:14px;font-weight:500}
.a-in small,.a-eng small,.a-band small,.a-out small{display:block;font-size:12.5px;color:var(--p2-mute);line-height:1.4;margin-top:2px}
.a-conn{position:relative;height:2px;background:var(--p2-ink);margin:0 6px}
.a-conn::after{content:"";position:absolute;right:-1px;top:-4px;border:5px solid transparent;border-left:7px solid var(--p2-ink);border-right:0}
.a-core{background:#fff;border:1.5px solid var(--p2-ink);border-radius:16px;padding:20px;display:flex;flex-direction:column;gap:10px}
.a-pats{display:flex;justify-content:center;gap:6px;flex-wrap:wrap}
.a-pats span{font-size:12px;padding:5px 12px;border-radius:99px;background:var(--sp-sand)}
.a-orch{display:flex;align-items:center;justify-content:center;gap:10px;padding:10px;border-radius:12px;border:1px solid rgba(0,0,0,.12)}
.a-orch .ico{width:20px;height:20px;color:var(--cp-blue)}
.a-engs{display:grid;grid-template-columns:1fr 14px 1fr 14px 1fr;align-items:center}
.a-engs>i.arw{height:1.5px;background:rgba(0,0,0,.35)}
.a-eng{border-radius:12px;padding:14px 10px;text-align:center;border:1px solid rgba(0,0,0,.12)}
.a-eng .ico{width:24px;height:24px;margin-bottom:6px}
.a-eng.hi{background:var(--cp-navy);color:#fff;border-color:var(--cp-navy)}.a-eng.hi small{color:rgba(255,255,255,.65)}
.a-band{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;background:var(--sp-sand)}
.a-band .ico{width:20px;height:20px}
.a-out{display:flex;align-items:center;gap:12px;padding:10px;border-radius:14px;color:#fff}
.a-out .ico{width:34px;height:34px;padding:8px;border-radius:50%;background:rgba(255,255,255,.16)}
.a-out small{color:rgba(255,255,255,.72)}
.a-out .bub{margin-left:auto;font-size:11px;line-height:1.3;max-width:42%;padding:7px 9px;border-radius:10px 10px 10px 3px;background:rgba(255,255,255,.14)}
.a-out+.a-out{margin-top:6px}
.cp-arch2.live [data-k]{cursor:pointer;transition:box-shadow .15s}
.cp-arch2.live [data-k]:hover{box-shadow:0 0 0 2px rgba(47,91,255,.35)}
.cp-arch2.live [data-k].on{box-shadow:0 0 0 2px var(--cp-blue)}
.cp-arch2.live .a-in{border-radius:10px}
.cp-adet{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1fr) minmax(0,1fr);gap:24px;border:1.5px solid var(--p2-ink);border-radius:14px;padding:20px 24px;margin-top:16px}
.cp-adet span{display:block;font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute);margin-bottom:6px}
.cp-adet b{font-size:20px;font-weight:500}.cp-adet p{margin:0;font-size:14px;line-height:1.5}
@media(max-width:1000px){.cp-arch2{grid-template-columns:1fr;gap:12px}.a-conn{width:2px;height:28px;margin:0 auto}.a-conn::after{right:-4px;top:auto;bottom:-1px;border:5px solid transparent;border-top:7px solid var(--p2-ink);border-bottom:0}.cp-adet{grid-template-columns:1fr}}
@media(max-width:600px){.a-engs{grid-template-columns:1fr}.a-engs>i.arw{display:none}.a-out .bub{display:none}}

/* configuration */
.cp-cfg{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:40px;align-items:start;background:var(--sp-sand);border-radius:18px;padding:32px}
.cp-cfg .ph{--pw:270px}
.cfg-pre{display:flex;gap:8px;margin-bottom:20px}
.cfg-pre button{font:inherit;font-size:14px;padding:10px 18px;border-radius:99px;border:1px solid rgba(0,0,0,.15);background:#fff;cursor:pointer;color:var(--p2-ink)}
.cfg-pre button[aria-pressed="true"]{background:var(--p2-ink);color:#fff;border-color:var(--p2-ink)}
.cfg-ctl{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.cfg-g{background:#fff;border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:12px}
.cfg-h{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--p2-ink-soft)}.cfg-h .ico{width:18px;height:18px;color:var(--p2-ink)}
.cfg-sw{display:flex;align-items:center;gap:8px}.cfg-sw i{width:30px;height:30px;border-radius:50%;box-shadow:inset 0 0 0 1px rgba(0,0,0,.12)}.cfg-sw b{margin-left:auto;font-size:28px;font-weight:400;line-height:1}
.cfg-seg{display:flex;background:var(--sp-sand);border-radius:10px;padding:3px}.cfg-seg span{flex:1;text-align:center;font-size:13px;padding:7px;border-radius:8px;color:var(--p2-mute)}.cfg-seg span.on{background:#fff;color:var(--p2-ink);box-shadow:0 1px 3px rgba(0,0,0,.08)}
.cfg-ag{display:flex;flex-direction:column;gap:8px}.cfg-ag span{display:flex;align-items:center;gap:8px;font-size:13.5px}.cfg-ag .ico{width:16px;height:16px}
.cfg-ag em{margin-left:auto;width:30px;height:18px;border-radius:99px;background:var(--p2-ink);position:relative}.cfg-ag em::after{content:"";position:absolute;top:2px;right:2px;width:14px;height:14px;border-radius:50%;background:#fff}
.cfg-ag .off{color:var(--p2-mute)}.cfg-ag .off em{background:#dcd9d3}.cfg-ag .off em::after{right:auto;left:2px}
.cfg-ds{display:flex;flex-wrap:wrap;gap:6px}.cfg-ds span{display:flex;align-items:center;gap:6px;font-size:12.5px;padding:6px 10px;border-radius:99px;border:1px dashed rgba(0,0,0,.25);color:var(--p2-mute)}
.cfg-ds .ico{width:14px;height:14px}.cfg-ds span.on{border:1px solid var(--p2-ink);color:var(--p2-ink);background:var(--sp-sand)}
.cfg-ru{display:flex;flex-direction:column;gap:8px}.cfg-ru span{display:flex;align-items:center;gap:8px;font-size:13.5px}.cfg-ru .ico{width:18px;height:18px;padding:3px;border-radius:50%}
.cfg-ru .y .ico{background:#e3f4ea;color:#1f6b3e}.cfg-ru .n{color:var(--p2-mute)}.cfg-ru .n .ico{background:#fbe3e1;color:#9c2a22}
.cfg-sl span{display:block;position:relative;height:6px;border-radius:6px;background:#eceae6}.cfg-sl span i{position:absolute;inset:0 auto 0 0;border-radius:6px;background:var(--p2-ink)}
.cfg-sl span b{position:absolute;top:50%;width:16px;height:16px;margin:-8px 0 0 -8px;border-radius:50%;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.3)}
.cfg-sl em{display:block;margin-top:10px;font-style:normal;font-size:13px;color:var(--p2-ink-soft)}
@media(max-width:1000px){.cp-cfg{grid-template-columns:1fr;justify-items:center}.cp-cfg>div:first-child{width:100%}}
@media(max-width:600px){.cfg-ctl{grid-template-columns:1fr}}

/* simulator extras */
.cp-graph{border:1px solid #ecebe8;border-radius:12px;padding:14px}
.cp-graph .lab{display:block;font-family:var(--p2-mono);font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute);margin-bottom:10px}
.cp-graph>div{display:flex;align-items:center;gap:8px}
.cp-graph .col{display:flex;flex-direction:column;gap:6px;flex:1}
.cp-graph .col span{font-size:12.5px;text-align:center;padding:8px 6px;border-radius:8px;border:1.5px solid var(--p2-ink);background:#fff}
.cp-graph .col:first-child span,.cp-graph .col:last-child span{background:var(--sp-sand);border-color:transparent}
.cp-graph i.ar{width:14px;height:1.5px;background:var(--p2-ink);flex-shrink:0}
.cp-eval{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:13px}.cp-eval>span{color:var(--p2-mute);margin-right:4px}
.cp-eval em{font-style:normal;display:flex;align-items:center;gap:6px;padding:6px 10px;border-radius:99px;background:#e3f4ea;color:#1f6b3e}.cp-eval svg{width:14px;height:14px}

/* tabs */
.cp-tabs{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:20px}
.cp-tab{font:inherit;font-size:14px;padding:10px 16px;border-radius:99px;border:1px solid rgba(0,0,0,.15);background:#fff;cursor:pointer;color:var(--p2-ink);display:flex;align-items:center;gap:8px}
.cp-tab .ico{width:16px;height:16px}
.cp-tab[aria-pressed="true"]{background:var(--p2-ink);color:#fff;border-color:var(--p2-ink)}

/* zoom stepper */
.cp-zoom{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px;align-items:stretch}
.zf{position:relative;aspect-ratio:16/10;border-radius:18px;overflow:hidden;background:var(--zbg,#fff);box-shadow:inset 0 0 0 1px rgba(0,0,0,.06)}
.zf img{position:absolute;left:0;top:0;max-width:none;transform-origin:0 0;transition:transform .7s cubic-bezier(.22,1,.36,1),width .7s cubic-bezier(.22,1,.36,1)}
.zs{display:flex;flex-direction:column;gap:6px}
.zd{display:flex;flex-direction:column;gap:2px}
.zd button{font:inherit;text-align:left;display:flex;gap:12px;align-items:baseline;padding:12px 14px;border:0;border-radius:10px;background:transparent;cursor:pointer;color:var(--p2-mute)}
.zd button b{font-family:var(--p2-mono);font-size:11px;font-weight:400}.zd button span{font-size:15px}
.zd button[aria-pressed="true"]{background:var(--sp-sand);color:var(--p2-ink)}
.zc{font-size:14px;line-height:1.55;color:var(--p2-ink-soft);padding:12px 14px 0;margin:0}
.zn-row{display:flex;gap:8px;margin-top:auto;padding:12px 14px 0}
.zn-row button{font:inherit;width:40px;height:40px;border-radius:50%;border:1px solid rgba(0,0,0,.15);background:#fff;cursor:pointer;font-size:16px}
@media(max-width:900px){.cp-zoom{grid-template-columns:1fr}.zd{flex-direction:row;overflow-x:auto}.zd button span{display:none}}

/* journey */
.cj{background:var(--sp-sand);border-radius:18px;padding:32px}
.cj-top{display:flex;justify-content:space-between;align-items:baseline;gap:16px;margin-bottom:28px;flex-wrap:wrap}
.cj-top h3{margin:0;font-size:clamp(20px,2vw,26px);font-weight:400;letter-spacing:-.01em;max-width:620px;line-height:1.25}
