.cp-story p{margin:0;font-size:15px;line-height:1.55;color:var(--p2-ink-soft)}
.cp-story ul{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:10px;font-size:15px;line-height:1.45}
.cp-story li{display:flex;gap:10px;align-items:flex-start}.cp-story li .ico{width:20px;height:20px;margin-top:1px;color:var(--cp-blue)}
.cp-story-tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px}
.cp-story-tags span{display:flex;align-items:center;gap:6px;font-size:13px;padding:6px 12px;border-radius:99px;border:1px solid rgba(0,0,0,.18)}
.cp-story-tags .ico{width:15px;height:15px}
@media(max-width:900px){.cp-story{grid-template-columns:1fr;gap:24px}}

/* type scale on copilot pages */
.p2-page .p2-hero-title{font-size:clamp(28px,3vw,44px);line-height:1.12;text-wrap:balance;padding-bottom:28px;margin-bottom:28px;border-bottom:1px solid rgba(0,0,0,.14)}
.p2-page .p2-section-title{font-size:clamp(22px,2.2vw,32px);line-height:1.2}
/* chats start under the header */
.cp-msgs{justify-content:flex-end;padding-top:1em;padding-bottom:2.4em;gap:.8em}
/* learning loop */
.cp-arch2.motion .a-eng.fed{border-style:dashed;border-color:var(--cp-blue)}
.cp-arch2.learning [data-k="learn"] .ico{animation:cp-spin 1.2s linear infinite;color:var(--cp-blue)}
.cp-arch2.learning [data-k="learn"] small{color:var(--cp-blue)}
.cp-arch2.learning .a-out{opacity:.55}
/* videos at natural phone ratio */
.lu-2:has(.bf.nat){grid-template-columns:repeat(2,minmax(0,300px));justify-content:center;gap:32px}
.bf.nat{border-radius:28px}

.cp-hero-art .ph{--pw:18.5cqw;top:5cqw}
.cp-hero-art .sp-hsys{white-space:nowrap;bottom:1.6cqw;padding:.9cqw 1.6cqw}
.cp-hero-art .sp-hsys b{overflow:hidden;text-overflow:ellipsis}
@media(max-width:1100px){.cp-hero-art .sp-hsys span{display:none}.cp-hero-art .sp-hsys{justify-content:center}}
.p2-page .p2-hero-title em{font-style:normal;color:inherit;font-weight:inherit;font-family:inherit}
.p2-page .p2-hero-sub strong{font-weight:500;color:var(--p2-ink)}
.cp-zoom{align-items:start}.zf{width:100%;height:auto;align-self:start}


/* Original: partner-partner-kit.css */
:scope{--pe-blue:#5a46d6;--pe-blue-soft:#eeebfc;--pe-mint:#ecefe9;--pe-lav:#eeebfa;--pe-blush:#f2ebe5;--pe-butter:#f3eee3;--pe-amber:#b7791f;--pe-red:#b4473a;--pe-green:#2f7a5b}
.pe-chips{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 20px}
.pe-chips span{font-size:13px;padding:6px 12px;border-radius:99px;border:1px solid rgba(0,0,0,.14);color:var(--p2-ink-soft)}
.pe-lab{font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute)}
.pe-cap{margin:12px 0 0;font-size:13px;line-height:1.5;color:var(--p2-mute);max-width:640px}
.pe-stage{background:var(--sp-sand);border-radius:18px;padding:32px}
/* browser window */
.pe-win{background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 24px 48px -28px rgba(30,25,15,.35),0 0 0 1px rgba(0,0,0,.05)}
.pe-wbar{display:flex;align-items:center;gap:5px;padding:8px 12px;border-bottom:1px solid #eeece8;background:#fafaf8}
.pe-wbar i{width:7px;height:7px;border-radius:50%;background:#dedbd5}.pe-wbar span{flex:1;text-align:center;font-family:var(--p2-mono);font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute);margin-right:26px}
.pe-side{display:flex;flex-direction:column;gap:10px;padding:14px 10px;border-right:1px solid #eeece8}
.pe-side i{width:16px;height:16px;border-radius:5px;background:#efedea}.pe-side i:first-child{background:none;box-shadow:inset 0 0 0 1.5px var(--pe-blue)}
/* hero */
.pe-hero{container-type:inline-size;position:relative;overflow:hidden;background:var(--sp-sand)!important}
.pe-hero .pe-win{position:absolute;font-size:1cqw}
.pe-hero .w1{left:5cqw;top:6cqw;width:52cqw}.pe-hero .w2{right:5cqw;top:24cqw;width:52cqw;z-index:2}
.pe-pub{padding:3cqw 3cqw 3cqw;display:grid;grid-template-columns:1fr 18cqw;gap:2cqw}
.pe-pub h4{margin:0;font-size:2.6cqw;font-weight:500;line-height:1.1;letter-spacing:-.02em}
.pe-pub .ln{height:.6cqw;border-radius:1cqw;background:#efedea;margin-top:1.2cqw}.pe-pub .ln.s{width:60%}
.pe-pub .btns{display:flex;gap:.8cqw;margin-top:2cqw}.pe-pub .btns span{font-size:1.15cqw;padding:1cqw 1.6cqw;border-radius:99px;border:1px solid #d9d6d0}.pe-pub .btns span:first-child{background:#141414;color:#fff;border-color:#141414}
.pe-pub .pe-photo{aspect-ratio:1;border-radius:50%;background:#d9d3c7 url("https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?auto=format&fit=crop&w=500&q=70") center/cover}
.pe-bento{grid-column:1/-1;display:grid;grid-template-columns:repeat(4,1fr);gap:.9cqw}
.pe-bento span{min-height:6cqw;border-radius:.9cqw;padding:1cqw;font-size:1.15cqw}
.c-mint{background:var(--pe-mint)}.c-lav{background:var(--pe-lav)}.c-blush{background:var(--pe-blush)}.c-butter{background:var(--pe-butter)}
.pe-in{display:grid;grid-template-columns:auto 1fr}
.pe-home{padding:2.4cqw 2.6cqw}
.pe-home b.g{display:block;font-size:2cqw;font-weight:500;letter-spacing:-.01em}
.pe-home small.id{display:block;margin-top:.5cqw;font-size:1.05cqw;color:var(--p2-mute)}
.pe-cols{display:grid;grid-template-columns:1fr 1fr;margin-top:2cqw;border-top:1px solid #eeece8}
.pe-cols>div{padding:1.6cqw 1.6cqw 0 0}.pe-cols>div+div{padding-left:1.6cqw;border-left:1px solid #eeece8}
.pe-cols h6{margin:0 0 1cqw;font-size:1.2cqw;font-weight:500}
.pe-it{display:flex;gap:.9cqw;align-items:center;margin-bottom:1cqw;font-size:1.15cqw;line-height:1.3}
.pe-it i{flex-shrink:0;width:2cqw;height:2cqw;border-radius:.5cqw;background:var(--pe-mint)}
.pe-it i.am{background:var(--pe-butter);box-shadow:inset 0 0 0 1.5px var(--pe-amber)}.pe-it i.bl{background:var(--pe-lav)}
.pe-it em{display:block;font-style:normal;font-size:.95cqw}.pe-it em.am{color:var(--pe-amber)}.pe-it em.bl{color:var(--pe-blue)}
@media(max-width:700px){.pe-hero .w1{width:62cqw}.pe-hero .w2{width:62cqw;top:22cqw}}
/* portals */
.pe-portals{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) 48px minmax(0,1.2fr);gap:12px;align-items:center}
.pe-portal{background:#fff;border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:10px;border-top:0}
.pe-portal b{font-size:14px;font-weight:500}.pe-portal .ln{height:6px;border-radius:6px;background:#efedea}.pe-portal .ln.s{width:60%}
.pe-portal .so{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--pe-red)}.pe-portal .so .ico{width:14px;height:14px}
.pe-portal:nth-child(1){transform:rotate(-1.5deg)}.pe-portal:nth-child(3){transform:rotate(1.5deg)}
.pe-arr{display:grid;place-items:center}.pe-arr .ico{width:26px;height:26px}
.pe-hub{background:#fff;border-radius:14px;box-shadow:0 0 0 1.5px var(--p2-ink);display:grid;grid-template-columns:auto 1fr;overflow:hidden}
.pe-hub .pe-side i{width:14px;height:14px}
.pe-hub>div:last-child{padding:16px;display:flex;flex-direction:column;gap:8px}
.pe-hub b{font-size:15px;font-weight:500}.pe-hub .ok{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--pe-green)}.pe-hub .ok .ico{width:14px;height:14px}
@media(max-width:900px){.pe-portals{grid-template-columns:1fr}.pe-portal{transform:none!important}.pe-arr{transform:rotate(90deg)}}
/* team */
.pe-org{display:flex;flex-direction:column;align-items:center;gap:0;padding:36px 24px}
.pe-org .row{display:flex;flex-wrap:wrap;justify-content:center;gap:10px}
.pe-org .vl{width:1.5px;height:24px;background:var(--p2-ink)}
.pe-org .rail{width:min(560px,90%);height:1.5px;background:var(--p2-ink);margin-bottom:0}
.pe-org .rail+.row{padding-top:0}
.pe-pill{font-size:14px;padding:10px 16px;border-radius:99px;background:#fff;box-shadow:inset 0 0 0 1px rgba(0,0,0,.12);display:flex;align-items:center;gap:8px}
.pe-pill .ico{width:16px;height:16px}
.pe-pill.me{background:var(--pe-blue);color:#fff;box-shadow:none}.pe-pill.ld{box-shadow:inset 0 0 0 1.5px var(--p2-ink)}
.pe-pill.pt{background:transparent;box-shadow:inset 0 0 0 1px rgba(0,0,0,.25);border:0;color:var(--p2-ink-soft);outline:1px dashed transparent}
.pe-org .lab2{margin:18px 0 10px;font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute)}
/* role switcher */
.pe-roles .seg{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}
.pe-roles .seg button{font:inherit;font-size:14px;padding:10px 16px;border-radius:99px;border:1px solid rgba(0,0,0,.15);background:#fff;cursor:pointer;color:var(--p2-ink);display:flex;gap:8px;align-items:center}
.pe-roles .seg .ico{width:16px;height:16px}
.pe-roles .seg button[aria-pressed="true"]{background:var(--p2-ink);color:#fff;border-color:var(--p2-ink)}
.pe-app{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:420px}
.pe-nav{border-right:1px solid #eeece8;padding:14px 10px;display:flex;flex-direction:column;gap:2px}
.pe-nav span{display:flex;justify-content:space-between;align-items:center;font-size:14px;padding:9px 10px;border-radius:8px;transition:background .25s}
.pe-nav span.r{background:var(--pe-blue-soft)}.pe-nav span.r em{font-style:normal;font-family:var(--p2-mono);font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--pe-blue)}
.pe-nav span.off{color:#c3c0b9}
.pe-view{padding:26px 30px;display:flex;flex-direction:column;gap:12px}
.pe-view q{font-size:clamp(18px,1.8vw,24px);line-height:1.3;letter-spacing:-.01em;quotes:"“" "”"}
.pe-view>p{margin:0;font-size:14px;color:var(--p2-ink-soft)}
.pe-view .pe-homecards{margin-top:14px;border-top:1px solid #eeece8;padding-top:16px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.pe-view .pe-homecards div{display:flex;flex-direction:column;gap:8px}
.pe-view .pe-homecards i{display:block;height:64px;border-radius:10px}
.pe-view .pe-homecards b{font-size:14px;font-weight:500}.pe-view .pe-homecards small{font-size:12.5px;color:var(--p2-mute);line-height:1.4}
@media(max-width:800px){.pe-app{grid-template-columns:1fr}.pe-nav{border-right:0;border-bottom:1px solid #eeece8;flex-direction:row;flex-wrap:wrap}.pe-view .pe-homecards{grid-template-columns:1fr}}
/* decision */
.pe-dec{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:48px;align-items:start}
.pe-dec dl{margin:0;display:grid;grid-template-columns:140px 1fr;border-top:1px solid rgba(0,0,0,.14)}
.pe-dec dt,.pe-dec dd{padding:14px 0;border-bottom:1px solid rgba(0,0,0,.1)}
.pe-dec dt{font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute);padding-top:17px}
.pe-dec dd{margin:0;font-size:15px;line-height:1.5}
.pe-dec dd.k{font-weight:500}
.pe-stack{display:flex;flex-direction:column;gap:6px}
.pe-stack div{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:14px 16px;border-radius:10px;background:var(--sp-sand);font-size:14.5px}
.pe-stack div em{font-style:normal;font-family:var(--p2-mono);font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute)}
.pe-stack div.nx{background:transparent;border:1.5px dashed rgba(0,0,0,.28);color:var(--p2-ink-soft)}
.pe-stack div.nx em{color:var(--pe-blue)}
.pe-stack div:last-child{background:var(--p2-ink);color:#fff}.pe-stack div:last-child em{color:rgba(255,255,255,.6)}
.pe-stack .base{margin-top:6px;font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute);text-align:center;background:none;padding:0}
@media(max-width:900px){.pe-dec{grid-template-columns:1fr;gap:28px}.pe-dec dl{grid-template-columns:110px 1fr}}
.pe-more{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px;margin-top:32px;max-width:900px}
.pe-more p{margin:0;font-size:15px;line-height:1.55}.pe-more b{font-weight:500}
@media(max-width:800px){.pe-more{grid-template-columns:1fr}}
/* toc */
.sp-toc{list-style:none;margin:16px 0 0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 32px;border-top:1px solid rgba(0,0,0,.14)}
.sp-toc a{display:grid;grid-template-columns:36px minmax(0,1fr) auto;gap:12px;align-items:start;padding:20px 0;border-bottom:1px solid rgba(0,0,0,.14);text-decoration:none;color:var(--p2-ink)}
.sp-toc .n{font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;color:var(--p2-mute);padding-top:4px}
.sp-toc .t{font-size:17px;font-weight:500}.sp-toc .t small{display:block;font-size:13px;font-weight:400;color:var(--p2-mute);margin-top:4px;line-height:1.4}
.sp-toc svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.6;margin-top:5px}
@media(max-width:900px){.sp-toc{grid-template-columns:1fr}}
[id^="ch"]{scroll-margin-top:100px}
/* annotated homepage */
.pe-ann{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:28px;align-items:center}
.pe-ann .pe-win{font-size:10px}
.pe-ann .pe-home{padding:20px 22px}
.pe-ann .pe-home b.g{font-size:19px}.pe-ann .pe-home small.id{font-size:12px}
.pe-zone{position:relative;border-radius:10px;transition:box-shadow .25s,background .25s;padding:6px;margin:-6px}
.pe-zone.on{box-shadow:0 0 0 1.5px var(--pe-blue);background:rgba(61,91,217,.04)}
.pe-zone .tg{position:absolute;top:-9px;right:8px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:inset 0 0 0 1.5px var(--pe-blue);color:var(--pe-blue);font-family:var(--p2-mono);font-size:11px;display:grid;place-items:center;opacity:0;transition:opacity .25s}
.pe-zone.on .tg{opacity:1}
.pe-ann .pe-cols{margin-top:18px}
.pe-ann .pe-cols h6{font-size:13px}
.pe-ann .pe-it{font-size:12.5px;gap:10px}.pe-ann .pe-it i{width:20px;height:20px;border-radius:5px}.pe-ann .pe-it em{font-size:10.5px}
.pe-ann .pe-it .act{margin-left:auto;font-size:11.5px;color:var(--pe-blue)}
.pe-kits{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:6px}
.pe-kits span{display:flex;flex-direction:column;gap:8px;font-size:12.5px}
.pe-kits i{display:block;height:58px;border-radius:8px}
.pe-keys{display:flex;flex-direction:column;gap:4px}
.pe-keys button{font:inherit;text-align:left;display:grid;grid-template-columns:28px 1fr;gap:10px;padding:14px;border:0;border-radius:12px;background:transparent;cursor:pointer;color:var(--p2-mute)}
.pe-keys b{width:22px;height:22px;border-radius:50%;box-shadow:inset 0 0 0 1.5px currentColor;display:grid;place-items:center;font-family:var(--p2-mono);font-size:11px;font-weight:400}
.pe-keys strong{display:block;font-size:15px;font-weight:500}.pe-keys small{display:none;margin-top:4px;font-size:13.5px;line-height:1.5;color:var(--p2-ink-soft)}
.pe-keys button[aria-pressed="true"]{background:var(--sp-sand);color:var(--p2-ink)}.pe-keys button[aria-pressed="true"] b{color:var(--pe-blue)}.pe-keys button[aria-pressed="true"] small{display:block}
@media(max-width:900px){.pe-ann{grid-template-columns:1fr}}
/* empty states */
.pe-opts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.pe-opt{display:flex;flex-direction:column;gap:12px}
.pe-opt .pe-lab.no{color:var(--pe-red)}.pe-opt .pe-lab.yes{color:var(--pe-green)}
.pe-card{background:#fff;border-radius:12px;padding:16px;min-height:170px;display:flex;flex-direction:column;gap:10px}
.pe-opt.rec .pe-card{box-shadow:0 0 0 1.5px var(--pe-blue)}
.pe-card h6{margin:0;font-size:13px;font-weight:500}
.pe-card .ill{flex:1;min-height:64px;border-radius:8px;background:linear-gradient(135deg,var(--pe-mint),var(--pe-lav))}
.pe-card .msg{font-size:12.5px;color:var(--p2-ink-soft);text-align:center}
.pe-card .msg.l{text-align:left;display:flex;align-items:center;gap:8px;color:var(--p2-ink)}.pe-card .msg.l .ico{width:18px;height:18px;color:var(--pe-green)}
.pe-card .pe-it{font-size:12.5px}.pe-card .pe-it i{width:20px;height:20px;border-radius:5px}.pe-card .pe-it em{font-size:10.5px}
.pe-opt p{margin:0;font-size:13.5px;line-height:1.5;color:var(--p2-ink-soft)}
@media(max-width:900px){.pe-opts{grid-template-columns:1fr}}
/* re-auth stepper */
.pe-flow{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:24px;align-items:stretch}
.pe-flow .scr2{background:var(--sp-sand);border-radius:18px;display:grid;place-items:center;padding:32px;min-height:380px}
.pe-flow .pe-win{width:100%;max-width:420px}
.pe-flow .pg{padding:28px;display:flex;flex-direction:column;gap:12px;min-height:220px}
.pe-flow .pg[hidden]{display:none}
.pe-flow .pg b{font-size:18px;font-weight:500}.pe-flow .pg p{margin:0;font-size:13.5px;color:var(--p2-ink-soft);line-height:1.5}
.pe-flow .fld{border:1px solid #dedbd5;border-radius:8px;padding:10px 12px;font-size:13.5px;color:var(--p2-ink-soft)}
.pe-flow .bt{align-self:flex-start;font-size:13.5px;padding:10px 18px;border-radius:99px;background:#141414;color:#fff}
.pe-flow .code{display:flex;gap:8px}.pe-flow .code i{width:38px;height:46px;border-radius:8px;border:1px solid #dedbd5;display:grid;place-items:center;font-style:normal;font-size:18px}
.pe-flow .code i.f{border-color:var(--pe-blue);color:var(--pe-ink)}
.pe-flow .ok{display:flex;align-items:center;gap:8px;font-size:13.5px;color:var(--pe-green)}.pe-flow .ok .ico{width:18px;height:18px}
.pe-flow .ln{height:7px;border-radius:7px;background:#efedea}.pe-flow .ln.s{width:60%}
.pe-flow .exit{margin-top:auto;font-size:12px;color:var(--p2-mute)}
@media(max-width:900px){.pe-flow{grid-template-columns:1fr}}
/* voice */
.pe-voice{width:100%;border-collapse:collapse;font-size:14.5px}
.pe-voice th{text-align:left;font-weight:400;font-family:var(--p2-mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--p2-mute);padding:0 16px 12px 0;border-bottom:1px solid rgba(0,0,0,.18)}
.pe-voice td{padding:16px 16px 16px 0;border-bottom:1px solid rgba(0,0,0,.1);vertical-align:top}
.pe-voice td:first-child{color:var(--p2-mute);width:22%}.pe-voice td:nth-child(2){width:26%;font-weight:500}
.pe-voice td:last-child q{font-size:15.5px;quotes:"“" "”"}
.pe-img3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:40px}
.pe-img3>div{display:flex;flex-direction:column;gap:12px}
.pe-img3 .v{aspect-ratio:4/3;border-radius:14px;overflow:hidden;position:relative}
.pe-img3 .v.photo{background:#d9d3c7 url("https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=700&q=70") center/cover}
.pe-img3 .v.il{background:linear-gradient(135deg,var(--pe-lav),var(--pe-mint));display:grid;place-items:center}
.pe-img3 .v.il span{width:46%;height:30%;border-radius:10px;background:#fff;box-shadow:0 0 0 1.5px var(--p2-ink);position:relative}
